window.KITAB_MBCL_DATA["ulangan"] = {"edition":"MBCL","book":{"id":"ulangan","nameBn":"দ্বিতীয় বিবরণ","chapters":34},"contentSha256":"15f2a02961f7a7f589a6ce23289831965355f655f350760d5cefa686da2dfac6","chapters":{"1":[{"heading":"তুর পাহাড় ছেড়ে যাওয়ার হুকুম","v":1,"ve":1,"vl":"1","bn":"মূসা জর্ডান নদীর পূর্ব দিকের মরুভূমিতে, অর্থাৎ আরবাতে সমস্ত বনি-ইসরাইলদের কাছে অনেক কথা বলেছিলেন। তিনি যেখানে সেই সব কথা বলেছিলেন সেই জায়গাটা ছিল সূফের সামনের দিকে। তার এক দিকে ছিল পারণ এবং অন্য দিকে ছিল তোফল, লাবন, হৎসেরোৎ ও দীষাহব।"},{"v":2,"ve":2,"vl":"2","bn":"হোরেব থেকে সেয়ীর পাহাড়ের রাস্তা ধরে কাদেশ-বর্ণেয় পর্যন্ত যেতে এগারো দিন লাগে।"},{"v":3,"ve":3,"vl":"3","bn":"মাবুদ বনি-ইসরাইলদের সম্বন্ধে মূসাকে যে সব নির্দেশ দিয়েছিলেন তা তিনি তাদের যাত্রার চল্লিশ বছরের এগারো মাসের পয়লা তারিখে তাদের কাছে প্রকাশ করেছিলেন।"},{"v":4,"ve":4,"vl":"4","bn":"আমোরীয়দের বাদশাহ্‌ সীহোনকে এবং ইদ্রিয়ী শহরে বাশন দেশের বাদশাহ্‌ উজকে হারিয়ে দেবার পরে তিনি তা প্রকাশ করেছিলেন। সীহোন রাজত্ব করতেন হিষ্‌বোনে এবং উজ রাজত্ব করতেন অষ্টারোতে।"},{"v":5,"ve":5,"vl":"5","bn":"শরীয়তের এই সব কথা মূসা জর্ডান নদীর পূর্ব দিকে মোয়াব দেশে বনি-ইসরাইলদের বুঝিয়ে বলতে লাগলেন। তিনি বললেন,"},{"v":6,"ve":6,"vl":"6","bn":"“আমাদের মাবুদ আল্লাহ্‌ তুর পাহাড়ে আমাদের বলেছিলেন, ‘এই পাহাড়ে তোমাদের অনেক দিন কেটে গেছে।"},{"v":7,"ve":7,"vl":"7","bn":"এখন তোমরা ছাউনি তুলে নিয়ে আমোরীয়দের পাহাড়ী এলাকা এবং তার আশেপাশের জায়গার লোকদের কাছে যাও। তারা আরবাতে, উঁচু পাহাড়ী এলাকায়, নীচের পাহাড়ী এলাকায়, নেগেভে এবং সাগরের কিনারায় বাস করে। এই জায়গাগুলো হল কেনানীয়দের দেশ সুদ্ধ লেবানন হয়ে মহানদী ফোরাত পর্যন্ত সম্পূর্ণ জায়গাটা।"},{"v":8,"ve":8,"vl":"8","bn":"দেখ, আমি ঐ জায়গাগুলো তোমাদের দিয়ে রেখেছি। আমি মাবুদ তোমাদের পূর্বপুরুষ ইব্রাহিম, ইসহাক, ইয়াকুব ও তাদের পরে তাদের বংশধরদের যে দেশ দেবার কসম খেয়েছিলাম তোমরা সেখানে গিয়ে সেই দেশ অধিকার কর।’"},{"heading":"নেতা নিয়োগ","v":9,"ve":9,"vl":"9","bn":"“সেই সময় আমি তোমাদের বলেছিলাম, ‘আমার একার পক্ষে তোমাদের বয়ে নিয়ে যাওয়া সম্ভব নয়।"},{"v":10,"ve":10,"vl":"10","bn":"তোমাদের মাবুদ আল্লাহ্‌ তোমাদের লোকসংখ্যা এত বাড়িয়ে দিয়েছেন যে, আজকে তোমরা আসমানের তারার মত অসংখ্য হয়ে উঠেছ।"},{"v":11,"ve":11,"vl":"11","bn":"তোমাদের পূর্বপুরুষদের মাবুদ আল্লাহ্‌ তোমাদের সংখ্যা আরও হাজার গুণ বাড়িয়ে দিন এবং তাঁর ওয়াদা অনুসারেই তিনি তোমাদের দোয়া করুন।"},{"v":12,"ve":12,"vl":"12","bn":"কিন্তু আমি একা কি করে তোমাদের সব ঝগড়া-বিবাদ মিটাবার ভার ও বোঝা বহন করব?"},{"v":13,"ve":13,"vl":"13","bn":"তোমরা তোমাদের প্রত্যেকটা গোষ্ঠী থেকে কয়েকজন করে জ্ঞানবান, বুদ্ধিমান ও অভিজ্ঞ লোক বেছে নাও; আমি তাদের উপর তোমাদের দেখাশোনার ভার দেব।’"},{"v":14,"ve":14,"vl":"14","bn":"“তোমরা তার জবাবে বলেছিলে, ‘আপনি যা বলছেন তা-ই করা ভাল।’"},{"v":15,"ve":15,"vl":"15","bn":"সেইজন্য আমি তোমাদের গোষ্ঠীগুলো থেকে জ্ঞানী ও অভিজ্ঞ সর্দারদের নিয়ে তোমাদের উপরে হাজারপতি, শতপতি, পঞ্চাশপতি, দশপতি এবং অন্যান্য কর্মচারী নিযুক্ত করেছিলাম।"},{"v":16,"ve":16,"vl":"16","bn":"এই সব বিচারকদের তখন আমি বলেছিলাম, ‘তোমরা ঝগড়া-বিবাদের সময়ে দু’পক্ষের কথা শুনে ন্যায়ভাবে বিচার করবে- সেই ঝগড়া ইসরাইলীয় ভাইদের মধ্যেই হোক কিংবা ইসরাইলীয় এবং ভিন্ন জাতির লোকদের মধ্যেই হোক।"},{"v":17,"ve":17,"vl":"17","bn":"বিচারের ব্যাপারে তোমরা কারও পক্ষ নেবে না এবং বড়-ছোট সবার কথাই শুনবে। বিচারের কাজটা আসলে আল্লাহ্‌র; তাই কোন মানুষকে তোমরা ভয় করবে না। যদি কোন বিচার তোমাদের কাছে শক্ত বলে মনে হয় তবে তোমরা তা আমার কাছে নিয়ে আসবে, আমি সেই বিচার করব।’"},{"v":18,"ve":18,"vl":"18","bn":"তোমাদের যা করতে হবে তা-ও আমি তখন তোমাদের বলে দিয়েছিলাম।"},{"heading":"গোয়েন্দা পাঠানো","v":19,"ve":19,"vl":"19","bn":"“এর পর আমাদের মাবুদ আল্লাহ্‌র হুকুমে আমরা হোরেব পাহাড় ছেড়ে আমোরীয়দের পাহাড়ী এলাকার দিকে রওনা হলাম। কত বড় এবং কত ভয়ানক মরুভূমির মধ্য দিয়ে আমাদের যেতে হয়েছিল তা তোমরা দেখেছ। এইভাবে আমরা কাদেশ-বর্ণেয়তে গিয়ে পৌঁছালাম।"},{"v":20,"ve":20,"vl":"20","bn":"তারপর আমি তোমাদের বললাম, ‘তোমরা আমোরীয়দের পাহাড়ী এলাকাতে এসে গেছ; এটা আমাদের মাবুদ আল্লাহ্‌ আমাদের দিতে যাচ্ছেন।"},{"v":21,"ve":21,"vl":"21","bn":"দেখ, তোমাদের মাবুদ আল্লাহ্‌র দেওয়া গোটা দেশটাই তোমাদের সামনে রয়েছে। তোমাদের পূর্বপুরুষদের মাবুদ আল্লাহ্‌র কথামত তোমরা গিয়ে দেশটা দখল কর। তোমরা ভয় কোরো না, নিরাশও হয়ো না।’"},{"v":22,"ve":22,"vl":"22","bn":"“তখন তোমরা সবাই এসে আমাকে বললে, ‘কয়েকজন লোককে আগেই পাঠিয়ে দেওয়া হোক, যাতে তারা দেশটা দেখে এসে আমাদের বলতে পারে কোন্‌ পথে আমাদের সেখানে যেতে হবে এবং কোন্‌ কোন্‌ শহর আমাদের সামনে পড়বে।’"},{"v":23,"ve":23,"vl":"23","bn":"“তোমাদের কথাটা আমার কাছে ভালই মনে হল। তাই আমি তোমাদের প্রত্যেক গোষ্ঠী থেকে একজন করে মোট বারোজন লোক বেছে নিলাম।"},{"v":24,"ve":24,"vl":"24","bn":"তারা তোমাদের ছেড়ে ঐ পাহাড়ী এলাকায় উঠে গেল এবং ইষ্কোল উপত্যকায় গিয়ে ভাল করে সব কিছু দেখে আসল।"},{"v":25,"ve":25,"vl":"25","bn":"তারা সেই দেশের কিছু ফল সংগে করে নিয়ে এসে আমাদের বলল, ‘আমাদের মাবুদ আল্লাহ্‌ যে দেশটা আমাদের দিতে যাচ্ছেন তা সত্যিই চমৎকার।’"},{"v":26,"ve":26,"vl":"26","bn":"“কিন্তু তোমরা সেই দেশে যেতে চাইলে না। তোমরা তোমাদের মাবুদ আল্লাহ্‌র হুকুমের বিরুদ্ধে দাঁড়ালে।"},{"v":27,"ve":27,"vl":"27","bn":"তোমরা নিজেদের তাম্বুর মধ্যে বক্‌বক্‌ করতে শুরু করলে এবং বললে, ‘মাবুদ আমাদের ঘৃণা করেন। সেইজন্য আমোরীয়দের হাতে তুলে দিয়ে ধ্বংস করে ফেলবার জন্যই তিনি আমাদের মিসর দেশ থেকে বের করে এনেছেন।"},{"v":28,"ve":28,"vl":"28","bn":"আমরা কি করে সেখানে যাই? আমাদের ভাইয়েরাই আমাদের মন ভেংগে দিয়েছে। তারা বলেছে, ওখানকার লোকগুলো তাদের চেয়ে শক্তিশালী ও লম্বা; তাদের শহরগুলোও বড় বড় এবং তাদের চারদিকে রয়েছে আকাশ-ছোঁয়া দেয়াল। সেখানে তারা অনাকীয়দেরও দেখেছে।’"},{"v":29,"ve":29,"vl":"29","bn":"“তা শুনে আমি তোমাদের বললাম, ‘তোমরা ভয় পেয়ো না, ঐ লোকদের ভয় কোরো না।"},{"v":30,"ve":31,"vl":"30-31","bn":"তোমাদের মাবুদ আল্লাহ্‌ই তোমাদের আগে আগে যাচ্ছেন। তিনি তোমাদের চোখের সামনে মিসর দেশে এবং মরুভূমিতে যেমন তোমাদের হয়ে যুদ্ধ করেছিলেন এখনও তেমনি করবেন। তোমরা তো দেখেছ, পিতা যেমন ছেলেকে কোলে করে নিয়ে যান তেমনি করে এই জায়গায় না পৌঁছানো পর্যন্ত তোমাদের মাবুদ আল্লাহ্‌ও সারাটা পথ তোমাদের বয়ে নিয়ে এসেছেন।’"},{"v":32,"ve":32,"vl":"32","bn":"তবুও তোমরা তোমাদের মাবুদ আল্লাহ্‌র উপর ভরসা কর নি।"},{"v":33,"ve":33,"vl":"33","bn":"তিনিই তো তাম্বু ফেলবার জায়গা ঠিক করবার জন্য এবং পথ দেখিয়ে তোমাদের নিয়ে যাবার জন্য রাতে আগুনের মধ্যে ও দিনে মেঘের মধ্যে থেকে যাত্রাপথে তোমাদের আগে আগে গিয়েছিলেন।"},{"v":34,"ve":36,"vl":"34-36","bn":"“তোমাদের কথা শুনে মাবুদ রেগে গিয়ে কসম খেয়ে বলেছিলেন, ‘যে চমৎকার দেশটা তোমাদের পূর্বপুরুষদের দেবার কসম আমি খেয়েছিলাম একমাত্র যিফুন্নির ছেলে কালুত ছাড়া এখনকার সেই অসৎ লোকদের মধ্যে একজনও তা দেখতে পাবে না। কেবল কালুত তা দেখবে। সে পুরোপুরি ভাবে মাবুদের কথামত চলেছে বলে সে তা দেখবে এবং যেখানে সে পা দিয়ে এসেছে সেটাই আমি তাকে ও তার বংশধরদের দেব।’"},{"v":37,"ve":37,"vl":"37","bn":"“তোমাদের দরুন মাবুদ আমার উপরও রেগে গিয়ে বলেছিলেন, ‘ঐ দেশে তোমারও ঢোকা হবে না,"},{"v":38,"ve":38,"vl":"38","bn":"কিন্তু তোমার সাহায্যকারী নূনের ছেলে ইউসা ঢুকবে। তুমি ইউসাকে উৎসাহ দাও, কারণ সে-ই দেশটা দখল করে বনি-ইসরাইলদের অধিকার হিসাবে দেবে।"},{"v":39,"ve":39,"vl":"39","bn":"যে সব ছেলেমেয়েদের বন্দী করে নিয়ে যাওয়া হবে বলে তোমরা বলেছিলে তোমাদের সেই সব ছেলেমেয়েরা, যাদের নেকী-বদীর জ্ঞান এখনও হয় নি, তারাই সেই দেশে ঢুকবে। আমি দেশটা তাদেরই দেব এবং তারা তা দখল করবে।"},{"v":40,"ve":40,"vl":"40","bn":"এখন তোমরা পিছন ফিরে আকাবা উপসাগরের পথ ধরে মরুভূমির দিকে রওনা হয়ে যাও।’"},{"v":41,"ve":41,"vl":"41","bn":"“এই কথা শুনে তোমরা বলেছিলে, ‘আমরা মাবুদের বিরুদ্ধে গুনাহ্‌ করেছি। এখন আমাদের মাবুদ আল্লাহ্‌র হুকুম অনুসারে আমরা গিয়ে যুদ্ধ করব।’ এই বলে তোমরা সবাই অস্ত্রশস্ত্র নিলে। তোমরা ভেবেছিলে পাহাড়ী এলাকায় উঠে যাওয়া খুব সহজ।"},{"v":42,"ve":42,"vl":"42","bn":"“কিন্তু মাবুদ আমাকে বললেন, ‘তুমি তাদের বলে দাও যেন তারা যুদ্ধ করবার জন্য ওখানে উঠে না যায় কারণ আমি তাদের সংগে থাকব না; তাই তারা শত্রুদের কাছে হেরে যাবে।’"},{"v":43,"ve":43,"vl":"43","bn":"“আমি তোমাদের সেই কথা জানালাম কিন্তু তোমরা তাতে কান দিলে না। তোমরা মাবুদের হুকুমের বিরুদ্ধে গিয়ে বুক ফুলিয়ে পাহাড়ী এলাকায় উঠে গেলে।"},{"v":44,"ve":44,"vl":"44","bn":"তা দেখে যে সব আমোরীয়রা ঐ পাহাড়ী এলাকায় বাস করত তারা তোমাদের বিরুদ্ধে বের হয়ে আসল। এক ঝাঁক মৌমাছির মত তারা তোমাদের তাড়া করল আর সেয়ীরের মধ্যে হর্মা পর্যন্ত তোমাদের মারতে মারতে নিয়ে গেল।"},{"v":45,"ve":45,"vl":"45","bn":"তোমরা ফিরে এসে মাবুদের কাছে কাঁদতে লাগলে, কিন্তু তিনি তোমাদের কান্না শুনলেন না; তিনি কান বন্ধ করে রইলেন।"},{"v":46,"ve":46,"vl":"46","bn":"এইভাবে তোমরা কাদেশে অনেক দিন রইলে এবং সেখানেই তোমাদের অনেক দিন কেটে গেল।"}],"2":[{"heading":"মরুভূমিতে বনি-ইসরাইলরা","v":1,"ve":1,"vl":"1","bn":"“মাবুদ আমাকে যেমন নির্দেশ দিয়েছিলেন সেইভাবে আমরা তারপর পিছন ফিরে আকাবা উপসাগরের পথ ধরে মরুভূমির দিকে রওনা হলাম। সেয়ীরের পাহাড়ী এলাকা ঘুরে যেতে আমাদের অনেক দিন কেটে গেল।"},{"v":2,"ve":2,"vl":"2","bn":"তারপর মাবুদ আমাকে বললেন,"},{"v":3,"ve":3,"vl":"3","bn":"‘তোমরা অনেক দিন ধরে এই পাহাড়ী এলাকায় ঘুরছ; এইবার উত্তর দিকে ফের।’"},{"v":4,"ve":4,"vl":"4","bn":"তারপর তিনি আমাকে তোমাদের বলতে বললেন, ‘তোমাদের ভাই সেয়ীরের বাসিন্দা ইসের বংশধরদের রাজ্যের মধ্য দিয়ে এখন তোমাদের যেতে হবে। তোমাদের দেখে তারা ভয় পাবে কিন্তু তোমরা খুব সাবধান থেকো।"},{"v":5,"ve":5,"vl":"5","bn":"তোমরা ইসের বংশধরদের যুদ্ধের উসকানি দেবে না, কারণ আমি তাদের দেশের কোন অংশই তোমাদের দেব না, এমন কি, পা রাখবার জায়গা পর্যন্ত না। আমি সেয়ীরের এই পাহাড়ী এলাকা ইস্‌কে তার নিজের দেশ হিসাবে দিয়েছি।"},{"v":6,"ve":6,"vl":"6","bn":"তাদের কাছ থেকে খাবার ও পানি তোমাদের টাকা দিয়ে কিনে খেতে হবে।’"},{"v":7,"ve":7,"vl":"7","bn":"“তোমাদের মাবুদ আল্লাহ্‌ সব কাজেই তোমাদের দোয়া করেছেন। এই মস্ত বড় মরুভূমির মধ্য দিয়ে যাবার সময়ে তিনি তোমাদের দেখাশোনা করেছেন। এই চল্লিশটা বছর তোমাদের মাবুদ আল্লাহ্‌ তোমাদের সংগেই থেকেছেন আর তোমাদের কোন কিছুর অভাব হয় নি।"},{"v":8,"ve":8,"vl":"8","bn":"“কাজেই আমরা আমাদের ভাই সেয়ীরের বাসিন্দা ইসের বংশধরদের ছেড়ে চলে আসলাম। আরবার যে পথটা এলৎ ও ইৎসিয়োন-গেবর থেকে বের হয়ে এসেছে সেই পথ ছেড়ে আমরা মোয়াবের মরুভূমির পথ ধরে চলতে লাগলাম।"},{"v":9,"ve":9,"vl":"9","bn":"তারপর মাবুদ আমাকে বললেন, ‘তোমরা মোয়াবীয়দের বিরক্ত কোরো না কিংবা যুদ্ধের উসকানি দিয়ো না, কারণ তাদের দেশের কোন অংশই আমি তোমাদের দেব না। আমি সম্পত্তি হিসাবে আর্‌ শহরটা লুতের বংশধরদের দিয়েছি।’ ”"},{"v":10,"ve":10,"vl":"10","bn":"(আগে এমীয়রা ঐ এলাকায় বাস করত। এমীয় জাতির লোকেরা ছিল শক্তিশালী, সংখ্যায় অনেক এবং অনাকীয়দের মত লম্বা।"},{"v":11,"ve":11,"vl":"11","bn":"অনাকীয়দের মত এমীয়দেরও রফায়ীয় বলা হত কিন্তু মোয়াবীয়রা তাদের বলত এমীয়।"},{"v":12,"ve":12,"vl":"12","bn":"সেয়ীরে হোরীয়রা বাস করত, কিন্তু পরে ইসের বংশধরেরা তাদের সেখান থেকে তাড়িয়ে দিয়েছিল। মাবুদ সম্পত্তি হিসাবে বনি-ইসরাইলদের যে দেশ দিয়েছিলেন সেখানে তারা যা করেছিল ইসের বংশধরেরাও ঠিক তা-ই করল; তারা হোরীয়দের ধ্বংস করে দিয়ে তাদের জায়গায় নিজেরা বাস করতে লাগল।)"},{"v":13,"ve":13,"vl":"13","bn":"“তারপর মাবুদ বললেন, ‘এখন তোমরা উঠে সেরদ উপত্যকা পার হয়ে যাও।’ আর আমরা সেটা পার হয়ে আসলাম।"},{"v":14,"ve":14,"vl":"14","bn":"কাদেশ-বর্ণেয় ছেড়ে সেরদ উপত্যকা পার হয়ে আসতে আমাদের আটত্রিশ বছর কেটে গিয়েছিল। কাদেশ-বর্ণেয় ছেড়ে আসবার আগে ছাউনিতে যে সব সৈন্য ছিল তারা সবাই এই আটত্রিশ বছরের মধ্যে মাবুদের কসম খেয়ে বলা কথা অনুসারে মারা গিয়েছিল।"},{"v":15,"ve":15,"vl":"15","bn":"ছাউনি থেকে তাদের একেবারে ধ্বংস করে ফেলবার জন্য মাবুদ তাদের বিরুদ্ধে কাজ করছিলেন, যে পর্যন্ত না তারা শেষ হয়ে যায়।"},{"v":16,"ve":18,"vl":"16-18","bn":"“সেই সব সৈন্যেরা মারা যাওয়ার পরে মাবুদ আমাকে বলেছিলেন, ‘আজ তোমাদের আর্‌ শহরের পাশ দিয়ে মোয়াব দেশের সীমানা ছেড়ে যেতে হবে।"},{"v":19,"ve":19,"vl":"19","bn":"কিন্তু তোমরা যখন অম্মোনীয়দের কাছে গিয়ে পৌঁছাবে তখন তাদের বিরক্ত করবে না বা যুদ্ধের উসকানি দেবে না, কারণ অম্মোনীয়দের দেশের কোন অংশই আমি তোমাদের দেব না। লুতের বংশধরদের আমি সেটা সম্পত্তি হিসাবে দিয়ে দিয়েছি।’ ”"},{"v":20,"ve":20,"vl":"20","bn":"ঐ দেশটাকে রফায়ীদের দেশ বলেও মনে করা হত, কারণ সেখানে তারা আগে বাস করত; অম্মোনীয়রা তাদের সম্‌সুম্মীয় জাতির লোক বলত।"},{"v":21,"ve":21,"vl":"21","bn":"রফায়ীয়রা শক্তিশালী এবং সংখ্যায় অনেক ছিল। তারা ছিল অনাকীয়দের মত লম্বা। মাবুদ অম্মোনীয়দের দিয়ে তাদের ধ্বংস করে ফেলেছিলেন; অম্মোনীয়রা রফায়ীয়দের তাড়িয়ে দিয়ে তাদের জায়গায় বাস করছিল।"},{"v":22,"ve":22,"vl":"22","bn":"মাবুদ ইসের বংশধরদের ব্যাপারেও সেই একই কাজ করেছিলেন। তিনি তাদের দিয়ে হোরীয়দের ধ্বংস করেছিলেন। তারা হোরীয়দের তাড়িয়ে দিয়ে তাদের জায়গা সেয়ীরে আজও বাস করছে।"},{"v":23,"ve":23,"vl":"23","bn":"ক্রীট থেকে ক্রীটীয়রা এসে অব্বীয়দের ধ্বংস করে দিয়ে তাদের জায়গায় বাস করছিল। অব্বীয়রা তখন গাজা পর্যন্ত সমস্ত গ্রামে বাস করত।"},{"v":24,"ve":24,"vl":"24","bn":"“তারপর মাবুদ বলেছিলেন, ‘তোমরা বের হয়ে পড় এবং অর্ণোন নদী পার হয়ে যাও। দেখ, আমি হিষ্‌বোনের আমোরীয় বাদশাহ্‌ সীহোন ও তার দেশ তোমাদের হাতে দিয়ে দিয়েছি। তোমরা তার দেশটা দখল করতে শুরু করে তাকে যুদ্ধে নামতে বাধ্য কর।"},{"v":25,"ve":25,"vl":"25","bn":"আজ থেকে আমি দুনিয়ার সমস্ত জাতির মধ্যে তোমাদের সম্বন্ধে একটা ভয়ের ভাব ও কাঁপুনি ধরাতে শুরু করব। তারা তোমাদের কথা শুনলে কাঁপতে থাকবে এবং তোমাদের দরুন তাদের মনে ভীষণ দুশ্চিন্তা জাগবে।’"},{"heading":"হিষ্‌বোনের বাদশাহ্‌ সীহোনের পরাজয়","v":26,"ve":26,"vl":"26","bn":"“এর পর আমি শান্তি বজায় রাখবার উদ্দেশ্যে কদেমোৎ মরুভূমি থেকে হিষ্‌বোনের বাদশাহ্‌ সীহোনের কাছে বলে পাঠালাম,"},{"v":27,"ve":27,"vl":"27","bn":"‘আপনার দেশের মধ্য দিয়ে আমাদের যেতে দিন। আমরা ডানে-বাঁয়ে না গিয়ে সদর রাস্তা ধরেই চলে যাব।"},{"v":28,"ve":29,"vl":"28-29","bn":"আপনি টাকা নিয়ে আমাদের খাবার ও পানি দিন। আমাদের মাবুদ আল্লাহ্‌ যে দেশ আমাদের দিতে যাচ্ছেন জর্ডান নদী পার হয়ে সেখানে না পৌঁছানো পর্যন্ত আপনি কেবল আমাদের পায়ে হেঁটে আপনার দেশটা পার হয়ে যেতে দিন। সেয়ীরের বাসিন্দা ইসের বংশধরেরা এবং আর্‌ শহরের বাসিন্দা মোয়াবীয়রাও আমাদের পার হয়ে যেতে দিয়েছে।’"},{"v":30,"ve":30,"vl":"30","bn":"কিন্তু হিষ্‌বোনের বাদশাহ্‌ সীহোন তাতে রাজী হলেন না। তোমাদের মাবুদ আল্লাহ্‌ তাঁর মন কঠিন করেছিলেন ও অন্তর একগুঁয়েমিতে ভরে দিয়েছিলেন যাতে তিনি তোমাদের হাতে পড়েন, আর এখন তা-ই ঘটেছে।"},{"v":31,"ve":31,"vl":"31","bn":"“পরে মাবুদ আমাকে বললেন, ‘দেখ, সীহোন ও তার রাজ্য আমি তোমার হাতে তুলে দিতে শুরু করেছি। তুমি এখন গিয়ে তার দেশটা জয় করবার কাজে হাত দাও এবং সেখানে বাস করতে শুরু কর।’"},{"v":32,"ve":33,"vl":"32-33","bn":"“এর পর যখন সীহোন তাঁর সৈন্য-সামন্ত নিয়ে বের হয়ে যহসে আমাদের সংগে যুদ্ধ করতে আসলেন তখন আমাদের মাবুদ আল্লাহ্‌ তাঁকে আমাদের হাতে এনে দিলেন। আমরা তাঁকে, তাঁর সব ছেলেদের এবং তাঁর সৈন্যদলকে ধ্বংস করলাম।"},{"v":34,"ve":34,"vl":"34","bn":"সেই সময়ে আমরা তাঁর সমস্ত গ্রাম ও শহর দখল করে নিলাম এবং তাদের পুরুষ, স্ত্রীলোক ও ছেলেমেয়েদের একেবারে ধ্বংস করে ফেললাম; তাদের কাউকেই আমরা বাঁচিয়ে রাখি নি।"},{"v":35,"ve":35,"vl":"35","bn":"কিন্তু পশুপাল এবং শহর থেকে লুট করা জিনিসপত্র আমরা নিজেদের জন্য নিয়ে আসলাম।"},{"v":36,"ve":36,"vl":"36","bn":"অর্ণোন উপত্যকার কিনারায় অরোয়ের শহর এবং সেই উপত্যকার মধ্যেকার গ্রামটা থেকে শুরু করে গিলিয়দ পর্যন্ত এমন কোন শক্তিশালী গ্রাম বা শহর রইল না যা আমরা জয় করে নিতে পারি নি। আমাদের মাবুদ আল্লাহ্‌ সেগুলো সবই আমাদের হাতে তুলে দিয়েছিলেন।"},{"v":37,"ve":37,"vl":"37","bn":"কেবল অম্মোনীয়দের জায়গা, যব্বোক নদীর কিনারার জায়গা, পাহাড়ের মধ্যেকার জায়গা এবং অন্যান্য যে সব জায়গায় যেতে তিনি নিষেধ করেছিলেন, সেই সব জায়গায় তোমরা যাও নি।"}],"3":[{"heading":"বাশনের বাদশাহ্‌ উজের পরাজয়","v":1,"ve":1,"vl":"1","bn":"“এর পর আমরা ঘুরে বাশন দেশের দিকে যাওয়ার রাস্তা ধরে এগিয়ে চললাম। আমাদের সংগে যুদ্ধ করবার জন্য বাশনের বাদশাহ্‌ উজ তাঁর সমস্ত সৈন্য-সামন্ত নিয়ে বের হয়ে ইদ্রিয়ী শহরে আসলেন।"},{"v":2,"ve":2,"vl":"2","bn":"তখন মাবুদ আমাকে বললেন, ‘তুমি তাকে ভয় কোরো না, কারণ তাকে ও তার দেশ ও সৈন্য-সামন্ত আমি তোমার হাতে দিয়ে দিয়েছি। তুমি হিষ্‌বোনে বাসকারী আমোরীয়দের বাদশাহ্‌ সীহোনের অবস্থা যা করেছিলে এর অবস্থাও তা-ই করবে।’"},{"v":3,"ve":3,"vl":"3","bn":"“এইভাবে আমাদের মাবুদ আল্লাহ্‌ বাশনের বাদশাহ্‌ উজ ও তাঁর সমস্ত সৈন্য-সামন্তকে আমাদের হাতে দিয়ে দিয়েছিলেন। আমরা তাদের সবাইকে হত্যা করেছিলাম; কাউকেই বাঁচিয়ে রাখি নি।"},{"v":4,"ve":4,"vl":"4","bn":"সেই সময় আমরা তাঁর সব গ্রাম ও শহরগুলো নিয়ে নিয়েছিলাম। তাঁর ষাটটা শহরের সবগুলোই আমরা দখল করে নিয়েছিলাম; একটাও বাদ রাখি নি। গোটা অর্গোব এলাকাটা, অর্থাৎ বাশনের মধ্যে উজের গোটা রাজ্যটা আমরা দখল করে নিয়েছিলাম।"},{"v":5,"ve":5,"vl":"5","bn":"এই সব শহরগুলো উঁচু উঁচু দেয়াল দিয়ে ঘেরা ছিল আর তাতে ছিল দরজা আর হুড়কা। অনেকগুলো দেয়াল ছাড়া গ্রামও সেখানে ছিল।"},{"v":6,"ve":6,"vl":"6","bn":"আমরা সেই সব গ্রাম ও শহর সম্পূর্ণভাবে ধ্বংস করে দিয়েছিলাম। হিষ্‌বোনের বাদশাহ্‌ সীহোনের প্রতি আমরা যেমন করেছিলাম তেমনি করে তাদের পুরুষ, স্ত্রীলোক ও ছেলেমেয়ে এবং প্রত্যেকটা গ্রাম ও শহর আমরা একেবারে ধ্বংস করে দিয়েছিলাম।"},{"v":7,"ve":7,"vl":"7","bn":"কিন্তু সেখান থেকে সমস্ত পশুপাল এবং লুট করে আনা জিনিসপত্র আমরা নিজেদের জন্য নিয়ে এসেছিলাম।"},{"v":8,"ve":8,"vl":"8","bn":"“সেই সময় আমরা অর্ণোন নদী থেকে হর্মোণ পাহাড় পর্যন্ত জর্ডান নদীর পূর্ব দিকের এলাকাটা এই দু’জন আমোরীয় বাদশাহ্‌র হাত থেকে নিয়ে নিয়েছিলাম।"},{"v":9,"ve":9,"vl":"9","bn":"(সিডনীয়রা হর্মোণকে সিরিয়োণ বলে আর আমোরীয়রা বলে সনীর।)"},{"v":10,"ve":10,"vl":"10","bn":"ঐ মালভূমির সমস্ত গ্রাম ও শহর, সব গিলিয়দ এলাকা এবং বাশনের বাদশাহ্‌ উজের রাজ্যের সল্‌খা ও ইদ্রিয়ী শহর পর্যন্ত গোটা বাশন দেশটা আমরা দখল করে নিয়েছিলাম।"},{"v":11,"ve":11,"vl":"11","bn":"রফায়ীয়দের বাকী লোকদের মধ্যে কেবল বাশনের বাদশাহ্‌ উজই বেঁচে ছিলেন। তাঁর লোহার তৈরী শোবার খাটটা ছিল লম্বায় প্রমাণ হাতের নয় হাত আর চওড়ায় চার হাত। ওটা এখনও অম্মোনীয়দের রব্বা শহরে আছে।"},{"heading":"জায়গা-জমি ভাগ","v":12,"ve":12,"vl":"12","bn":"“আমাদের অধিকার করা জায়গা থেকে আমি তখন অর্ণোন নদীর কাছে অরোয়ের শহরের বাইরে উত্তর দিকের এলাকাটা এবং গিলিয়দের পাহাড়ী এলাকার অর্ধেক ও সেখানকার সব গ্রাম ও শহর রূবেণ ও গাদ-গোষ্ঠীর লোকদের দিলাম।"},{"v":13,"ve":13,"vl":"13","bn":"গিলিয়দ দেশের বাকী অংশ এবং বাদশাহ্‌ উজের গোটা বাশন রাজ্যটা আমি মানশা-গোষ্ঠীর অর্ধেক লোককে দিলাম। “বাশনের মধ্যেকার সমস্ত অর্গোব এলাকাটাকে রফায়ীদের দেশ বলা হত।"},{"v":14,"ve":14,"vl":"14","bn":"যায়ীর নামে মানশার এক বংশধর গশূরীয় ও মাখাথীয়দের সীমানা পর্যন্ত গোটা অর্গোব এলাকাটা দখল করে নিজের নাম অনুসারে তার নাম রেখেছিল। তাই এখন বাশনকে হব্বোৎ-যায়ীর বলা হয়ে থাকে।"},{"v":15,"ve":15,"vl":"15","bn":"“আমি মাখীরকে গিলিয়দ এলাকাটা দিলাম।"},{"v":16,"ve":16,"vl":"16","bn":"কিন্তু গিলিয়দ থেকে অর্ণোন উপত্যকার মাঝখানের সীমারেখাটা পর্যন্ত সমস্ত জায়গা এবং সেখান থেকে অম্মোনীয়দের সীমানা যব্বোক নদী পর্যন্ত আমি রূবেণ ও গাদ-গোষ্ঠীর লোকদের দিলাম।"},{"v":17,"ve":17,"vl":"17","bn":"পশ্চিম দিকে তাদের শেষ সীমানা ছিল আরবার জর্ডান নদীর যে অংশটা গালীল সাগর থেকে পিস্‌গা পাহাড়শ্রেণীর ঢালু অংশের নীচে আরবার সমুদ্র, অর্থাৎ মরু-সাগর পর্যন্ত চলে গেছে সেই অংশটা।"},{"v":18,"ve":18,"vl":"18","bn":"“তারপর আমি তাদের বললাম, ‘তোমাদের মাবুদ আল্লাহ্‌ এই জায়গাটা তোমাদের দখল করবার জন্য দিয়েছেন। কিন্তু তোমাদের মধ্যে যাদের গায়ে জোর আছে সেই সব লোকদের যুদ্ধের জন্য তৈরী হয়ে ইসরাইলীয় ভাইদের আগে আগে নদী পার হয়ে যেতে হবে।"},{"v":19,"ve":19,"vl":"19","bn":"তবে তোমাদের যে সব গ্রাম ও শহর দেওয়া হল সেখানে তোমাদের স্ত্রী, ছেলেমেয়ে আর পশুপাল রেখে যেতে পারবে। আমি জানি তোমাদের পশু অনেক।"},{"v":20,"ve":20,"vl":"20","bn":"মাবুদ যতদিন পর্যন্ত তোমাদের মত করে তোমাদের ভাইদেরও বিশ্রামের সুযোগ না দেন এবং জর্ডানের ওপারে যে দেশটা তোমাদের মাবুদ আল্লাহ্‌ তাদের দিতে যাচ্ছেন তা তারা অধিকার না করে ততদিন পর্যন্ত তোমাদের যুদ্ধ করে যেতে হবে। তার পরে এই যে জায়গা-জমি তোমাদের দেওয়া হল এখানে তোমরা ফিরে আসতে পারবে।’"},{"heading":"মূসাকে জর্ডান নদী পার হতে দেবার অস্বীকৃতি","v":21,"ve":21,"vl":"21","bn":"“সেই সময় আমি ইউসাকে বললাম, ‘তোমাদের মাবুদ আল্লাহ্‌ এই দু’জন বাদশাহ্‌র অবস্থা কি করেছেন তা তো তুমি নিজের চোখেই দেখেছ। তোমরা যেখানে যাচ্ছ সেখানকার সব রাজ্যগুলোর অবস্থাও মাবুদ তা-ই করবেন।"},{"v":22,"ve":22,"vl":"22","bn":"তোমরা তাদের ভয় কোরো না; তোমাদের মাবুদ আল্লাহ্‌ নিজে তোমাদের হয়ে যুদ্ধ করবেন।’"},{"v":23,"ve":23,"vl":"23","bn":"“সেই সময় আমি মাবুদকে মিনতি করে বলেছিলাম,"},{"v":24,"ve":24,"vl":"24","bn":"‘হে আল্লাহ্‌ মালিক, তুমি যে কত মহান এবং শক্তিশালী তা তোমার গোলামকে দেখাতে শুরু করেছ। বেহেশতে বা দুনিয়াতে কোন্‌ দেবতা আছে যে, তুমি যে সব কাজ করেছ তা করতে পারে এবং তুমি যে শক্তি দেখিয়েছ তা দেখাতে পারে?"},{"v":25,"ve":25,"vl":"25","bn":"জর্ডান নদী পার হয়ে গিয়ে ঐ চমৎকার দেশটা, অর্থাৎ ঐ পাহাড়ী দেশটা আর লেবানন আমাকে দেখতে দাও।’"},{"v":26,"ve":26,"vl":"26","bn":"“কিন্তু তোমাদের দরুন মাবুদ আমার উপর বিরক্ত হওয়াতে আমার কথা তিনি শুনলেন না। তিনি বললেন, ‘যথেষ্ট হয়েছে। এই বিষয়ে আমাকে আর বোলো না।"},{"v":27,"ve":27,"vl":"27","bn":"তুমি পিস্‌গার চূড়ায় উঠে উত্তর-দক্ষিণ ও পূর্ব-পশ্চিমে চেয়ে দেখ। জর্ডান নদী পার হয়ে যখন তোমার যাওয়া হবে না তখন নিজের চোখে দেশটা একবার দেখে নাও।"},{"v":28,"ve":28,"vl":"28","bn":"ইউসাকে কি করতে হবে তা তুমি তাকে বলে দাও; তাকে উৎসাহ ও সাহস দাও, কারণ সে-ই আগে আগে গিয়ে লোকদের পার করে নিয়ে যাবে এবং যে দেশটা তুমি দেখতে যাচ্ছ তা তাদের দিয়ে অধিকার করাবে।’"},{"v":29,"ve":29,"vl":"29","bn":"সেইজন্য আমরা বৈৎ-পিয়োরের উল্টা দিকের উপত্যকায় থেকে গেলাম।"}],"4":[{"heading":"বাধ্যতা সম্বন্ধে হুকুম","v":1,"ve":1,"vl":"1","bn":"“বনি-ইসরাইলরা, আমি তোমাদের যে সব নিয়ম ও শরীয়ত শিক্ষা দিতে যাচ্ছি তা তোমরা এখন শোন। এগুলো তোমাদের মেনে চলতে হবে যাতে তোমরা বেঁচে থাক এবং তোমাদের পূর্বপুরুষদের মাবুদ আল্লাহ্‌ যে দেশ তোমাদের দিতে যাচ্ছেন সেখানে গিয়ে তা অধিকার করে নিতে পার।"},{"v":2,"ve":2,"vl":"2","bn":"আমি তোমাদের যে হুকুম দিচ্ছি তার সংগে কিছু যোগ কোরো না এবং তা থেকে কিছু বাদও দিয়ো না। তোমাদের মাবুদ আল্লাহ্‌র যে সব হুকুম আমি তোমাদের দিচ্ছি তা তোমরা মেনে চলবে।"},{"v":3,"ve":3,"vl":"3","bn":"“মাবুদ বাল-পিয়োরে যা করেছিলেন তা তো তোমরা নিজের চোখেই দেখেছ। তোমাদের মধ্যে যারা পিয়োরের বাল-দেবতার পূজা করেছিল তোমাদের মাবুদ আল্লাহ্‌ তাদের প্রত্যেককে তোমাদের মধ্য থেকে ধ্বংস করেছেন,"},{"v":4,"ve":4,"vl":"4","bn":"কিন্তু তোমরা যারা তোমাদের মাবুদ আল্লাহ্‌কে আঁকড়ে ধরেছিলে, তোমরা সবাই এখনও বেঁচে আছ।"},{"v":5,"ve":5,"vl":"5","bn":"“আমার মাবুদ আল্লাহ্‌র হুকুম মেনে আমি তোমাদের নিয়ম ও শরীয়ত শিক্ষা দিয়েছি, যাতে যে দেশ তোমরা অধিকার করতে যাচ্ছ সেই দেশে তা পালন করতে পার। তোমরা এই সব যত্নের সংগে পালন করবে।"},{"v":6,"ve":6,"vl":"6","bn":"এগুলো পালন করবার মধ্য দিয়ে অন্যান্য জাতির লোকদের সামনে তোমাদের জ্ঞান ও বুদ্ধি প্রকাশ পাবে। তারা এই সব নিয়মের বিষয় শুনে বলবে, ‘জাতি হিসাবে এরা সত্যিই মহান এবং জ্ঞানী ও বুদ্ধিমান।’"},{"v":7,"ve":7,"vl":"7","bn":"এমন আর কোন্‌ মহান জাতি আছে যাদের দেব-দেবী তাদের কাছে থাকে, যেমন করে আমাদের মাবুদ আল্লাহ্‌কে ডাকলে তাঁকে কাছে পাওয়া যায়?"},{"v":8,"ve":8,"vl":"8","bn":"এমন আর কোন্‌ মহান জাতি আছে যাদের নিয়ম ও শরীয়ত তোমাদের কাছে আজকে আমার দেওয়া নিয়ম-কানুনের মত ন্যায়ে ভরা?"},{"v":9,"ve":9,"vl":"9","bn":"“যতদিন তোমরা বেঁচে থাকবে ততদিন তোমরা সতর্ক থাকবে এবং নিজেদের উপর কড়া নজর রাখবে যাতে তোমরা চোখে যা দেখেছ তা ভুলে না যাও এবং তোমাদের অন্তর থেকে তা মুছে না যায়। এই সব তোমরা তোমাদের ছেলেমেয়েদের এবং তাদের পরে তাদের ছেলেমেয়েদের শিখাবে।"},{"v":10,"ve":10,"vl":"10","bn":"তোমরা সেই দিনের কথা মনে কর যেদিন তোমরা তুর পাহাড়ে তোমাদের মাবুদ আল্লাহ্‌র সামনে উপস্থিত হয়েছিলে। সেই দিন তিনি আমাকে বলেছিলেন, ‘আমার কথা শুনবার জন্য তুমি লোকদের আমার সামনে জমায়েত কর যাতে তারা এই দুনিয়াতে সারা জীবন আমাকেই ভয় করে চলতে শিখতে পারে আর তাদের ছেলেমেয়েদের আমার হুকুমের কথা শিক্ষা দিতে পারে।’"},{"v":11,"ve":11,"vl":"11","bn":"তখন তোমরা কাছে গিয়ে সেই পাহাড়ের নীচে দাঁড়িয়ে ছিলে; আর তখন অন্ধকারে ঘেরা পাহাড়টা মেঘ ও ঘন অন্ধকারে ভরা আকাশ পর্যন্ত জ্বলছিল।"},{"v":12,"ve":12,"vl":"12","bn":"সেই সময় আগুনের মধ্য থেকে মাবুদ তোমাদের কাছে কথা বলেছিলেন। তোমরা তাঁর কথা শুনেছিলে কিন্তু কোন চেহারা দেখতে পাও নি, কেবল গলার আওয়াজই শুনেছিলে।"},{"v":13,"ve":13,"vl":"13","bn":"তিনি তোমাদের কাছে তাঁর ব্যবস্থা, অর্থাৎ তাঁর দশটি বিশেষ হুকুম ঘোষণা করেছিলেন। তিনি সেই দশটি হুকুম তোমাদের মেনে চলতে বলেছিলেন এবং তা দু’টি পাথরের ফলকের উপর লিখে দিয়েছিলেন।"},{"v":14,"ve":14,"vl":"14","bn":"জর্ডান নদী পার হয়ে যে দেশ তোমরা অধিকার করতে যাচ্ছ সেই দেশে গিয়ে তোমাদের যে নিয়ম ও শরীয়ত পালন করে চলতে হবে তা তোমাদের শিক্ষা দেবার জন্য সেই সময় মাবুদ আমাকে নির্দেশ দিয়েছিলেন।"},{"heading":"মূর্তিপূজা সম্বন্ধে সাবধানবাণী","v":15,"ve":15,"vl":"15","bn":"“তুর পাহাড়ে যেদিন মাবুদ আগুনের মধ্য থেকে তোমাদের কাছে কথা বলেছিলেন সেই দিন তোমরা কোন চেহারা দেখতে পাও নি। সেইজন্য তোমরা নিজেদের উপর খুব কড়া নজর রাখবে,"},{"v":16,"ve":16,"vl":"16","bn":"যাতে তোমরা কুপথে গিয়ে পূজার উদ্দেশ্যে কোন মূর্তি খোদাই না কর কিংবা কোন চেহারার মূর্তি তৈরী না কর- তা পুরুষের বা স্ত্রীলোকেরই হোক,"},{"v":17,"ve":17,"vl":"17","bn":"কিংবা মাটির উপরকার কোন জন্তুর বা আকাশে উড়ে বেড়ানো কোন পাখীরই হোক,"},{"v":18,"ve":18,"vl":"18","bn":"কিংবা বুকে-হাঁটা কোন প্রাণীর বা পানির নীচের কোন মাছেরই হোক।"},{"v":19,"ve":19,"vl":"19","bn":"আসমানের দিকে তাকিয়ে সূর্য, চাঁদ ও তারা, এক কথায় আসমানে সাজিয়ে রাখা সমস্ত আলোদানকারী জিনিসগুলো যখন তোমাদের চোখে পড়বে তখন দুনিয়ার সমস্ত জাতিকে দেওয়া তোমাদের মাবুদ আল্লাহ্‌র এই সব জিনিসগুলোকে সেবা এবং পূজা করে তোমরা বিপথে চলে যেয়ো না।"},{"v":20,"ve":20,"vl":"20","bn":"মনে রেখো, মাবুদ তোমাদের বেছে নিয়েছেন এবং লোহা গলানো হাপরের মত যে মিসর দেশ সেখান থেকে তোমাদের বের করে এনেছেন যেন তোমরা তাঁরই বান্দা হতে পার, আর তোমরা এখন তা-ই হয়েছ।"},{"v":21,"ve":21,"vl":"21","bn":"“তোমাদের দরুন মাবুদ আমার উপর রাগ করলেন। তিনি কসম খেয়ে বলেছিলেন যে, সম্পত্তি হিসাবে যে চমৎকার দেশটা তোমাদের মাবুদ আল্লাহ্‌ তোমাদের দিতে যাচ্ছেন, জর্ডান নদী পার হয়ে আমার সেখানে যাওয়া হবে না।"},{"v":22,"ve":22,"vl":"22","bn":"আমি এখানেই মারা যাব, জর্ডান নদী পার হতে পারব না; কিন্তু তোমরা নদী পার হয়ে সেই চমৎকার দেশটা অধিকার করতে যাচ্ছ।"},{"v":23,"ve":23,"vl":"23","bn":"তোমাদের মাবুদ আল্লাহ্‌ তোমাদের জন্য যে ব্যবস্থা স্থাপন করেছেন, সাবধান, তা তোমরা ভুলে যেয়ো না। তোমাদের মাবুদ আল্লাহ্‌র নিষেধ করা কোন কিছুর মূর্তি তৈরী করা তোমাদের চলবে না,"},{"v":24,"ve":24,"vl":"24","bn":"কারণ তোমাদের মাবুদ আল্লাহ্‌ হলেন সব কিছু পুড়িয়ে দেওয়া আগুন; তাঁর পাওনা এবাদত সম্বন্ধে তিনি খুব আগ্রহী।"},{"v":25,"ve":25,"vl":"25","bn":"“তোমরা এবং তোমাদের বংশধরেরা সেই দেশে অনেক দিন বাস করবার পর যখন তোমরা কুপথে গিয়ে পূজার জন্য মূর্তি তৈরী করবে আর তোমাদের মাবুদ আল্লাহ্‌র চোখে যা খারাপ তা করে তাঁকে অসন্তুষ্ট করে তুলবে,"},{"v":26,"ve":26,"vl":"26","bn":"সেই সময়ের জন্য আমি আজকের এই দিনে আসমান ও জমীনকে তোমাদের বিরুদ্ধে সাক্ষী রেখে বলছি, তোমরা জর্ডান নদী পার হয়ে যে দেশ অধিকার করতে যাচ্ছ সেই দেশে তোমরা অল্প দিনেই শেষ হয়ে যাবে। তোমরা সেখানে বেশী দিন বাস করতে পারবে না, নিশ্চয়ই ধ্বংস হয়ে যাবে।"},{"v":27,"ve":27,"vl":"27","bn":"মাবুদ নানা জাতির মধ্যে তোমাদের ছড়িয়ে দেবেন এবং যাদের মধ্যে তিনি তোমাদের তাড়িয়ে দেবেন তোমাদের খুব কম লোকই তাদের মধ্যে বেঁচে থাকবে।"},{"v":28,"ve":28,"vl":"28","bn":"সেখানে তোমরা মানুষের তৈরী কাঠের ও পাথরের দেবতার পূজা করবে যারা না পারে দেখতে, না পারে শুনতে, না পারে খেতে, না পারে গন্ধ নিতে।"},{"v":29,"ve":29,"vl":"29","bn":"কিন্তু সেখান থেকে তোমরা তোমাদের মাবুদ আল্লাহ্‌র দিকে মন ফিরাবে এবং তাতে তোমরা তাঁর কাছ থেকে সাড়া পাবে, অবশ্য যখন তোমরা তোমাদের সমস্ত মনপ্রাণ দিয়ে তা করবে।"},{"v":30,"ve":30,"vl":"30","bn":"যখন তোমরা কষ্টে পড়বে এবং এই সব তোমাদের উপর ঘটে যাবে তখন ভবিষ্যতের সেই দিনগুলোতে তোমরা তোমাদের মাবুদ আল্লাহ্‌র কাছে ফিরে আসবে এবং তাঁর বাধ্য হয়ে চলবে।"},{"v":31,"ve":31,"vl":"31","bn":"তোমাদের মাবুদ আল্লাহ্‌ মেহেরবান; তিনি তোমাদের ছেড়ে যাবেন না বা ধ্বংস করবেন না, কিংবা কসম খেয়ে তোমাদের পূর্বপুরুষদের জন্য যে ব্যবস্থা স্থাপন করেছেন তা ভুলে যাবেন না।"},{"heading":"আল্লাহ্‌ই মাবুদ","v":32,"ve":32,"vl":"32","bn":"“আল্লাহ্‌ দুনিয়াতে মানুষ সৃষ্টি করবার পর থেকে তোমাদের সময়কার অনেক আগের দিনগুলোতে তোমরা খুঁজে দেখ; আসমানের এক দিক থেকে অন্য দিক পর্যন্ত খুঁজে দেখ যে, যা যা ঘটেছে তার মত মহান আর কিছু ঘটেছে কি না, কিংবা তার মত আর কোন কিছুর কথা শোনা গেছে কি না,"},{"v":33,"ve":33,"vl":"33","bn":"কিংবা তোমাদের মত করে অন্য কোন জাতির লোক আগুনের মধ্য থেকে আল্লাহ্‌কে কথা বলতে শুনে বেঁচে আছে কি না।"},{"v":34,"ve":34,"vl":"34","bn":"তোমরা খুঁজে দেখ যে, তোমাদের মাবুদ আল্লাহ্‌ তোমাদের চোখের সামনে মিসর দেশে তোমাদের জন্য যা করেছিলেন কোন দেবতা কখনও সেইভাবে পরীক্ষা দ্বারা, কুদরতি ও চিহ্ন দ্বারা, যুদ্ধ দ্বারা, কঠোর ও শক্তিশালী হাত দ্বারা এবং মহান ও ভয় জাগানো কাজ দ্বারা কোন জাতিকে অন্য জাতির মধ্য থেকে নিজের জন্য বের করে এনেছে কি না।"},{"v":35,"ve":35,"vl":"35","bn":"“তোমরা যাতে জানতে পার যে, আল্লাহ্‌ই মাবুদ এবং তিনি ছাড়া আর কোন মাবুদ নেই, সেইজন্যই এই সব তোমাদের দেখানো হয়েছিল।"},{"v":36,"ve":36,"vl":"36","bn":"তোমাদের তাঁর শাসনের আওতায় আনবার জন্য তিনি বেহেশত থেকে তাঁর স্বর তোমাদের শুনতে দিয়েছিলেন আর দুনিয়াতে দেখিয়েছিলেন তাঁর মহান আগুন, আর সেই আগুনের মধ্য থেকে তোমরা তাঁর কথা শুনতে পেয়েছিলে।"},{"v":37,"ve":37,"vl":"37","bn":"তিনি তোমাদের পূর্বপুরুষদের মহব্বত করতেন এবং তাঁদের পরে তাঁদের বংশধরদের বেছে নিয়েছেন। সেইজন্য তিনি নিজে উপস্থিত থেকে তাঁর মহাশক্তি দ্বারা মিসর দেশ থেকে তোমাদের বের করে এনেছেন।"},{"v":38,"ve":38,"vl":"38","bn":"তিনি তা করেছেন যাতে তোমাদের চেয়েও বড় এবং শক্তিশালী জাতিগুলোকে তোমাদের সামনে থেকে তাড়িয়ে দিয়ে তাদের দেশে তোমাদের নিয়ে যেতে পারেন এবং সম্পত্তি হিসাবে তা তোমাদের দিতে পারেন; আর আজ তা-ই হয়েছে।"},{"v":39,"ve":39,"vl":"39","bn":"“আজকে তোমরা এই কথাটা জেনে রাখ এবং অন্তরে গেঁথে রাখ যে, আল্লাহ্‌ই উপরে আসমানের এবং নীচে দুনিয়ার মাবুদ, আর তিনি ছাড়া অন্য কোন মাবুদ নেই।"},{"v":40,"ve":40,"vl":"40","bn":"তোমাদের ও তোমাদের পরে তোমাদের সন্তানদের যেন উন্নতি হয় এবং তোমাদের মাবুদ আল্লাহ্‌ যে দেশ চিরকালের জন্য তোমাদের দিচ্ছেন তাতে যেন তোমরা অনেকদিন বেঁচে থাকতে পার সেইজন্য আমি যে সব শরীয়ত ও হুকুম আজ তোমাদের দিচ্ছি তা তোমরা মেনে চলবে।”"},{"heading":"আশ্রয়-শহর","v":41,"ve":43,"vl":"41-43","bn":"এর পর মূসা জর্ডান নদীর পূর্ব দিকে তিনটা শহর বেছে নিলেন, যাতে কেউ কাউকে হত্যা করলে পর সেখানে পালিয়ে গিয়ে আশ্রয় নিতে পারে। অবশ্য যদি সে মনে কোন হিংসা না রেখে হঠাৎ তা করে থাকে তবেই সে সেখানে আশ্রয় নিতে পারবে। যে শহরগুলোতে পালিয়ে গিয়ে নিজের জীবন রক্ষা করা যাবে সেগুলো হল রূবেণীয়দের জন্য মরুভূমির সমভূমির বেৎসর, গাদীয়দের জন্য গিলিয়দের রামোৎ এবং মানশীয়দের জন্য বাশনের গোলান।"},{"heading":"শরীয়তের ভূমিকা","v":44,"ve":46,"vl":"44-46","bn":"মূসা বনি-ইসরাইলদের সামনে এই শরীয়ত তুলে ধরেছিলেন। মিসর থেকে বের হয়ে আসবার পর তিনি জর্ডানের পূর্ব দিকে হিষ্‌বোনের আমোরীয় বাদশাহ্‌ সীহোনের দেশে বৈৎ-পিয়োরের সামনের উপত্যকাতে বনি-ইসরাইলদের কাছে এই সব সাবধানের কথা এবং নিয়ম ও নির্দেশ জানিয়েছিলেন। মিসর দেশ থেকে বের হয়ে আসবার পর মূসা ও বনি-ইসরাইলরা বাদশাহ্‌ সীহোনকে হারিয়ে দিয়েছিলেন।"},{"v":47,"ve":47,"vl":"47","bn":"তাঁরা সীহোনের ও বাশনের বাদশাহ্‌ উজের দেশ অধিকার করে নিয়েছিলেন। এই দুই আমোরীয় বাদশাহ্‌র রাজ্য দু’টি ছিল জর্ডানের পূর্ব দিকে।"},{"v":48,"ve":48,"vl":"48","bn":"অর্ণোন উপত্যকার কিনারার অরোয়ের শহর থেকে সীওন পাহাড়, অর্থাৎ হর্মোণ পাহাড় পর্যন্ত ছিল এই দুই রাজ্য।"},{"v":49,"ve":49,"vl":"49","bn":"তার মধ্যে রয়েছে জর্ডানের পূর্ব দিকের গোটা আরবা এলাকাটা। এটা পিস্‌গা পাহাড়শ্রেণীর ঢালু অংশের নীচে আরবার সাগর পর্যন্ত চলে গেছে।"}],"5":[{"heading":"শরীয়তের দশটি বিশেষ হুকুম","v":1,"ve":1,"vl":"1","bn":"মূসা সমস্ত বনি-ইসরাইলদের ডেকে বললেন, “বনি-ইসরাইলরা, আজ আমি তোমাদের কাছে যে সব নিয়ম ও নির্দেশ প্রকাশ করছি তোমরা তা শোন। তোমরা সেগুলো শিখে রাখবে এবং তা যত্নের সংগে পালন করবে।"},{"v":2,"ve":2,"vl":"2","bn":"আমাদের মাবুদ আল্লাহ্‌ তুর পাহাড়ে আমাদের জন্য একটি ব্যবস্থা স্থাপন করেছিলেন।"},{"v":3,"ve":3,"vl":"3","bn":"সেই ব্যবস্থা তিনি আমাদের পূর্বপুরুষদের কাছে দেন নি, দিয়েছেন আমাদের কাছে, আজ আমরা যারা এখানে বেঁচে রয়েছি আমাদের সকলের কাছে।"},{"v":4,"ve":4,"vl":"4","bn":"মাবুদ সেই পাহাড়ের উপরে আগুনের মধ্য থেকে তোমাদের সামনেই কথা বলেছিলেন।"},{"v":5,"ve":5,"vl":"5","bn":"সেই সময় আগুনের ভয়ে তোমরা পাহাড়ের উপর ওঠো নি বলে আমি তোমাদের ও মাবুদের মাঝখানে দাঁড়িয়ে তাঁর কথা তোমাদের কাছে প্রকাশ করেছিলাম। তখন মাবুদ বলেছিলেন,"},{"v":6,"ve":6,"vl":"6","bn":"‘আমি আল্লাহ্‌ তোমাদের মাবুদ। মিসর দেশের গোলামী থেকে আমিই তোমাদের বের করে এনেছি।"},{"v":7,"ve":7,"vl":"7","bn":"‘আমার জায়গায় কোন দেব-দেবী দাঁড় করাবে না।"},{"v":8,"ve":8,"vl":"8","bn":"‘পূজার উদ্দেশ্যে তোমরা কোন মূর্তি তৈরী করবে না, তা আসমানের কোন কিছুর মত হোক বা মাটির উপরকার কোন কিছুর মত হোক কিংবা পানির মধ্যেকার কোন কিছুর মত হোক।"},{"v":9,"ve":9,"vl":"9","bn":"তোমরা তাদের পূজাও করবে না, তাদের সেবাও করবে না, কারণ কেবলমাত্র আমি আল্লাহ্‌ই তোমাদের মাবুদ। আমার পাওনা এবাদত আমি চাই। যারা আমাকে ঘৃণা করে তাদের গুনাহের শাস্তি আমি তাদের তৃতীয় ও চতুর্থ পুরুষ পর্যন্ত দিয়ে থাকি।"},{"v":10,"ve":10,"vl":"10","bn":"কিন্তু যারা আমাকে মহব্বত করে এবং আমার হুকুম পালন করে হাজার হাজার পুরুষ পর্যন্ত তাদের প্রতি আমার অটল মহব্বত থাকবে।"},{"v":11,"ve":11,"vl":"11","bn":"‘কোন বাজে উদ্দেশ্যে তোমরা তোমাদের মাবুদ আল্লাহ্‌র নাম নেবে না। যে তা করবে তাকে মাবুদ শাস্তি দেবেন।"},{"v":12,"ve":12,"vl":"12","bn":"‘তোমাদের মাবুদ আল্লাহ্‌ তোমাকে যেমন হুকুম দিয়েছেন তেমনি করে তোমরা বিশ্রামবার পবিত্র করে রাখবে এবং তা পালন করবে।"},{"v":13,"ve":13,"vl":"13","bn":"সপ্তার ছয় দিন তোমরা পরিশ্রম করবে এবং তোমাদের সমস্ত কাজ করবে,"},{"v":14,"ve":14,"vl":"14","bn":"কিন্তু সপ্তম দিনটি হল তোমাদের মাবুদ আল্লাহ্‌র উদ্দেশে বিশ্রামের দিন। সেই দিন তোমরা, তোমাদের ছেলেমেয়ে, তোমাদের গোলাম ও বাঁদী, তোমাদের গরু ও গাধা কিংবা অন্য কোন পশু কিংবা তোমাদের গ্রাম ও শহরে বাস করা অন্য জাতির লোক- কারও কোন কাজ করা চলবে না। এতে তোমাদের গোলাম ও বাঁদীও তোমাদের মত বিশ্রাম পাবে।"},{"v":15,"ve":15,"vl":"15","bn":"মনে রেখো, তোমরাও মিসর দেশে গোলামই ছিলে এবং তোমাদের মাবুদ আল্লাহ্‌ তাঁর কঠোর এবং শক্তিশালী হাত বাড়িয়ে সেখান থেকে তোমাদের বের করে এনেছেন। সেইজন্যই তিনি বিশ্রামবার পালন করবার হুকুম তোমাদের দিয়েছেন।"},{"v":16,"ve":16,"vl":"16","bn":"‘তোমাদের মাবুদ আল্লাহ্‌র হুকুম মেনে তোমরা তোমাদের পিতা-মাতাকে সম্মান করে চলবে। তাতে তোমাদের মাবুদ আল্লাহ্‌র দেওয়া দেশে তোমরা অনেক দিন বেঁচে থাকবে এবং তোমাদের উন্নতি হবে।"},{"v":17,"ve":17,"vl":"17","bn":"‘খুন কোরো না।"},{"v":18,"ve":18,"vl":"18","bn":"‘জেনা কোরো না।"},{"v":19,"ve":19,"vl":"19","bn":"‘চুরি কোরো না।"},{"v":20,"ve":20,"vl":"20","bn":"‘কারও বিরুদ্ধে মিথ্যা সাক্ষ্য দিয়ো না।"},{"v":21,"ve":21,"vl":"21","bn":"‘অন্যের স্ত্রীর উপর লোভ কোরো না। অন্যের ঘর-দুয়ার, জমা-জমি, গোলাম ও বাঁদী, গরু-গাধা কিংবা আর কিছুর উপর লোভ কোরো না।’"},{"v":22,"ve":22,"vl":"22","bn":"“সেই পাহাড়ের উপর আগুন, মেঘ ও গাঢ় অন্ধকারের মধ্য থেকে মাবুদ এই হুকুমগুলোই তোমাদের সকলের কাছে জোরে ঘোষণা করেছিলেন। এছাড়া তিনি তোমাদের কাছে আর কিছু বলেন নি। পরে তিনি সেগুলো দু’টি পাথরের ফলকের উপর লিখে আমার কাছে দিয়েছিলেন।"},{"v":23,"ve":23,"vl":"23","bn":"“সেই দিন যখন পাহাড়টা জ্বলছিল আর অন্ধকারের মধ্য থেকে তোমরা তাঁর গলার আওয়াজ শুনতে পেয়েছিলে তখন তোমাদের সব গোষ্ঠী-সর্দারেরা আর বৃদ্ধ নেতারা আমার কাছে উঠে এসেছিলেন।"},{"v":24,"ve":24,"vl":"24","bn":"তোমরা তখন বলেছিলে, ‘আমাদের মাবুদ আল্লাহ্‌ যে কত গৌরবময় ও মহান তা তিনি আমাদের দেখিয়েছেন আর আগুনের মধ্য থেকে আমরা তাঁর গলার আওয়াজ শুনতে পেয়েছি। আজকে আমরা বুঝতে পারলাম যে, আল্লাহ্‌ কারও কাছে কথা বলবার পরেও সে বেঁচে থাকতে পারে।"},{"v":25,"ve":25,"vl":"25","bn":"কিন্তু এর পর আমরা মারা পড়তে যাব কেন? এই মহান আগুন তো আমাদের পুড়িয়ে ফেলবে; আর বেশীক্ষণ যদি আমাদের মাবুদ আল্লাহ্‌র গলার আওয়াজ শুনতে পাই তবে আমরা মারা পড়বই।"},{"v":26,"ve":26,"vl":"26","bn":"মানুষের মধ্যে এমন কে আছে যে, আমাদের মত করে আগুনের মধ্য থেকে জীবন্ত আল্লাহ্‌র গলার আওয়াজ শুনবার পরেও বেঁচে আছে?"},{"v":27,"ve":27,"vl":"27","bn":"আমাদের মাবুদ আল্লাহ্‌ যা বলেছেন, আপনিই কাছে গিয়ে তা শুনে আসুন। তিনি আপনাকে যা বলবেন তা আমাদের জানিয়ে দেবেন; আমরা তা শুনে সেইমতই চলব।’"},{"v":28,"ve":28,"vl":"28","bn":"“আমার সংগে যখন তোমরা কথা বলছিলে তখন মাবুদ তোমাদের কথা শুনেছিলেন এবং আমাকে বলেছিলেন, ‘এই লোকেরা তোমাকে যা বলেছে তা আমি শুনেছি। তারা যা বলেছে তা ভালই।"},{"v":29,"ve":29,"vl":"29","bn":"আমাকে ভয় করবার এবং আমার হুকুম পালন করে চলবার এই মনোভাব যেন তাদের সব সময় থাকে। তাতে তাদের ও তাদের সন্তানদের চিরস্থায়ী উন্নতি হবে।"},{"v":30,"ve":30,"vl":"30","bn":"“‘তুমি তাদের তাম্বুতে ফিরে যেতে বল,"},{"v":31,"ve":31,"vl":"31","bn":"কিন্তু তুমি এখানে আমার কাছে থাক। আমি তোমাকে সেই সমস্ত হুকুম, আইন ও নিয়ম দেব যা তোমাকে তাদের শিখাতে হবে, যেন অধিকার করবার জন্য যে দেশ আমি তাদের দিতে যাচ্ছি সেখানে তারা সেগুলো পালন করে চলে।’"},{"v":32,"ve":32,"vl":"32","bn":"“কাজেই তোমাদের মাবুদ আল্লাহ্‌ তোমাদের যা করবার হুকুম দিয়েছেন তা তোমাদের যত্নের সংগে পালন করতে হবে; তা থেকে একটুও এদিক-সেদিক হওয়া চলবে না।"},{"v":33,"ve":33,"vl":"33","bn":"যাতে তোমরা বাঁচতে পার এবং তোমাদের উন্নতি হয় আর যে দেশ তোমরা অধিকার করবে সেখানে অনেক দিন বেঁচে থাকতে পার সেইজন্য তোমাদের মাবুদ আল্লাহ্‌ যে যে পথে তোমাদের চলবার হুকুম দিয়েছেন তোমরা সেই সব পথেই চলবে।"}],"6":[{"heading":"শরীয়তের মূল হুকুম","v":1,"ve":1,"vl":"1","bn":"“তোমাদের মাবুদ আল্লাহ্‌ এই সব হুকুম, নিয়ম ও নির্দেশ তোমাদের শিক্ষা দেবার জন্য আমাকে হুকুম দিয়েছেন, যেন জর্ডান নদী পার হয়ে যে দেশ তোমরা অধিকার করতে যাচ্ছ সেখানে তোমরা তা পালন করে চল।"},{"v":2,"ve":2,"vl":"2","bn":"এতে তোমরা, তোমাদের ছেলেমেয়েরা ও তাদের বংশধরেরা তোমাদের মাবুদ আল্লাহ্‌কে ভয় করে তাঁর দেওয়া এই সব নিয়ম ও হুকুম সারা জীবন পালন করবে এবং তার ফলে অনেক দিন বেঁচে থাকবে।"},{"v":3,"ve":3,"vl":"3","bn":"বনি-ইসরাইলরা, তোমরা আমার কথা শোন এবং সতর্ক হয়ে এই সব মেনে চল, যাতে দুধ আর মধুতে ভরা সেই দেশে যাবার পরে তোমাদের পূর্বপুরুষদের মাবুদ আল্লাহ্‌র ওয়াদা অনুসারে তোমাদের উন্নতি হয় আর তোমরা সংখ্যায় অনেক বেড়ে উঠতে পার।"},{"v":4,"ve":4,"vl":"4","bn":"“বনি-ইসরাইলরা, শোন, আমাদের মাবুদ আল্লাহ্‌ এক।"},{"v":5,"ve":5,"vl":"5","bn":"তোমরা প্রত্যেকে তোমাদের সমস্ত দিল, সমস্ত প্রাণ ও সমস্ত শক্তি দিয়ে তোমাদের মাবুদ আল্লাহ্‌কে মহব্বত করবে।"},{"v":6,"ve":6,"vl":"6","bn":"এই সব হুকুম যা আজ আমি তোমাদের দিচ্ছি তা যেন তোমাদের অন্তরে থাকে।"},{"v":7,"ve":7,"vl":"7","bn":"তোমাদের ছেলেমেয়েদের তোমরা বার বার করে সেগুলো শিখাবে। ঘরে বসে থাকবার সময়, পথে চলবার সময়, শোবার সময় এবং বিছানা থেকে উঠবার সময় তোমরা এই বিষয় নিয়ে আলোচনা করবে।"},{"v":8,"ve":8,"vl":"8","bn":"তোমরা তা মনে রাখবার চিহ্ন হিসাবে তোমাদের হাতে বেঁধে রাখবে এবং কপালে লাগিয়ে রাখবে।"},{"v":9,"ve":9,"vl":"9","bn":"তোমাদের বাড়ীর দরজায় ও চৌকাঠে তোমরা সেগুলো লিখে রাখবে।"},{"v":10,"ve":10,"vl":"10","bn":"“তোমাদের পূর্বপুরুষ ইব্রাহিম, ইসহাক ও ইয়াকুবের কাছে তোমাদের মাবুদ আল্লাহ্‌ তোমাদের যে দেশ দেবার কথা কসম খেয়ে বলেছিলেন সেখানে তিনি তোমাদের নিয়ে যাবেন। সেখানে রয়েছে এমন সব সুন্দর ও বড় বড় শহর যা তোমরা নিজেরা তৈরী কর নি,"},{"v":11,"ve":12,"vl":"11-12","bn":"এমন সব ভাল ভাল জিনিসে ভরা ঘর-বাড়ী যে সব জিনিস তোমরা নিজেরা যোগাড় কর নি, এমন সব পানি রাখবার জায়গা যা তোমরা নিজেরা কেটে তৈরী কর নি এবং এমন সব আংগুর ক্ষেত ও জলপাই বাগান যার গাছপালা তোমরা নিজেরা লাগাও নি। কিন্তু সেখানে খাওয়া-দাওয়া করে তৃপ্ত হবার পরে সতর্ক থেকো যাতে তোমরা মাবুদকে ভুলে না যাও, যিনি মিসর দেশের গোলামী থেকে তোমাদের বের করে এনেছেন।"},{"v":13,"ve":13,"vl":"13","bn":"“তোমাদের মাবুদ আল্লাহ্‌কে তোমরা ভয় করবে, কেবল তাঁরই এবাদত করবে এবং তাঁর নামেই কসম খাবে।"},{"v":14,"ve":14,"vl":"14","bn":"তোমাদের আশেপাশে যে সব জাতি থাকবে তোমরা তাদের দেব-দেবীদের পিছনে যাবে না,"},{"v":15,"ve":15,"vl":"15","bn":"কারণ তোমাদের মধ্যে তোমাদের যে মাবুদ আল্লাহ্‌ রয়েছেন তিনি তাঁর পাওনা এবাদত সম্বন্ধে খুব আগ্রহী; দেব-দেবীদের পিছনে গেলে তোমাদের বিরুদ্ধে তাঁর রাগের আগুন জ্বলে উঠবে, আর তিনি দুনিয়ার উপর থেকে তোমাদের ধ্বংস করে ফেলবেন।"},{"v":16,"ve":16,"vl":"16","bn":"তোমরা তোমাদের মাবুদ আল্লাহ্‌কে পরীক্ষা করতে যেয়ো না, যেমন তোমরা মঃসাতে করেছিলে।"},{"v":17,"ve":17,"vl":"17","bn":"তোমাদের মাবুদ আল্লাহ্‌ যে সব হুকুম, সাবধানের কথা আর নিয়ম দিয়েছিলেন তা অবশ্যই তোমাদের পালন করতে হবে।"},{"v":18,"ve":19,"vl":"18-19","bn":"তোমাদের যাতে উন্নতি হয় সেইজন্য মাবুদের চোখে যা ঠিক এবং ভাল তোমরা তা-ই কোরো। তাতে মাবুদ তোমাদের পূর্বপুরুষদের কাছে কসম খেয়ে যে চমৎকার দেশটি দেবার ওয়াদা করেছিলেন, সেই দেশে গিয়ে তোমরা তা অধিকার করতে পারবে এবং মাবুদ যেমন বলেছিলেন তেমনি করে তোমাদের সামনে থেকে তোমাদের শত্রুদের তোমরা তাড়িয়ে দিতে পারবে।"},{"v":20,"ve":20,"vl":"20","bn":"“ভবিষ্যতে যখন তোমাদের ছেলেরা তোমাদের জিজ্ঞাসা করবে, ‘আমাদের মাবুদ আল্লাহ্‌ এই যে সব সাবধানের কথা, নিয়ম ও নির্দেশ তোমাদের দিয়েছেন সেই সবের মানে কি?’"},{"v":21,"ve":21,"vl":"21","bn":"তখন তোমরা তাদের বলবে, ‘মিসর দেশে আমরা ফেরাউনের গোলাম ছিলাম, কিন্তু মাবুদ শক্তিশালী হাত ব্যবহার করে সেখান থেকে আমাদের বের করে এনেছেন।"},{"v":22,"ve":22,"vl":"22","bn":"মাবুদ আমাদের চোখের সামনে ফেরাউন ও তাঁর বাড়ীর সকলের উপর এবং মিসর দেশের উপর বড় বড় এবং ভয়ংকর অলৌকিক চিহ্ন ও কুদরতি দেখিয়েছিলেন।"},{"v":23,"ve":23,"vl":"23","bn":"কিন্তু সেখান থেকে তিনি আমাদের বের করে এনেছিলেন যাতে আমাদের পূর্বপুরুষদের কাছে যে দেশ দেবার কসম তিনি খেয়েছিলেন সেই দেশে নিয়ে গিয়ে আমাদের তা দিতে পারেন।"},{"v":24,"ve":24,"vl":"24","bn":"আজকের মত যেন সব সময় আমাদের উন্নতি হয় আর আমরা বেঁচে থাকতে পারি সেইজন্য মাবুদ আমাদের এই সব নিয়ম পালন করতে এবং আমাদের মাবুদ আল্লাহ্‌কে ভয় করতে হুকুম দিয়েছেন।"},{"v":25,"ve":25,"vl":"25","bn":"আমরা যদি আমাদের মাবুদ আল্লাহ্‌র সামনে তাঁর হুকুম মত এই শরীয়ত মেনে চলবার দিকে মন দিই, তবে সেটাই হবে আমাদের পক্ষে তাঁর ইচ্ছামত চলা।’"}],"7":[{"heading":"আল্লাহ্‌র বাছাই-করা বান্দা","v":1,"ve":1,"vl":"1","bn":"“তোমরা যে দেশ অধিকার করবার জন্য যাচ্ছ সেখানে তোমাদের মাবুদ আল্লাহ্‌ই তোমাদের নিয়ে যাবেন এবং অনেক জাতিকে তোমাদের সামনে থেকে তাড়িয়ে দেবেন। এই জাতিগুলো হল হিট্টীয়, গির্গাষীয়, আমোরীয়, কেনানীয়, পরিষীয়, হিব্বীয় এবং যিবূষীয়। এই সাতটি জাতিই লোকসংখ্যায় এবং শক্তিতে তোমাদের চেয়ে বড়।"},{"v":2,"ve":2,"vl":"2","bn":"তিনি যখন তাদের তোমাদের হাতের মুঠোয় এনে দেবেন এবং তোমরা তাদের হারিয়ে দেবে তখন তোমরা তাদের একেবারে ধ্বংস করে ফেলবে। তোমরা তাদের সংগে কোন সন্ধি করবে না এবং তাদের প্রতি কোন দয়া দেখাবে না।"},{"v":3,"ve":3,"vl":"3","bn":"তোমরা তাদের সংগে কোন বিয়ের সম্বন্ধ স্থাপন করবে না। তোমাদের মেয়েদেরও তোমরা তাদের ছেলেদের হাতে দেবে না এবং তাদের মেয়েদেরও তোমরা তোমাদের ছেলেদের জন্য আনবে না,"},{"v":4,"ve":4,"vl":"4","bn":"কারণ সেই মেয়েরা তোমাদের ছেলেদের আমার কাছ থেকে দূরে সরিয়ে নেবে এবং দেব-দেবীর পূজা করাবে। তাতে মাবুদের রাগের আগুন তোমাদের বিরুদ্ধে জ্বলে উঠবে এবং সংগে সংগে তোমাদের ধ্বংস করে ফেলবে।"},{"v":5,"ve":5,"vl":"5","bn":"তোমরা ঐ সব জাতির বেদীগুলো ভেংগে ফেলবে, পূজার পাথরগুলো চুরমার করে দেবে, পূজার আশেরা-খুঁটিগুলো কেটে ফেলবে এবং মূর্তিগুলো আগুনে পুড়িয়ে দেবে।"},{"v":6,"ve":6,"vl":"6","bn":"তোমরা এমন একটি জাতি যাকে তোমাদের মাবুদ আল্লাহ্‌র উদ্দেশ্যে আলাদা করে রাখা হয়েছে। তোমরা যেন তোমাদের মাবুদ আল্লাহ্‌র নিজের বান্দা ও সম্পত্তি হও সেইজন্য দুনিয়ার সমস্ত জাতির মধ্য থেকে তিনি তোমাদের বেছে নিয়েছেন।"},{"v":7,"ve":7,"vl":"7","bn":"“অন্য জাতির চেয়ে তোমাদের লোকসংখ্যা বেশী মনে করে যে মাবুদ তোমাদের সংগে নিজেকে মহব্বতের বাঁধনে বেঁধেছেন কিংবা তোমাদের বেছে নিয়েছেন তা নয়, কারণ অন্য সব জাতির চেয়ে তোমাদের লোকসংখ্যা কম।"},{"v":8,"ve":8,"vl":"8","bn":"তিনি তা করেছেন তোমাদের প্রতি তাঁর অটল মহব্বতের জন্য এবং তোমাদের পূর্বপুরুষদের কাছে তিনি যে কসম খেয়েছিলেন তা রক্ষা করবার জন্য। সেইজন্যই তিনি শক্তিশালী হাত ব্যবহার করে তোমাদের বের করে এনেছেন এবং মিসরের বাদশাহ্‌ ফেরাউনের হাত থেকে আর গোলামীর দেশ থেকে তোমাদের মুক্ত করেছেন।"},{"v":9,"ve":9,"vl":"9","bn":"কাজেই তোমরা জেনে রেখো যে, তোমাদের মাবুদ আল্লাহ্‌ই মাবুদ। তিনি বিশ্বস্ত; যারা তাঁকে মহব্বত করে ও তাঁর হুকুমগুলো পালন করে তাদের জন্য তিনি যে ব্যবস্থা স্থাপন করেছেন তা তিনি হাজার হাজার পুরুষ পর্যন্ত রক্ষা করেন এবং তাদের প্রতি তাঁর অটল মহব্বত দেখান।"},{"v":10,"ve":10,"vl":"10","bn":"কিন্তু যারা তাঁকে মহব্বত করে না তাদের ধ্বংস করে তিনি তার শোধ দেন; আর তা করতে তিনি দেরি করেন না।"},{"v":11,"ve":11,"vl":"11","bn":"কাজেই আজ আমি তোমাদের যে সব হুকুম, নিয়ম ও নির্দেশ দিচ্ছি তা তোমরা যত্নের সংগে পালন করবে।"},{"heading":"বাধ্যতার পুরস্কার","v":12,"ve":12,"vl":"12","bn":"“যদি তোমরা এই সব নিয়মের দিকে মনোযোগ দাও এবং তা যত্নের সংগে পালন কর, তবে তোমাদের মাবুদ আল্লাহ্‌ তোমাদের পূর্বপুরুষদের কাছে যে কসম খেয়েছিলেন সেই অনুসারে তোমাদের জন্য তিনি যে ব্যবস্থা স্থাপন করেছেন তা তিনি রক্ষা করবেন এবং তোমাদের প্রতি অটল মহব্বত দেখাবেন।"},{"v":13,"ve":13,"vl":"13","bn":"তিনি তোমাদের মহব্বত করবেন, দোয়া করবেন এবং তোমাদের লোকসংখ্যা বাড়িয়ে দেবেন। যে দেশ তোমাদের দেবার কথা তিনি তোমাদের পূর্বপুরুষদের কাছে কসম খেয়ে বলেছিলেন সেই দেশে তিনি তোমাদের দোয়া করবেন। তাতে তোমাদের অনেক সন্তান হবে, তোমাদের জমি থেকে তোমরা প্রচুর পরিমাণে শস্য, আংগুর-রস ও তেল পাবে, আর তোমাদের গরু, ছাগল ও ভেড়ারও অনেক বাচ্চা হবে।"},{"v":14,"ve":14,"vl":"14","bn":"অন্য সব লোকদের চেয়ে তোমরা বেশী দোয়া পাবে। তোমাদের কেউই সন্তানহীন থাকবে না এবং তোমাদের পালের কোন পশুই বাচ্চাহীন থাকবে না।"},{"v":15,"ve":15,"vl":"15","bn":"মাবুদ সব রোগ থেকে তোমাদের মুক্ত রাখবেন। মিসরে যে সব ভীষণ রোগ তোমরা দেখেছ তা তিনি তোমাদের উপর হতে দেবেন না, কিন্তু যারা তোমাদের ঘৃণা করে তাদের উপর সেই সব হতে দেবেন।"},{"v":16,"ve":16,"vl":"16","bn":"তোমাদের মাবুদ আল্লাহ্‌ তোমাদের হাতের মুঠোয় যে সব জাতি এনে দেবেন তাদের সবাইকে তোমাদের ধ্বংস করে ফেলতে হবে। তাদের তোমরা দয়া দেখাবে না এবং তাদের দেবতাদেরও পূজা করবে না, কারণ তা তোমাদের পক্ষে ফাঁদ হয়ে দাঁড়াবে।"},{"v":17,"ve":17,"vl":"17","bn":"“তোমরা মনে মনে বলতে পার, ‘এই সব জাতির লোকেরা আমাদের চেয়ে সংখ্যায় বেশী; আমরা কেমন করে তাদের তাড়িয়ে বের করে দেব?’"},{"v":18,"ve":18,"vl":"18","bn":"কিন্তু তোমরা তাদের ভয় কোরো না। ফেরাউন ও সারা মিসর দেশের উপর তোমাদের মাবুদ আল্লাহ্‌ কি করেছিলেন তা ভুলে যেয়ো না।"},{"v":19,"ve":19,"vl":"19","bn":"তোমাদের মাবুদ আল্লাহ্‌ যে সব ভীষণ পরীক্ষা দ্বারা, কুদরতি ও অলৌকিক চিহ্ন দ্বারা এবং তাঁর কঠোর এবং শক্তিশালী হাত দ্বারা তোমাদের বের করে এনেছেন তা তো তোমরা নিজেদের চোখেই দেখেছ। তোমরা এখন যে সব জাতিদের দেখে ভয় পাচ্ছ তাদের উপরও তিনি তা-ই করবেন।"},{"v":20,"ve":20,"vl":"20","bn":"এর পরেও তাদের মধ্যে যারা বেঁচে যাবে এবং তোমাদের কাছ থেকে নিজেদের লুকিয়ে রাখবে তোমাদের মাবুদ আল্লাহ্‌ তাদের মধ্যে ভিমরুল পাঠিয়ে দেবেন আর তারা সবাই ধ্বংস হয়ে যাবে।"},{"v":21,"ve":21,"vl":"21","bn":"তোমরা তাদের ভয় কোরো না, কারণ তোমাদের মাবুদ আল্লাহ্‌ যিনি তোমাদের মধ্যে আছেন, তিনি ভয় জাগানো আল্লাহ্‌তা’লা।"},{"v":22,"ve":22,"vl":"22","bn":"তোমাদের মাবুদ আল্লাহ্‌ই তোমাদের সামনে থেকে ঐ সব জাতিকে আস্তে আস্তে তাড়িয়ে দেবেন। তাদের সবাইকে তোমরা একসংগে তাড়িয়ে দেবে না, কারণ তাহলে তোমাদের চারপাশে বুনো জানোয়ারের সংখ্যা বেড়ে যাবে।"},{"v":23,"ve":23,"vl":"23","bn":"তোমাদের মাবুদ আল্লাহ্‌ ভীষণ বিশৃঙ্খলার মধ্যে ফেলে তোমাদের হাতে তাদের তুলে দেবেন যতক্ষণ না তারা একেবারে ধ্বংস হয়ে যায়।"},{"v":24,"ve":24,"vl":"24","bn":"তাদের বাদশাহ্‌দের তিনি তোমাদের হাতে তুলে দেবেন আর তোমরা তাদের নাম দুনিয়া থেকে মুছে ফেলবে। কেউ তোমাদের বাধা দিয়ে রাখতে পারবে না; তোমরা তাদের ধ্বংস করে ফেলবে।"},{"v":25,"ve":25,"vl":"25","bn":"তাদের দেব-দেবীর মূর্তিগুলো তোমরা আগুনে পুড়িয়ে ফেলবে। তোমরা তাদের গায়ের সোনা-রূপার লোভ করবে না। নিজেদের জন্য তোমরা তা নেবে না, কারণ তা করলে তোমরা ওগুলোর ফাঁদে পড়বে। তোমাদের মাবুদ আল্লাহ্‌র কাছে ওগুলো ঘৃণার জিনিস।"},{"v":26,"ve":26,"vl":"26","bn":"কোন ঘৃণার জিনিস তোমাদের ঘরে আনবে না। ওগুলো তোমরা মনেপ্রাণে ঘৃণা ও তুচ্ছ করবে, কারণ ওগুলোর উপর রয়েছে ধ্বংসের বদদোয়া। ওগুলো যদি তোমরা ঘরে আন তবে তোমাদের উপরও ধ্বংসের বদদোয়া নেমে আসবে।"}],"8":[{"heading":"মাবুদকে মনে রাখবার হুকুম","v":1,"ve":1,"vl":"1","bn":"“আজ আমি তোমাদের যে সব হুকুম দিচ্ছি তার প্রত্যেকটা পালন করবার দিকে তোমরা মন দাও, যাতে তোমরা বেঁচে থাক ও সংখ্যায় বেড়ে ওঠো আর মাবুদ তোমাদের পূর্বপুরুষদের কাছে যে দেশ দেবার কথা কসম খেয়ে ওয়াদা করেছিলেন সেখানে ঢুকে তা অধিকার করতে পার।"},{"v":2,"ve":2,"vl":"2","bn":"মনে করে দেখ, তোমাদের মাবুদ আল্লাহ্‌ এই চল্লিশটা বছর কিভাবে মরুভূমির মধ্য দিয়ে সারাটা পথ তোমাদের চালিয়ে এনেছেন। তোমাদের অহংকার ভেংগে দেবার জন্য এবং তোমাদের মনে কি আছে, অর্থাৎ তোমরা তাঁর হুকুম পালন করবে কি না, তা পরীক্ষায় ফেলে দেখাবার জন্য তিনি এই কাজ করেছেন।"},{"v":3,"ve":3,"vl":"3","bn":"ক্ষুধায় কষ্ট দিয়ে এবং যে মান্নার কথা তোমাদের ও তোমাদের পূর্বপুরুষদের জানা ছিল না তা খাইয়ে তিনি তোমাদের অহংকার ভেংগে দিয়েছেন। এতে তিনি তোমাদের এই শিক্ষা দিতে চেয়েছেন যে, মানুষ কেবল রুটিতেই বাঁচে না, কিন্তু মাবুদের মুখের প্রত্যেকটি কথাতেই বাঁচে।"},{"v":4,"ve":4,"vl":"4","bn":"এই চল্লিশ বছর তোমাদের গায়ের কাপড় নষ্ট হয় নি এবং পা-ও ফুলে যায় নি।"},{"v":5,"ve":5,"vl":"5","bn":"এই কথা তোমাদের দিলে জেনে রেখো যে, বাবা যেমন ছেলেকে শাসন করেন ঠিক সেইভাবে তোমাদের মাবুদ আল্লাহ্‌ তোমাদের শাসন করেন।"},{"v":6,"ve":6,"vl":"6","bn":"“তোমরা তোমাদের মাবুদ আল্লাহ্‌র হুকুম পালন করবে, তাঁর পথে চলবে এবং তাঁকে ভয় করবে।"},{"v":7,"ve":7,"vl":"7","bn":"তোমাদের মাবুদ আল্লাহ্‌ যে চমৎকার দেশটিতে তোমাদের নিয়ে যাচ্ছেন সেখানে রয়েছে পাহাড় ও উপত্যকা দিয়ে বয়ে যাওয়া নদী, ঝর্ণা আর মাটির তলার পানি।"},{"v":8,"ve":8,"vl":"8","bn":"সেখানে রয়েছে প্রচুর গম ও যব, আংগুর ও ডুমুর গাছ এবং ডালিম, জলপাইয়ের তেল আর মধু।"},{"v":9,"ve":9,"vl":"9","bn":"সেই দেশে তোমরা পাবে প্রচুর খাবার এবং কোন কিছুরই অভাব তোমাদের থাকবে না। সেখানকার পাথরে রয়েছে লোহা। সেখানকার পাহাড় থেকে তোমরা তামা খুঁড়ে তুলতে পারবে।"},{"v":10,"ve":10,"vl":"10","bn":"“তোমরা সেখানে খাওয়া-দাওয়া করে তৃপ্ত হবার পর তোমাদের মাবুদ আল্লাহ্‌র দেওয়া ঐ চমৎকার দেশটির জন্য তাঁর প্রশংসা করবে।"},{"v":11,"ve":11,"vl":"11","bn":"তোমরা সতর্ক থাকবে যেন আজ আমি তাঁর যে সব হুকুম, নির্দেশ ও নিয়ম তোমাদের দিচ্ছি তা অমান্য করে তোমরা তোমাদের মাবুদ আল্লাহ্‌কে ভুলে না যাও।"},{"v":12,"ve":12,"vl":"12","bn":"যদি তোমরা সতর্ক না থাক, তবে তোমরা যখন খাওয়া-দাওয়া করে তৃপ্ত হবে আর সুন্দর সুন্দর বাড়ী-ঘর তৈরী করে সেখানে বাস করতে থাকবে,"},{"v":13,"ve":13,"vl":"13","bn":"যখন তোমাদের পালের গরু-ছাগল-ভেড়ার সংখ্যা বেড়ে যাবে আর তোমাদের অনেক সোনা-রূপা হবে এবং তোমাদের সব কিছু বেড়ে যাবে,"},{"v":14,"ve":14,"vl":"14","bn":"তখন তোমরা অহংকারী হয়ে উঠবে এবং যিনি মিসর দেশের গোলামী থেকে তোমাদের বের করে এনেছেন তোমাদের সেই মাবুদ আল্লাহ্‌কে তোমরা ভুলে যাবে।"},{"v":15,"ve":15,"vl":"15","bn":"তিনি তোমাদের এক বিরাট, ভয়ংকর, শুকনা, পানিহীন এবং বিষাক্ত সাপ ও কাঁকড়া-বিছায় ভরা মরুভূমির মধ্য দিয়ে নিয়ে এসেছেন। তিনি শক্ত পাথরের মধ্য থেকে তোমাদের জন্য পানি বের করেছেন।"},{"v":16,"ve":16,"vl":"16","bn":"তিনি সেই মরুভূমিতে তোমাদের মান্না খেতে দিয়েছেন যার কথা তোমাদের পূর্বপুরুষেরা কখনও জানেন নি। তোমাদের পরীক্ষা করবার জন্য ও অহংকার ভেংগে দেবার জন্য তিনি তা দিয়েছিলেন যাতে শেষ পর্যন্ত তোমাদের উন্নতি হয়।"},{"v":17,"ve":17,"vl":"17","bn":"তোমরা হয়তো কেউ মনে মনে বলতে পার, ‘আমার নিজের শক্তিতে, নিজের হাতে কাজ করে আমি এই সব ধন-সম্পত্তি করেছি।’"},{"v":18,"ve":18,"vl":"18","bn":"কিন্তু তোমরা তোমাদের মাবুদ আল্লাহ্‌র কথা ভুলে যেয়ো না; তিনিই এই সব করবার ক্ষমতা তোমাদের দিয়েছেন, আর এইভাবে তিনি তোমাদের পূর্বপুরুষদের কাছে যে ব্যবস্থার কথা কসম খেয়ে বলেছিলেন তা তিনি এখন পূর্ণ করে চলেছেন।"},{"v":19,"ve":19,"vl":"19","bn":"“যদি তোমরা কখনও তোমাদের মাবুদ আল্লাহ্‌কে ভুলে গিয়ে দেব-দেবীদের পিছনে যাও এবং তাদের সেবা ও পূজা কর, তবে আজ আমি তোমাদের বিরুদ্ধে এই কথা নিশ্চয় করে বলছি যে, তোমরা ধ্বংস হয়ে যাবে।"},{"v":20,"ve":20,"vl":"20","bn":"মাবুদ তোমাদের সামনে যে সব জাতিকে ধ্বংস করছেন তাদের মত তোমরাও তোমাদের মাবুদ আল্লাহ্‌র অবাধ্য হওয়ার দরুন ধ্বংস হয়ে যাবে।"}],"9":[{"heading":"বনি-ইসরাইলদের অবাধ্যতা এবং বিদ্রোহ","v":1,"ve":1,"vl":"1","bn":"“বনি-ইসরাইলরা, শোন। যে সব জাতি তোমাদের চেয়ে লোকসংখ্যায় এবং শক্তিতে বড় তোমরা এখন গিয়ে তাদের আকাশ ছোঁয়া দেয়াল দিয়ে ঘেরা বড় বড় শহরগুলো দখল করবার জন্য জর্ডান নদী পার হতে যাচ্ছ।"},{"v":2,"ve":2,"vl":"2","bn":"সেখানকার লোকেরা অনাকীয়; তারা লম্বা ও শক্তিশালী। তোমরা অনাকীয়দের বিষয়ে জান; তাদের সম্বন্ধে তোমরা এই কথা বলতে শুনেছ, ‘অনাকীয়দের বিরুদ্ধে দাঁড়াতে পারে এমন লোক কোথায়?’"},{"v":3,"ve":3,"vl":"3","bn":"কিন্তু তোমরা এই কথা জেনে রেখো যে, তোমাদের মাবুদ আল্লাহ্‌ই ধ্বংসকারী আগুনের মত তোমাদের আগে আগে জর্ডান নদী পার হয়ে যাচ্ছেন। তিনি তাদের ধ্বংস করে দেবেন; তিনিই তোমাদের কাছে তাদের হার মানাবেন। তোমাদের কাছে মাবুদ যে আশ্বাস দিয়েছেন সেই অনুসারে তোমরা তাদের তাড়িয়ে দেবে এবং অল্প সময়ের মধ্যেই তাদের শেষ করে ফেলবে।"},{"v":4,"ve":4,"vl":"4","bn":"“তোমাদের মাবুদ আল্লাহ্‌ তোমাদের সামনে থেকে তাদের তাড়িয়ে দেবার পর তোমাদের কেউ যেন মনে মনে না বলে, ‘আমি ধার্মিক বলেই মাবুদ এই দেশ অধিকার করবার জন্য আমাকে এখানে নিয়ে এসেছেন।’ আসলে তা নয়; এই সব জাতির লোকদের খারাপীর জন্যই মাবুদ তোমাদের সামনে থেকে তাদের তাড়িয়ে দিতে যাচ্ছেন।"},{"v":5,"ve":5,"vl":"5","bn":"ধার্মিক কিংবা সৎ বলেই যে তোমরা তাদের দেশ অধিকার করতে যাচ্ছ তা নয়, বরং তোমাদের মাবুদ আল্লাহ্‌ তোমাদের পূর্বপুরুষ ইব্রাহিম, ইসহাক ও ইয়াকুবের কাছে যে কথা ওয়াদা করে বলেছিলেন তা পূরণ করবার জন্যই তিনি এই সব জাতির খারাপীর দরুন তোমাদের সামনে থেকে তাদের তাড়িয়ে দেবেন।"},{"v":6,"ve":6,"vl":"6","bn":"কাজেই তোমরা জেনে রেখো, তোমরা ধার্মিক বলেই যে তোমাদের মাবুদ আল্লাহ্‌ এই চমৎকার দেশটা তোমাদের অধিকার করতে দিচ্ছেন তা নয়। তোমরা তো একটা একগুঁয়ে জাতি।"},{"heading":"সোনার বাছুর","v":7,"ve":7,"vl":"7","bn":"“তোমরা মরুভূমিতে তোমাদের মাবুদ আল্লাহ্‌র রাগ কিভাবে জাগিয়ে তুলেছিলে তা মনে রেখো, কখনও ভুলে যেয়ো না। মিসর দেশ ছেড়ে আসবার দিন থেকে শুরু করে এখানে পৌঁছানো পর্যন্ত তোমরা মাবুদের বিরুদ্ধে বিদ্রোহের ভাব মনে পুষে আসছ।"},{"v":8,"ve":8,"vl":"8","bn":"তোমরা তুর পাহাড়ে এমন ভাবে মাবুদের রাগ জাগিয়ে তুলেছিলে যে, তার দরুন তিনি তোমাদের ধ্বংস করে ফেলতে চেয়েছিলেন।"},{"v":9,"ve":9,"vl":"9","bn":"মাবুদ যে ব্যবস্থা তোমাদের জন্য স্থাপন করেছেন সেই ব্যবস্থা লেখা পাথরের ফলক দু’টা গ্রহণ করবার জন্য আমি পাহাড়ের উপর উঠে চল্লিশ দিন ও চল্লিশ রাত সেখানেই ছিলাম। তখন আমি পানি বা রুটি কিছুই খাই নি।"},{"v":10,"ve":10,"vl":"10","bn":"মাবুদের নিজের লেখা রয়েছে এমন দু’টা পাথরের ফলক মাবুদ আমাকে দিয়েছিলেন। তোমরা সবাই যেদিন মাবুদের সামনে জমায়েত হয়েছিলে সেই দিন তিনি পাহাড়ের উপরে আগুনের মধ্য থেকে যে সব হুকুম তোমাদের কাছে ঘোষণা করেছিলেন সেগুলো ঐ ফলক দু’টার উপর লেখা ছিল।"},{"v":11,"ve":11,"vl":"11","bn":"“সেই চল্লিশ দিন আর চল্লিশ রাত কেটে যাওয়ার পর মাবুদ ঐ ব্যবস্থা লেখা পাথরের ফলক দু’টা আমাকে দিয়েছিলেন।"},{"v":12,"ve":12,"vl":"12","bn":"তারপর তিনি আমাকে বলেছিলেন, ‘তুমি আর দেরি না করে এখনই নীচে নেমে যাও, কারণ যে লোকদের তুমি মিসর থেকে বের করে এনেছ তারা কুপথে গেছে। যে পথে চলবার হুকুম আমি দিয়েছিলাম এর মধ্যেই তারা তা থেকে দূরে সরে গেছে এবং পূজার জন্য ছাঁচে ফেলে একটা মূর্তি তৈরী করে নিয়েছে।’"},{"v":13,"ve":13,"vl":"13","bn":"“মাবুদ আমাকে আরও বললেন, ‘আমি এই লোকগুলোকে দেখেছি; এরা একটা একগুঁয়ে জাতি।"},{"v":14,"ve":14,"vl":"14","bn":"না, তুমি আমাকে বাধা দিয়ো না; আমি তাদের ধ্বংস করে ফেলব এবং দুনিয়া থেকে তাদের নাম মুছে ফেলব। তারপর তোমার মধ্য দিয়ে আমি আরও শক্তিশালী এবং আরও বড় একটা জাতির সৃষ্টি করব।’"},{"v":15,"ve":15,"vl":"15","bn":"“এর পর আমি পাহাড় থেকে নেমে আসলাম; তখনও পাহাড়ে আগুন জ্বলছিল, আর আমার হাতে ছিল ব্যবস্থা লেখা সেই ফলক দু’টা।"},{"v":16,"ve":16,"vl":"16","bn":"আমি চেয়ে দেখলাম, তোমরা তোমাদের মাবুদ আল্লাহ্‌র বিরুদ্ধে গুনাহ্‌ করেছ; পূজার জন্য তোমরা ছাঁচে ফেলে একটা বাছুরের মূর্তি তৈরী করে নিয়েছ। মাবুদ তোমাদের যে পথে চলবার হুকুম দিয়েছিলেন তোমরা ঐটুকু সময়ের মধ্যেই সেই পথ থেকে সরে গেছ।"},{"v":17,"ve":17,"vl":"17","bn":"কাজেই আমি সেই পাথরের ফলক দু’টা আমার হাত থেকে ছুঁড়ে ফেলে দিলাম। তোমাদের চোখের সামনেই সেই দু’টি টুকরা টুকরা হয়ে ভেংগে গেল।"},{"v":18,"ve":18,"vl":"18","bn":"“মাবুদের চোখে খারাপ এমন সব গুনাহ্‌ করে তোমরা তাঁর রাগ জাগিয়ে তুলেছিলে বলে আমি আগের বারের মত আবার চল্লিশ দিন ও চল্লিশ রাত মাবুদের সামনে উবুড় হয়ে পড়ে রইলাম; পানি বা রুটি কিছুই মুখে দিলাম না।"},{"v":19,"ve":19,"vl":"19","bn":"মাবুদের ভীষণ রাগকে আমি ভয় করেছিলাম, কারণ তোমাদের ধ্বংস করে ফেলবার মত রাগ তাঁর হয়েছিল। কিন্তু এবারও মাবুদ আমার কথা শুনেছিলেন।"},{"v":20,"ve":20,"vl":"20","bn":"হারুনকে ধ্বংস করে ফেলবার মত রাগও তাঁর হয়েছিল কিন্তু সেই সময় আমি হারুনের জন্যও মিনতি করেছিলাম।"},{"v":21,"ve":21,"vl":"21","bn":"তোমাদের সেই গুনাহের জিনিসটা, অর্থাৎ তোমাদের তৈরী সেই বাছুরটা নিয়ে আমি আগুনে পুড়িয়ে দিয়েছিলাম। তারপর আমি সেটা ধুলার মত গুঁড়া করে নিয়ে পাহাড় থেকে বয়ে আসা নদীর স্রোতে ফেলে দিয়েছিলাম।"},{"v":22,"ve":22,"vl":"22","bn":"“তবিয়েরাতে, মঃসাতে ও কিব্রোৎ-হত্তাবাতেও তোমরা মাবুদের রাগ জাগিয়ে তুলেছিলে।"},{"v":23,"ve":23,"vl":"23","bn":"মাবুদ কাদেশ-বর্ণেয় থেকে তোমাদের রওনা করে দেবার সময়ে বলেছিলেন, ‘যে দেশ আমি তোমাদের দিয়েছি তোমরা গিয়ে তা অধিকার কর।’ কিন্তু তোমরা তোমাদের মাবুদ আল্লাহ্‌র হুকুমের বিরুদ্ধে বিদ্রোহ করলে। তোমরা তাঁকে বিশ্বাসও কর নি, তাঁর কথায় কানও দাও নি।"},{"v":24,"ve":24,"vl":"24","bn":"আমি যখন থেকে তোমাদের জেনেছি তখন থেকেই দেখছি যে, তোমরা মাবুদের বিরুদ্ধে কেবল বিদ্রোহই করে চলেছ।"},{"v":25,"ve":25,"vl":"25","bn":"“মাবুদ তোমাদের ধ্বংস করে দেবার কথা বলেছিলেন বলে আমি সেই চল্লিশ দিন আর চল্লিশ রাত মাবুদের সামনে উবুড় হয়ে পড়ে ছিলাম।"},{"v":26,"ve":26,"vl":"26","bn":"তাঁর কাছে আমি এই বলে মুনাজাত করেছিলাম, ‘হে আল্লাহ্‌ মালিক, তোমার বান্দাদের তুমি ধ্বংস করে ফেলো না। তারা তো তোমারই সম্পত্তি যাদের তুমি তোমার মহাশক্তি দ্বারা মুক্ত করেছ এবং তোমার শক্তিশালী হাত ব্যবহার করে মিসর দেশ থেকে বের করে এনেছ।"},{"v":27,"ve":27,"vl":"27","bn":"তোমার গোলাম ইব্রাহিম, ইসহাক ও ইয়াকুবের কথা মনে কর। এই লোকদের একগুঁয়েমি, খারাপী ও গুনাহের দিকে চেয়ে দেখো না।"},{"v":28,"ve":28,"vl":"28","bn":"তা করলে যে দেশ থেকে তুমি আমাদের বের করে এনেছ সেই দেশের লোকেরা বলবে, মাবুদ তাঁর ওয়াদা করা দেশে তাদের নিয়ে যেতে পারেন নি বলে কিংবা তিনি তাদের ঘৃণা করেন বলে তাদের মেরে ফেলবার জন্য এই মরুভূমিতে নিয়ে এসেছেন।"},{"v":29,"ve":29,"vl":"29","bn":"কিন্তু এরা তো তোমারই বান্দা, তোমারই সম্পত্তি যাদের তুমি তোমার হাত বাড়িয়ে দিয়ে মহাশক্তিতে বের করে এনেছ।’"}],"10":[{"heading":"দ্বিতীয়বার পাথরের ফলক দেওয়া","v":1,"ve":1,"vl":"1","bn":"“সেই সময় মাবুদ আমাকে বলেছিলেন, ‘তুমি দুই টুকরা পাথর কেটে আগের পাথর-ফলক দু’টার মত করে নাও এবং পাহাড়ের উপরে আমার কাছে উঠে এস। সেই সংগে কাঠের একটি সিন্দুকও তৈরী করে নিয়ো।"},{"v":2,"ve":2,"vl":"2","bn":"আগের যে ফলক দু’টা তুমি ভেংগে ফেলেছ তার উপর যে কথা লেখা ছিল আমি তা-ই এই ফলক দু’টার উপর লিখে দেব। তারপর তুমি সেই দু’টা নিয়ে সিন্দুকটির মধ্যে রাখবে।’"},{"v":3,"ve":3,"vl":"3","bn":"“সেইজন্য আমি বাবলা কাঠ দিয়ে একটি সিন্দুক তৈরী করলাম এবং দুই টুকরা পাথর কেটে আগের ফলক দু’টার মত করে নিলাম। তারপর সেই দু’টা হাতে করে পাহাড়ের উপর উঠে গেলাম।"},{"v":4,"ve":4,"vl":"4","bn":"মাবুদ প্রথম ফলক দু’টার উপর যে কথা লিখেছিলেন এই দু’টার উপরও তা-ই লিখে ফলক দু’টা আমাকে দিলেন। সেই কথাগুলোই হল তাঁর সেই দশ হুকুম যা তিনি তোমাদের সকলের একসংগে জমায়েত হওয়ার দিনে পাহাড়ের উপর আগুনের মধ্য থেকে তোমাদের কাছে ঘোষণা করেছিলেন।"},{"v":5,"ve":5,"vl":"5","bn":"তারপর মাবুদের হুকুম মত আমি পাহাড় থেকে নীচে নেমে এসে আমার তৈরী করা সেই সিন্দুকটার মধ্যে ফলক দু’টা রাখলাম। সেগুলো এখনও সেখানে আছে।”"},{"v":6,"ve":6,"vl":"6","bn":"বনি-ইসরাইলরা পরে বেরোৎ-বনে-যাকন থেকে রওনা হয়ে মোষেরোতে পৌঁছেছিল। সেখানেই হারুন মারা গিয়েছিলেন এবং তাঁকে দাফন করা হয়েছিল। তাঁর ছেলে ইলিয়াসর তাঁর জায়গায় মহা-ইমাম হয়েছিলেন।"},{"v":7,"ve":7,"vl":"7","bn":"তারপর বনি-ইসরাইলরা গুধগোদায় গিয়েছিল এবং সেখান থেকে গিয়েছিল যট্‌বাথায়। যট্‌বাথায় অনেকগুলো ছোট নদী ছিল।"},{"v":8,"ve":8,"vl":"8","bn":"সেই সময় মাবুদ তাঁর সাক্ষ্য-সিন্দুক বয়ে নেবার জন্য এবং ইমাম-কাজের উদ্দেশ্যে তাঁর সামনে দাঁড়াবার জন্য আর তাঁর নামে দোয়া উচ্চারণ করবার জন্য লেবীয়দের বেছে নিয়েছিলেন। এই সব কাজ তারা আজও করছে।"},{"v":9,"ve":9,"vl":"9","bn":"সেইজন্যই লেবীয়রা তাদের ইসরাইলীয় ভাইদের মধ্যে সম্পত্তির কোন ভাগ বা অধিকার পায় নি; তোমাদের মাবুদ আল্লাহ্‌র কথা অনুসারে মাবুদই তাদের সম্পত্তি।"},{"v":10,"ve":10,"vl":"10","bn":"“আগের বারের মত সেই বারও আমি চল্লিশ দিন আর চল্লিশ রাত পাহাড়ের উপর ছিলাম আর সেই বারও মাবুদ আমার কথা শুনেছিলেন। তোমাদের ধ্বংস করে দেবার ইচ্ছা তাঁর ছিল না।"},{"v":11,"ve":11,"vl":"11","bn":"মাবুদ আমাকে বলেছিলেন, ‘তুমি গিয়ে তাদের পরিচালনা করে নিয়ে যাও, যাতে তাদের পূর্বপুরুষদের কাছে আমি যে দেশ দেবার কসম খেয়েছিলাম সেখানে গিয়ে তারা তা অধিকার করে নিতে পারে।’"},{"heading":"আল্লাহ্‌তা’লা কি চান?","v":12,"ve":13,"vl":"12-13","bn":"“বনি-ইসরাইলরা, তোমাদের মাবুদ আল্লাহ্‌ এখন তোমাদের কাছ থেকে কি চান? তিনি কেবল চান যেন তোমরা তোমাদের মাবুদ আল্লাহ্‌কে ভয় কর, সব ব্যাপারে তাঁর পথে চল, তাঁকে মহব্বত কর, তোমাদের সমস্ত মনপ্রাণ দিয়ে তাঁর এবাদত কর আর তোমাদের ভালোর জন্য আজ আমি তোমাদের কাছে মাবুদের যে সব হুকুম ও নিয়ম দিচ্ছি তা পালন কর।"},{"v":14,"ve":14,"vl":"14","bn":"“আসমান ও তার উপরকার সব কিছু এবং দুনিয়া ও তার মধ্যেকার সব কিছুই তোমাদের মাবুদ আল্লাহ্‌র।"},{"v":15,"ve":15,"vl":"15","bn":"তবুও তোমাদের পূর্বপুরুষদের প্রতি তাঁর টান ছিল বলে তিনি তাদের মহব্বত করেছিলেন। তিনি সমস্ত জাতির মধ্য থেকে তাদের বংশধরদের, অর্থাৎ তোমাদের বেছে নিয়েছেন আর আজও তোমরা সেই বেছে নেওয়া জাতিই আছ।"},{"v":16,"ve":16,"vl":"16","bn":"সেইজন্য তোমরা তোমাদের দিলের খৎনা করাও; একগুঁয়ে হয়ে আর থেকো না।"},{"v":17,"ve":17,"vl":"17","bn":"তোমাদের মাবুদ আল্লাহ্‌ সব দেব-দেবীর উপরে এবং তিনি মালিকদের মালিক। তিনি মহান, শক্তিশালী এবং ভয় জাগানো আল্লাহ্‌। তিনি কারও পক্ষ নেন না এবং ঘুষও খান না।"},{"v":18,"ve":18,"vl":"18","bn":"এতিম ও বিধবাদের অধিকার তিনি রক্ষা করেন এবং তোমাদের মধ্যে বাস করা বিদেশীদের খেতে পরতে দিয়ে তাঁর মহব্বত দেখান। তিনি তাদের খেতে পরতে দেন।"},{"v":19,"ve":19,"vl":"19","bn":"তোমরাও বিদেশী বাসিন্দাদের মহব্বত কোরো, কারণ মিসরে তোমরাও বিদেশী বাসিন্দা ছিলে।"},{"v":20,"ve":20,"vl":"20","bn":"তোমরা তোমাদের মাবুদ আল্লাহ্‌কে ভয় করবে এবং তাঁর এবাদত করবে; তাঁকেই আঁকড়ে ধরে থাকবে এবং তাঁর নামেই কসম খাবে।"},{"v":21,"ve":21,"vl":"21","bn":"তিনিই তোমাদের প্রশংসা, তিনিই তোমাদের আল্লাহ্‌। তোমরা নিজেদের চোখে যে সব মহৎ ও ভয় জাগানো কুদরতি দেখেছ তা তিনি তোমাদের জন্যই করেছেন।"},{"v":22,"ve":22,"vl":"22","bn":"তোমাদের যে পূর্বপুরুষেরা মিসরে গিয়েছিলেন তাঁরা সংখ্যায় ছিলেন মাত্র সত্তরজন আর এখন তোমাদের মাবুদ আল্লাহ্‌ তোমাদের সংখ্যা করেছেন আসমানের তারার মত অসংখ্য।"}],"11":[{"heading":"মাবুদকে মহব্বত করা ও তাঁর হুকুম পালনের নির্দেশ","v":1,"ve":1,"vl":"1","bn":"“তোমাদের মাবুদ আল্লাহ্‌কে মহব্বত করবে আর তিনি যা চান তা করবে এবং তাঁর নিয়ম, নির্দেশ ও হুকুম সব সময় পালন করবে।"},{"v":2,"ve":2,"vl":"2","bn":"আজ তোমরা মনে রেখো যে, আমি এই সব কথা তোমাদেরই বলছি, তোমাদের ছেলেমেয়েদের কাছে বলছি না, কারণ তারা তোমাদের মাবুদ আল্লাহ্‌র গড়ে তুলবার কাজ জানেও নি দেখেও নি। তারা তাঁর মহিমা এবং তাঁর বাড়িয়ে দেওয়া কঠোর ও শক্তিশালী হাত দেখে নি।"},{"v":3,"ve":3,"vl":"3","bn":"মিসরের মধ্যে মিসরের বাদশাহ্‌ ফেরাউন ও তাঁর সারা দেশের উপর তিনি যে সব চিহ্ন কাজ এবং অন্যান্য কাজ করেছিলেন তা-ও তারা দেখে নি।"},{"v":4,"ve":4,"vl":"4","bn":"মিসরীয় সৈন্যদল, তাদের ঘোড়া ও রথগুলোর প্রতি তিনি যা করেছিলেন এবং তারা যখন তোমাদের পিছনে তাড়া করে আসছিল তখন কেমন করে তিনি লোহিত সাগরের পানিতে তাদের ডুবিয়ে দিয়েছিলেন আর কেমন করে তাদের সম্পূর্ণভাবে ধ্বংস করে দিয়েছিলেন তা-ও তারা দেখে নি।"},{"v":5,"ve":5,"vl":"5","bn":"তোমরা এখানে এসে না পৌঁছানো পর্যন্ত তিনি মরুভূমিতে তোমাদের জন্য যা করেছিলেন তা-ও তোমাদের ছেলেমেয়েরা দেখে নি।"},{"v":6,"ve":6,"vl":"6","bn":"তিনি রূবেণ-গোষ্ঠীর ইলীয়াবের ছেলে দাথন ও অবীরামের প্রতি যা করেছিলেন, অর্থাৎ যেভাবে সমস্ত বনি-ইসরাইলদের মাঝখানে দুনিয়া মুখ খুলে তাদের ও তাদের পরিবারের লোকজন, তাদের তাম্বু এবং তাদের সমস্ত প্রাণীকে গিলে ফেলেছিল তা-ও তারা দেখে নি।"},{"v":7,"ve":7,"vl":"7","bn":"কিন্তু মাবুদের এই সব বড় বড় কাজ তোমরাই নিজেদের চোখে দেখেছ।"},{"v":8,"ve":9,"vl":"8-9","bn":"“কাজেই যে দেশ দখল করবার জন্য তোমরা জর্ডান নদী পার হয়ে যাচ্ছ সেখানে গিয়ে যেন তা দখল করবার শক্তি পাও এবং মাবুদ তোমাদের পূর্বপুরুষ ও তাদের বংশধরদের কাছে দুধ আর মধুতে ভরা যে দেশ দেবার ওয়াদা করেছিলেন সেখানে অনেক দিন বাঁচতে পার সেইজন্য আজ আমি তোমাদের যে সব হুকুম দিচ্ছি তা পালন করবে।"},{"v":10,"ve":10,"vl":"10","bn":"তোমরা যে দেশটা দখল করতে যাচ্ছ সেটা মিসর দেশের মত নয় যেখান থেকে তোমরা এসেছ। তোমরা সেখানে বীজ বুনতে, আর সবজী ক্ষেতে যেমন করা হয় তেমনি করে সেখানে পা দিয়ে পানি সেচের কাজ করতে।"},{"v":11,"ve":11,"vl":"11","bn":"কিন্তু জর্ডান নদী পার হয়ে যে দেশটা তোমরা দখল করতে যাচ্ছ সেটা পাহাড় আর উপত্যকায় ভরা; সেই দেশ পানি পায় আসমান থেকে।"},{"v":12,"ve":12,"vl":"12","bn":"সেই দেশের দেখাশোনা তোমাদের মাবুদ আল্লাহ্‌ই করেন। বছরের শুরু থেকে শেষ পর্যন্ত সব সময় তাঁর চোখ সেই দেশের উপর রয়েছে।"},{"v":13,"ve":13,"vl":"13","bn":"“কাজেই তোমাদের মাবুদ আল্লাহ্‌কে মহব্বত করা ও সমস্ত মনপ্রাণ দিয়ে তাঁর এবাদত করবার যে হুকুম আজ আমি তোমাদের দিলাম তা তোমরা বিশ্বস্তভাবে পালন করবে।"},{"v":14,"ve":14,"vl":"14","bn":"তা করলে মাবুদ সময়মত, অর্থাৎ শরৎ ও বসন্তকালে তোমাদের দেশের উপর বৃষ্টি দেবেন যার ফলে তোমরা প্রচুর শস্য, নতুন আংগুর-রস ও তেল পাবে।"},{"v":15,"ve":15,"vl":"15","bn":"মাবুদ তোমাদের পশুপালের জন্য মাঠে ঘাস হতে দেবেন। তা ছাড়া তোমরাও প্রাণ ভরে খেতে পাবে।"},{"v":16,"ve":16,"vl":"16","bn":"“তোমরা কিন্তু সতর্ক থেকো, তা না হলে তোমরা ছলনায় পড়ে মাবুদের কাছ থেকে সরে যাবে এবং দেব-দেবীর সেবা ও পূজা করবে।"},{"v":17,"ve":17,"vl":"17","bn":"এতে তোমাদের উপর মাবুদের রাগের আগুন জ্বলে উঠবে এবং তিনি আসমানের দরজা বন্ধ করে দেবেন, যার ফলে বৃষ্টিও হবে না এবং জমিতে ফসলও হবে না। যে চমৎকার দেশটা মাবুদ তোমাদের দিচ্ছেন সেখান থেকে তোমরা অল্প সময়ের মধ্যেই শেষ হয়ে যাবে।"},{"v":18,"ve":18,"vl":"18","bn":"তোমাদের দিল ও মনে আমার এই কথাগুলো গেঁথে রাখবে, তা মনে রাখবার চিহ্ন হিসাবে হাতে বেঁধে রাখবে এবং কপালে লাগিয়ে রাখবে।"},{"v":19,"ve":19,"vl":"19","bn":"তোমাদের ছেলেমেয়েদের সেগুলো শিখাবে। ঘরে বসে থাকবার সময়, পথে চলবার সময়, শোবার সময় এবং বিছানা থেকে উঠবার সময় তোমরা এই সব বিষয় নিয়ে আলোচনা করবে।"},{"v":20,"ve":20,"vl":"20","bn":"তোমাদের বাড়ীর দরজায় ও চৌকাঠে তোমরা সেগুলো লিখে রাখবে।"},{"v":21,"ve":21,"vl":"21","bn":"যদি তোমরা এই সব কর তবে যে দেশ দেবার কসম মাবুদ তোমাদের পূর্বপুরুষদের কাছে খেয়েছিলেন সেই দেশে তোমরা ও তোমাদের ছেলেমেয়েরা ততকাল বেঁচে থাকবে যতকাল এই দুনিয়ার উপর আসমান থাকবে।"},{"v":22,"ve":22,"vl":"22","bn":"“তোমাদের মাবুদ আল্লাহ্‌কে মহব্বত করবার, তাঁর পথে চলবার এবং তাঁকে আঁকড়ে ধরে রাখবার এই যে সব হুকুম আমি তোমাদের দিলাম তা তোমরা যত্নের সংগে পালন করবে।"},{"v":23,"ve":23,"vl":"23","bn":"তা করলে মাবুদই তোমাদের সামনে থেকে ঐ সব জাতিগুলোকে বের করে দেবেন, আর তোমরা তোমাদের চেয়েও বড় বড় এবং শক্তিশালী জাতিকে বেদখল করবে।"},{"v":24,"ve":24,"vl":"24","bn":"দক্ষিণের মরুভূমি থেকে লেবানন পর্যন্ত এবং ফোরাত নদী থেকে ভূমধ্যসাগর পর্যন্ত তোমরা যেখানে পা ফেলবে সেই জায়গাই তোমাদের হবে।"},{"v":25,"ve":25,"vl":"25","bn":"কোন লোকই তোমাদের সামনে দাঁড়াতে পারবে না। তোমরা সেই দেশের যেখানেই যাবে তোমাদের মাবুদ আল্লাহ্‌ তাঁর ওয়াদা অনুসারে সেখানকার লোকদের মনে তোমাদের সম্বন্ধে একটা ভয়ের ভাব ও কাঁপুনি ধরিয়ে দেবেন।"},{"heading":"আল্লাহ্‌র দোয়া ও বদদোয়া","v":26,"ve":26,"vl":"26","bn":"“দেখ, আজ আমি তোমাদের সামনে একটা দোয়া ও একটা বদদোয়া তুলে ধরছি।"},{"v":27,"ve":27,"vl":"27","bn":"আজ আমি তোমাদের কাছে তোমাদের মাবুদ আল্লাহ্‌র যে হুকুমগুলো দিলাম তা যদি তোমরা পালন কর, তবে এই দোয়া তোমরা পাবে।"},{"v":28,"ve":28,"vl":"28","bn":"কিন্তু যদি তোমরা তোমাদের মাবুদ আল্লাহ্‌র হুকুম অমান্য কর এবং যে পথে চলবার হুকুম আমি আজ দিয়েছি তা থেকে সরে গিয়ে তোমাদের কাছে নতুন এমন দেব-দেবীর পিছনে যাও, তবে তোমাদের উপর বদদোয়া পড়বে।"},{"v":29,"ve":29,"vl":"29","bn":"দখল করবার জন্য তোমরা যে দেশে ঢুকতে যাচ্ছ তোমাদের মাবুদ আল্লাহ্‌ যখন সেই দেশে তোমাদের নিয়ে যাবেন তখন গরিষীম পাহাড়ের উপর থেকে সেই দোয়ার কথা তোমরা ঘোষণা করবে আর বদদোয়ার কথা ঘোষণা করবে এবল পাহাড়ের উপর থেকে।"},{"v":30,"ve":30,"vl":"30","bn":"তোমরা তো জান, জর্ডান নদীর পশ্চিম দিকের রাস্তার পশ্চিমে গিল্‌গলের কাছাকাছি আরবার বাসিন্দা কেনানীয়দের দেশের মধ্যে মোরির এলোন গাছগুলোর কাছে ঐ পাহাড় দু’টা রয়েছে।"},{"v":31,"ve":32,"vl":"31-32","bn":"তোমাদের মাবুদ আল্লাহ্‌ যে দেশ তোমাদের দিতে যাচ্ছেন সেই দেশ দখল করবার জন্য তোমরা জর্ডান নদী পার হতে যাচ্ছ। তোমরা যখন তা দখল করে সেখানে বাস করতে থাকবে তখন আজ আমি তোমাদের যে সব নিয়ম ও নির্দেশ দিলাম তা অবশ্যই তোমরা পালন করে চলবে।"}],"12":[{"heading":"একটিমাত্র এবাদতের স্থান","v":1,"ve":1,"vl":"1","bn":"“তোমাদের পূর্বপুরুষদের মাবুদ আল্লাহ্‌ যে দেশ তোমাদের দখল করবার জন্য দিয়েছেন সেখানে সারা জীবন এই সব নিয়ম ও নির্দেশ যত্নের সংগে তোমাদের পালন করতে হবে।"},{"v":2,"ve":2,"vl":"2","bn":"তোমরা যে সমস্ত জাতিদের বেদখল করতে যাচ্ছ তারা যে সব ছোট-বড় পাহাড়ের উপরে ও ডালপালা ছড়ানো সবুজ গাছের নীচে তাদের দেব-দেবীর পূজা করে সেই জায়গাগুলো তোমরা সম্পূর্ণভাবে ধ্বংস করে দেবে।"},{"v":3,"ve":3,"vl":"3","bn":"তাদের বেদীগুলো ভেংগে দেবে, পূজার পাথরগুলো চুরমার করে দেবে, পূজার আশেরা-খুঁটিগুলো পুড়িয়ে দেবে, দেব-দেবীর মূর্তিগুলো ভেংগে ফেলে দেবে এবং এইভাবে সেই সব জায়গা থেকে তাদের দেব-দেবীদের নাম মুছে ফেলবে।"},{"v":4,"ve":4,"vl":"4","bn":"“তোমরা তোমাদের মাবুদ আল্লাহ্‌র এবাদত তাদের পূজার মত করে করবে না।"},{"v":5,"ve":5,"vl":"5","bn":"কিন্তু তোমাদের মাবুদ আল্লাহ্‌ নিজেকে প্রকাশ করবার জন্য তোমাদের সব গোষ্ঠীকে দেওয়া জায়গা থেকে যে জায়গাটা তাঁর বাসস্থান হিসাবে বেছে নেবেন তোমরা সেখানেই তাঁর এবাদতের জন্য যাবে।"},{"v":6,"ve":6,"vl":"6","bn":"তোমরা তোমাদের পোড়ানো-কোরবানী এবং অন্যান্য পশু-কোরবানী, তোমাদের আয়ের দশ ভাগের এক ভাগ, তোমাদের বিশেষ দান এবং মানত-পূরণের কোরবানী, তোমাদের নিজেদের ইচ্ছায় করা কোরবানী এবং তোমাদের গরু-ছাগল-ভেড়ার প্রথম বাচ্চা সেখানেই নিয়ে যাবে।"},{"v":7,"ve":7,"vl":"7","bn":"সেখানেই তোমাদের মাবুদ আল্লাহ্‌র সামনে তোমরা ও তোমাদের পরিবারের লোকেরা খাওয়া-দাওয়া করবে এবং তাঁর দোয়া অনুসারে পাওয়া তোমাদের পরিশ্রমের ফল নিয়ে তোমরা আনন্দ করবে।"},{"v":8,"ve":9,"vl":"8-9","bn":"“তোমাদের মাবুদ আল্লাহ্‌ শান্তিতে বাস করবার জন্য যে সম্পত্তি তোমাদের দিতে যাচ্ছেন তোমরা এখনও সেখানে পৌঁছাও নি। তোমরা সেই দেশে গেলে পর আমরা যেমন আজ এখানে যার চোখে যা ভাল তা-ই করছি তোমরা সেখানে তা করবে না।"},{"v":10,"ve":10,"vl":"10","bn":"তোমাদের মাবুদ আল্লাহ্‌ সম্পত্তি হিসাবে যে দেশ তোমাদের দিচ্ছেন তোমরা জর্ডান নদী পার হয়ে গিয়ে যখন সেই দেশে বাস করতে থাকবে তখন তিনি তোমাদের চারপাশের শত্রুদের সংগে লড়াই থেকে তোমাদের বিশ্রাম দেবেন, আর তোমরা নিরাপদে সেখানে বাস করতে পারবে।"},{"v":11,"ve":11,"vl":"11","bn":"তখন তিনি নিজেকে প্রকাশ করবার জন্য যে জায়গাটা তাঁর বাসস্থান হিসাবে বেছে নেবেন সেখানে তোমরা আমার হুকুম করা সব জিনিস নিয়ে আসবে- তোমাদের পোড়ানো-কোরবানী ও অন্যান্য পশু-কোরবানী, তোমাদের আয়ের দশ ভাগের এক ভাগ, বিশেষ দান এবং তোমাদের বাছাই করা জিনিস যা তোমরা মাবুদের কাছে মানত করেছ।"},{"v":12,"ve":12,"vl":"12","bn":"সেখানে তোমাদের মাবুদ আল্লাহ্‌র সামনে তোমরা, তোমাদের ছেলেমেয়েরা, তোমাদের গোলামেরা এবং তোমাদের গ্রাম ও শহরের লেবীয়রা যাদের নিজের বলতে কোন জায়গা-জমি কিংবা সম্পত্তি নেই তোমরা সবাই আনন্দ করবে।"},{"v":13,"ve":13,"vl":"13","bn":"দেখো, যেন তোমাদের খুশীমত যে কোন জায়গায় তোমরা পোড়ানো-কোরবানী না কর।"},{"v":14,"ve":14,"vl":"14","bn":"তোমাদের গোষ্ঠীগুলোকে দেওয়া জায়গা থেকে যে জায়গাটা মাবুদ বেছে নেবেন সেখানেই তোমরা ঐ সব পোড়ানো-কোরবানী দেবে আর সেখানেই তোমরা আমার হুকুম করা সব কিছু করবে।"},{"v":15,"ve":15,"vl":"15","bn":"“তবে তোমাদের মাবুদ আল্লাহ্‌ তোমাদের দোয়া করে যে সব পশু দেবেন তা তোমরা যে কোন গ্রামে বা শহরে জবাই করে তোমাদের খুশীমত গোশ্‌ত খেতে পারবে, যেমন করে তোমাদের পাক-নাপাক সব লোকেরা কৃষ্ণসার কিংবা হরিণের গোশ্‌ত খায়।"},{"v":16,"ve":16,"vl":"16","bn":"কিন্তু তোমাদের জন্য রক্ত খাওয়া হারাম; তা পানির মত করে মাটিতে ঢেলে দিতে হবে।"},{"v":17,"ve":17,"vl":"17","bn":"এছাড়া তোমাদের শস্য, নতুন আংগুর-রস ও তেলের দশ ভাগের এক ভাগ, গরু-ছাগল-ভেড়ার প্রথম বাচ্চা, তোমাদের মানত করা জিনিস, তোমাদের নিজের ইচ্ছায় করা কোন কোরবানী এবং বিশেষ দান তোমাদের নিজেদের গ্রাম বা শহরের মধ্যে খাওয়া চলবে না।"},{"v":18,"ve":18,"vl":"18","bn":"তোমাদের মাবুদ আল্লাহ্‌র বেছে নেওয়া জায়গায় তাঁর সামনে এগুলো তোমাদের খেতে হবে। তোমরা, তোমাদের ছেলেমেয়েরা, তোমাদের গোলামেরা এবং তোমাদের গ্রাম ও শহরের লেবীয়রা তা খাবে এবং তোমাদের পরিশ্রমের ফল নিয়ে তোমাদের মাবুদ আল্লাহ্‌র সামনে আনন্দ করবে।"},{"v":19,"ve":19,"vl":"19","bn":"তোমাদের দেশে তোমরা যতদিন বাস করবে ততদিন লেবীয়দের প্রতি তোমাদের খেয়াল রাখতে হবে।"},{"v":20,"ve":20,"vl":"20","bn":"“তোমাদের মাবুদ আল্লাহ্‌ তাঁর ওয়াদা অনুসারে তোমাদের দেশের সীমানা বাড়িয়ে দেবার পরে যখন তোমরা গোশ্‌ত খাবার ইচ্ছা নিয়ে বলবে, ‘গোশ্‌ত খাব,’ তখন তোমরা খুশীমত গোশ্‌ত খেতে পারবে।"},{"v":21,"ve":21,"vl":"21","bn":"তোমাদের মাবুদ আল্লাহ্‌ নিজেকে প্রকাশ করবার জন্য যে জায়গাটা বেছে নেবেন সেটা যদি তোমাদের কাছ থেকে অনেক দূরে হয়, তবে আমার দেওয়া হুকুম অনুসারে তোমরা মাবুদের দেওয়া গরু-ভেড়ার পাল থেকে পশু নিয়ে জবাই করতে পারবে এবং যার যার গ্রাম ও শহরে খুশীমত গোশ্‌ত খেতে পারবে।"},{"v":22,"ve":22,"vl":"22","bn":"কৃষ্ণসার কিংবা হরিণের গোশ্‌তের মতই তোমরা তা খাবে। পাক-নাপাক সবাই তা খেতে পারবে।"},{"v":23,"ve":23,"vl":"23","bn":"কিন্তু সাবধান! রক্ত খাবে না, কারণ রক্তই হল প্রাণ, আর তোমরা গোশ্‌তের সংগে সেই প্রাণ খাবে না।"},{"v":24,"ve":24,"vl":"24","bn":"তোমরা রক্ত খাবে না, তা পানির মত করে মাটিতে ঢেলে দেবে।"},{"v":25,"ve":25,"vl":"25","bn":"তোমাদের ও তোমাদের পরে তোমাদের সন্তানদের যাতে উন্নতি হয় সেইজন্য তোমরা রক্ত খাবে না; তাহলে মাবুদের চোখে যা ভাল তা-ই করা হবে।"},{"v":26,"ve":26,"vl":"26","bn":"“মাবুদের বেছে নেওয়া জায়গায় তোমাদের পাক-পবিত্র জিনিস এবং মানতের জিনিস নিয়ে যেতে হবে।"},{"v":27,"ve":27,"vl":"27","bn":"তোমাদের মাবুদ আল্লাহ্‌র কোরবানগাহের উপর তোমরা তোমাদের পোড়ানো-কোরবানীর গোশ্‌ত ও রক্ত কোরবানী দেবে। তোমাদের মাবুদ আল্লাহ্‌র কোরবানগাহের গায়ে তোমাদের কোরবানী করা পশুর রক্ত ঢেলে দিতে হবে, কিন্তু তার গোশ্‌ত তোমরা খেতে পারবে।"},{"v":28,"ve":28,"vl":"28","bn":"তোমাদের ও তোমাদের পরে তোমাদের ছেলেমেয়েদের যাতে সব সময় উন্নতি হয় সেইজন্য আমার দেওয়া এই সব হুকুম তোমরা যত্নের সংগে পালন করবে, কারণ তা করলে তোমাদের মাবুদ আল্লাহ্‌র চোখে যা ন্যায় এবং ভাল তা-ই করা হবে।"},{"v":29,"ve":30,"vl":"29-30","bn":"“যে সব জাতিদের তোমরা বেদখল করতে যাচ্ছ তোমাদের মাবুদ আল্লাহ্‌ তোমাদের সামনে থেকে তাদের একেবারে ধ্বংস করে দেবেন। কিন্তু তাদের বেদখল করবার পর যখন তোমরা তাদের দেশে বাস করবে তখন সাবধান হবে যাতে তোমাদের সামনে থেকে তারা ধ্বংস হয়ে যাওয়ার পর তাদের দেব-দেবীর বিষয় খোঁজ নিতে গিয়ে তোমরা ফাঁদে না পড় এবং জিজ্ঞাসা না কর, ‘এই সব জাতি কেমন করে তাদের দেব-দেবীর পূজা করত?’ আর শেষে বল, ‘আমরাও তা-ই করব।’"},{"v":31,"ve":31,"vl":"31","bn":"তোমরা তোমাদের মাবুদ আল্লাহ্‌র এবাদত তাদের পূজার মত করে করবে না, কারণ তাদের দেব-দেবীর পূজায় তারা এমন সব জঘন্য কাজ করে যা মাবুদ ঘৃণা করেন। এমন কি, তারা তাদের দেব-দেবীর কাছে তাদের ছেলেমেয়েদের আগুনে পুড়িয়ে কোরবানী করে।"},{"v":32,"ve":32,"vl":"32","bn":"“আমি তোমাদের যে যে হুকুম দিলাম সেই সব তোমরা পালন করবে; এর সংগে কিছু যোগও দেবে না, আবার এর থেকে কিছু বাদও দেবে না।"}],"13":[{"heading":"ভণ্ড নবী ও মূর্তি পূজাকারীদের শাস্তি","v":1,"ve":2,"vl":"1-2","bn":"“ধরে নাও, তোমাদের মধ্যে কোন নবী বা স্বপ্ন দেখে ভবিষ্যতের কথা বলতে পারে এমন কেউ দেখা দিল এবং তোমাদের কাছে কোন চিহ্ন বা কুদরতির কথা বলল আর তা সত্যিই ঘটল। সেই লোকও যদি তোমাদের কাছে নতুন এমন দেব-দেবীর সম্বন্ধে বলে, ‘চল, আমরা দেব-দেবীর কাছে গিয়ে তাদের পূজা করি,’"},{"v":3,"ve":3,"vl":"3","bn":"তবে তোমরা সেই নবী বা স্বপ্নদেখা লোকের কথা শুনো না। তোমরা তোমাদের মাবুদ আল্লাহ্‌কে তোমাদের সব মনপ্রাণ দিয়ে মহব্বত কর কিনা তা তিনি তোমাদের পরীক্ষায় ফেলে দেখিয়ে দিচ্ছেন।"},{"v":4,"ve":4,"vl":"4","bn":"তোমাদের মাবুদ আল্লাহ্‌র কথামতই তোমাদের চলতে হবে এবং তাঁকেই ভয় করতে হবে। তোমরা তাঁর হুকুম পালন করবে ও তাঁর বাধ্য হয়ে চলবে; তোমরা তাঁর এবাদত করবে ও তাঁকেই আঁকড়ে ধরে থাকবে।"},{"v":5,"ve":5,"vl":"5","bn":"সেই নবী বা সেই স্বপ্নদেখা লোকটাকে হত্যা করতে হবে, কারণ তোমাদের মাবুদ আল্লাহ্‌, যিনি মিসর থেকে তোমাদের বের করে এনেছেন এবং সেই গোলামীর দেশ থেকে তোমাদের মুক্ত করেছেন, সে তাঁরই বিরুদ্ধে বিদ্রোহের উসকানি দিয়েছে এবং তোমাদের মাবুদ আল্লাহ্‌ যে পথে চলতে তোমাদের হুকুম দিয়েছেন সেই পথ থেকে তোমাদের ফিরাতে চেষ্টা করেছে। তোমাদের মধ্য থেকে সেই খারাপী তোমরা শেষ করে দেবে।"},{"v":6,"ve":7,"vl":"6-7","bn":"“দুনিয়ার এক সীমানা থেকে অন্য সীমানা পর্যন্ত তোমার চারদিকের কাছের বা দূরের লোকেরা যে দেব-দেবীর পূজা করে, যারা তোমার এবং তোমার পূর্বপুরুষদের অজানা সেই দেব-দেবীর দিকে যদি তোমার নিজের ভাই কিংবা তোমার ছেলে বা মেয়ে কিংবা প্রিয় স্ত্রী কিংবা তোমার প্রাণের বন্ধু তোমাকে একা পেয়ে বিপথে নিয়ে যাওয়ার জন্য বলে, ‘চল, আমরা গিয়ে দেব-দেবীর পূজা করি,’"},{"v":8,"ve":8,"vl":"8","bn":"তবে তার ডাকে সাড়া দিয়ো না বা তার কথায় কান দিয়ো না। তাকে কোন দয়া দেখাবে না; তাকে রেহাই দেবে না, কিংবা তাকে রক্ষাও করবে না।"},{"v":9,"ve":9,"vl":"9","bn":"তাকে হত্যা করতেই হবে। তাকে হত্যা করবার কাজটা তুমি নিজের হাতেই শুরু করবে, তারপর অন্য সবাই যোগ দেবে।"},{"v":10,"ve":10,"vl":"10","bn":"যিনি তোমাকে মিসর দেশের গোলামী থেকে বের করে এনেছেন তোমার সেই মাবুদ আল্লাহ্‌র দিক থেকে সে তোমাকে ফিরাবার চেষ্টা করেছে বলে তাকে তুমি পাথর ছুঁড়ে হত্যা করবে।"},{"v":11,"ve":11,"vl":"11","bn":"তাতে বনি-ইসরাইলরা সকলে সেই কথা শুনে ভয় পাবে এবং তোমাদের মধ্যে কেউ আর এই রকম খারাপ কাজ করবে না।"},{"v":12,"ve":12,"vl":"12","bn":"“তোমাদের মাবুদ আল্লাহ্‌ যে সব গ্রাম বা শহর তোমাদের বাস করবার জন্য দিতে যাচ্ছেন তার কোনটা সম্বন্ধে হয়তো তোমরা শুনতে পাবে যে,"},{"v":13,"ve":13,"vl":"13","bn":"সেখানকার বনি-ইসরাইলদের মধ্যে কিছু দুষ্ট লোক দেখা দিয়েছে যারা সেখানকার লোকদের এই বলে বিপথে টেনে নিয়ে গিয়েছে, ‘চল, আমরা দেব-দেবীর পূজা করি,’ যে দেব-দেবী তোমাদের কাছে নতুন।"},{"v":14,"ve":14,"vl":"14","bn":"তা-ই যদি হয় তবে ব্যাপারটা তোমাদের খুব ভাল করে খোঁজ-খবর নিয়ে পরীক্ষা ও তদন্ত করে দেখতে হবে। আর তা যদি সত্যি বলে প্র্রমাণিত হয় যে, এই জঘন্য কাজ তোমাদের মধ্যে করা হয়েছে,"},{"v":15,"ve":15,"vl":"15","bn":"তবে সেখানকার সব বাসিন্দাদের অবশ্যই হত্যা করতে হবে। সেই গ্রাম বা শহর এবং তার লোকজন ও পশুপাল তোমরা সম্পূর্ণভাবে ধ্বংস করে দেবে।"},{"v":16,"ve":16,"vl":"16","bn":"সেখানকার সব লুট করা জিনিস তোমরা শহর-চকের মাঝখানে নিয়ে গিয়ে সমস্ত জিনিস ও সেই গ্রাম বা শহর তোমরা তোমাদের মাবুদের উদ্দেশে পোড়ানো-কোরবানীর মত করে সম্পূর্ণভাবে পুড়িয়ে দেবে। সেই জায়গাটা চিরদিনের জন্য যেন একটা ধ্বংসের স্তূপ হয়ে পড়ে থাকে; আর কখনও যেন সেটা তৈরী করা না হয়।"},{"v":17,"ve":17,"vl":"17","bn":"মাবুদ যাতে তাঁর ভয়ংকর রাগ থেকে ফেরেন সেইজন্য তোমাদের হাতে যেন এই সব জিনিসের একটাও দেখা না যায়, কারণ তার উপর রয়েছে ধ্বংসের বদদোয়া। তাহলে তিনি তোমাদের রহমত ও মমতা করবেন এবং তোমাদের পূর্বপুরুষদের কাছে কসম খাওয়া ওয়াদা অনুসারে তোমাদের বংশ বাড়িয়ে দেবেন,"},{"v":18,"ve":18,"vl":"18","bn":"কারণ আজ আমি তোমাদের যে সব হুকুম দিচ্ছি তা পালন করে এবং তাঁর চোখে যা ভাল তা-ই করে তোমরা তোমাদের মাবুদ আল্লাহ্‌র বাধ্য হয়েছ।"}],"14":[{"heading":"হালাল ও হারাম খাবার","v":1,"ve":1,"vl":"1","bn":"“তোমরা তোমাদের মাবুদ আল্লাহ্‌র সন্তান। সেইজন্য মৃত লোকদের জন্য শোক প্রকাশ করতে গিয়ে শরীরের কোন জায়গায় তোমাদের ক্ষত করা চলবে না, কিংবা মাথার সামনের চুল কামানো চলবে না।"},{"v":2,"ve":2,"vl":"2","bn":"তোমরা তোমাদের মাবুদ আল্লাহ্‌র উদ্দেশ্যে একটা পবিত্র জাতি। দুনিয়ার সমস্ত জাতিগুলোর মধ্য থেকে মাবুদ তোমাদের বেছে নিয়েছেন যাতে তোমরা তাঁর নিজের বিশেষ সম্পত্তি হও।"},{"v":3,"ve":3,"vl":"3","bn":"“তোমরা কোন ঘৃণার জিনিস খাবে না।"},{"v":4,"ve":4,"vl":"4","bn":"যে সব পশুর গোশ্‌ত তোমাদের জন্য হালাল সেগুলো হল গরু, ভেড়া, ছাগল,"},{"v":5,"ve":5,"vl":"5","bn":"হরিণ, কৃষ্ণসার, চিতি-হরিণ, বুনো ছাগল, পিছন সাদা হরিণ, সাদা হরিণ এবং পাহাড়ী ভেড়া।"},{"v":6,"ve":6,"vl":"6","bn":"যে সব পশুর খুর পুরোপুরি দুই ভাগে চেরা এবং যারা জাবর কাটে সেই সব পশুর গোশ্‌ত তোমাদের জন্য হালাল।"},{"v":7,"ve":7,"vl":"7","bn":"কিন্তু মাত্র জাবর কাটা কিংবা শুধু খুর চেরা পশুর গোশ্‌ত তোমাদের জন্য হারাম। তোমরা উট, খরগোস ও শাফন খাবে না, কারণ সেগুলো জাবর কাটলেও তাদের খুর চেরা নয়। তাই সেগুলো তোমাদের পক্ষে নাপাক।"},{"v":8,"ve":8,"vl":"8","bn":"শূকরও নাপাক; খুর চেরা হলেও সে জাবর কাটে না। তোমাদের জন্য এগুলোর গোশ্‌ত হারাম এবং তাদের মৃতদেহও ছোঁবে না।"},{"v":9,"ve":9,"vl":"9","bn":"“পানিতে বাস করা প্রাণীদের মধ্যে যেগুলোর ডানা ও আঁশ আছে সেগুলো তোমাদের জন্য হালাল,"},{"v":10,"ve":10,"vl":"10","bn":"কিন্তু যেগুলোর ডানা ও আঁশ নেই সেগুলো তোমাদের জন্য হারাম। তোমাদের পক্ষে সেগুলো নাপাক।"},{"v":11,"ve":18,"vl":"11-18","bn":"“যে কোন পাক-পবিত্র পাখী তোমাদের জন্য হালাল; কিন্তু ঈগল, শকুন ও কালো শকুন, শিকারী-বাজ এবং যে কোন রকমের চিল, যে কোন রকমের কাক, উটপাখী, লক্ষ্মীপেঁচা, গাংচিল, যে কোন রকমের বাজ পাখী, কাল্‌পেঁচা, হুতুম পেঁচা, সাদা পেঁচা, মরু-পেঁচা, সিন্দুবাজ, হাড়গিলা, সারস, যে কোন রকমের বক, হুপ্পু পাখী এবং বাদুড় তোমাদের জন্য হারাম।"},{"v":19,"ve":19,"vl":"19","bn":"“ঝাঁক বেঁধে উড়ে বেড়ায় এমন সব পোকা তোমাদের পক্ষে নাপাক। সেগুলো তোমাদের জন্য হারাম;"},{"v":20,"ve":20,"vl":"20","bn":"কিন্তু যে সব প্রাণীর ডানা আছে এবং পাক-পবিত্র সেগুলো তোমাদের জন্য হালাল।"},{"v":21,"ve":21,"vl":"21","bn":"“মরে পড়ে থাকা যে কোন প্রাণী তোমাদের জন্য হারাম, কারণ তোমরা তোমাদের মাবুদের উদ্দেশ্যে একটা পবিত্র জাতি। তোমাদের গ্রাম বা শহরে বাস করা অন্য জাতির কোন লোককে তোমরা সেটা দিয়ে দিতে পারবে এবং সে তা খেতে পারবে, কিংবা তোমরা কোন বিদেশীর কাছে সেটা বিক্রি করে দিতে পারবে। “ছাগলের বাচ্চার গোশ্‌ত তার মায়ের দুধে রান্না করবে না।"},{"heading":"বনি-ইসরাইলদের জাকাতের নিয়ম","v":22,"ve":22,"vl":"22","bn":"“প্রত্যেক বছর তোমাদের জমিতে যে সব ফসল হবে তার দশ ভাগের এক ভাগ তোমরা অবশ্যই আলাদা করে রাখবে।"},{"v":23,"ve":23,"vl":"23","bn":"তোমাদের মাবুদ আল্লাহ্‌কে যাতে তোমরা ভয় করতে শেখ সেইজন্য তোমাদের শস্য, নতুন আংগুর-রস ও তেলের দশ ভাগের এক ভাগ এবং তোমাদের পালের গরু-ভেড়া-ছাগলের প্রথম বাচ্চার গোশ্‌ত তোমাদের মাবুদ আল্লাহ্‌র সামনে তোমাদের এমন জায়গায় খেতে হবে যে জায়গাটা তিনি নিজেকে প্রকাশ করবার জন্য তাঁর বাসস্থান হিসাবে বেছে নেবেন।"},{"v":24,"ve":24,"vl":"24","bn":"কিন্তু যদি সেই জায়গা খুব দূরে হয় এবং তোমাদের মাবুদ আল্লাহ্‌ তোমাদের এত দোয়া করে থাকেন যে, সেই দশ ভাগের এক ভাগ মাবুদের সেই জায়গা অনেক দূর বলে তোমাদের পক্ষে বয়ে নিয়ে যাওয়া সম্ভব নয়,"},{"v":25,"ve":25,"vl":"25","bn":"তবে তা বিক্রি করে সেই টাকা নিয়ে তোমরা তোমাদের মাবুদ আল্লাহ্‌র সেই বেছে নেওয়া জায়গায় যাবে।"},{"v":26,"ve":26,"vl":"26","bn":"সেই টাকা দিয়ে তোমরা তোমাদের খুশীমত জিনিস কিনবে, যেমন গরু-ছাগল-ভেড়া, আংগুর-রস, অন্য কোন মদানো রস কিংবা তোমাদের খুশীমত আর কিছু। তারপর তোমরা তোমাদের পরিবার নিয়ে তোমাদের মাবুদ আল্লাহ্‌র সামনে খাওয়া-দাওয়া করে আনন্দ করবে।"},{"v":27,"ve":27,"vl":"27","bn":"যে লেবীয়রা তোমাদের গ্রাম বা শহরে বাস করে তাদের কথা তোমরা ভুলে যেয়ো না, কারণ নিজেদের বলতে তাদের কোন জায়গা-জমি বা সম্পত্তি নেই।"},{"v":28,"ve":28,"vl":"28","bn":"“প্রত্যেক তৃতীয় বছরের শেষে তোমাদের সেই বছরের ফসলের দশ ভাগের এক ভাগ শহরে নিয়ে এসে তোমরা জমা করবে।"},{"v":29,"ve":29,"vl":"29","bn":"এতে লেবীয়রা, যাদের নিজেদের বলতে কোন জায়গা-জমি বা সম্পত্তি নেই এবং সেখানকার বিদেশী বাসিন্দারা, বিধবারা আর এতিম ছেলেমেয়েরা প্রাণ ভরে খেতে পাবে। এতে তোমাদের সব কাজে তোমাদের মাবুদ আল্লাহ্‌ তোমাদের দোয়া করবেন।"}],"15":[{"heading":"ঋণ-মাফের বছর","v":1,"ve":1,"vl":"1","bn":"“প্রতি সপ্তম বছরের শেষে অন্যদের কাছ থেকে তোমাদের পাওনা সব মাফ করে দেবে।"},{"v":2,"ve":2,"vl":"2","bn":"এই নিয়মে তা মাফ করতে হবে: প্রত্যেক ইসরাইলীয় পাওনাদার অন্য ইসরাইলীয়কে দেওয়া সব ঋণ মাফ করে দেবে। ঋণ মাফ করে দেবার জন্য মাবুদ যে সময় ঠিক করে দিয়েছেন তা ঘোষণা করা হয়েছে বলে কোন ইসরাইলীয় ভাইয়ের কাছ থেকে ঋণ শোধের দাবি করা চলবে না।"},{"v":3,"ve":3,"vl":"3","bn":"ভিন্ন জাতির লোকদের কাছ থেকে ঋণ শোধের দাবি করা চলবে, কিন্তু তোমাদের ভাইদের ঋণ তোমাদের মাফ করে দিতে হবে।"},{"v":4,"ve":5,"vl":"4-5","bn":"যদি তোমরা সম্পূর্ণভাবে তোমাদের মাবুদ আল্লাহ্‌র কথার বাধ্য থাক এবং আজ আমি তোমাদের যে সব হুকুম দিচ্ছি তা মেনে চলবার দিকে মন দাও, তবে অবশ্য তোমাদের মধ্যে কারও গরীব থাকবার কথা নয়, কারণ সম্পত্তি হিসাবে যে দেশ তোমাদের মাবুদ আল্লাহ্‌ তোমাদের দিতে যাচ্ছেন সেখানে তিনি তোমাদের প্রচুর দোয়া করবেন।"},{"v":6,"ve":6,"vl":"6","bn":"তোমাদের মাবুদ আল্লাহ্‌ তাঁর ওয়াদা অনুসারে তোমাদের দোয়া করবেন, আর তাতে তোমরা অনেক জাতির লোককে ঋণ দেবে, কিন্তু কারও কাছ থেকে তোমাদের ঋণ নিতে হবে না। তোমরা অনেক জাতিকে শাসন করবে কিন্তু কেউ তোমাদের শাসন করবে না।"},{"v":7,"ve":7,"vl":"7","bn":"“তোমাদের মাবুদ আল্লাহ্‌ যে দেশ তোমাদের দিতে যাচ্ছেন সেই দেশের কোন জায়গায় যদি তোমাদের ভাইদের মধ্যে কেউ গরীব থাকে, তবে তার উপর তোমাদের দিল কঠিন কোরো না, কিংবা সেই গরীব ভাইয়ের জন্য তোমাদের হাত মুঠো করে রেখো না।"},{"v":8,"ve":8,"vl":"8","bn":"তোমাদের হাত যেন খোলা থাকে; তার দরকার মত তাকে অবশ্যই ধার দেবে।"},{"v":9,"ve":9,"vl":"9","bn":"সাবধান, তোমাদের মনে এই খারাপ চিন্তাকে আমল দিয়ো না যে, সপ্তম বছর, অর্থাৎ ঋণ মাফের বছর প্রায় এসে গেছে। এই চিন্তা করে তোমাদের সেই অভাবী ভাইয়ের প্রতি বিরুদ্ধ মনোভাব নিয়ে তাকে খালি হাতে বিদায় কোরো না। যদি তা কর তবে তা নিয়ে সে তোমাদের বিরুদ্ধে মাবুদের কাছে কাতর হয়ে বিচার চাইবে আর তোমরা অন্যায়ের জন্য দোষী হবে।"},{"v":10,"ve":10,"vl":"10","bn":"মনে অনিচ্ছার ভাব না রেখে খোলা হাতে তাকে দেবে; তাহলে তোমাদের মাবুদ আল্লাহ্‌ তোমাদের সব কাজে দোয়া করবেন এবং তোমরা যাতে হাত দেবে তাতেই দোয়া পাবে।"},{"v":11,"ve":11,"vl":"11","bn":"গরীব লোক অবশ্য দেশে সব সময়ই থাকবে। সেইজন্য আমি তোমাদের এই হুকুম দিচ্ছি যে, তোমাদের ভাইদের প্রতি এবং দেশের গরীব ও অভাবী লোকদের প্রতি তোমাদের হাত যেন খোলা থাকে।"},{"heading":"গোলামী থেকে মুক্তি দেবার নিয়ম","v":12,"ve":12,"vl":"12","bn":"“যদি কোন ইবরানী পুরুষ বা স্ত্রীলোককে তোমাদের কাছে বিক্রি করা হয়, তবে ছয় বছর কাজ করবার পরে সপ্তম বছরে তাকে অবশ্যই তোমাদের ছেড়ে দিতে হবে।"},{"v":13,"ve":13,"vl":"13","bn":"ছেড়ে দেবার সময়ে তাকে খালি হাতে বিদায় করবে না।"},{"v":14,"ve":14,"vl":"14","bn":"তোমরা তাকে খোলা হাতে তোমাদের পাল থেকে ছাগল ও ভেড়া, খামার থেকে শস্য এবং আংগুর মাড়াইয়ের জায়গা থেকে আংগুর-রস দেবে। তোমাদের মাবুদ আল্লাহ্‌ তোমাদের যে পরিমাণে দোয়া করেছেন তোমরা সেই পরিমাণেই তাকে দেবে।"},{"v":15,"ve":15,"vl":"15","bn":"মনে রেখো, মিসর দেশে তোমরাও গোলাম ছিলে এবং তোমাদের মাবুদ আল্লাহ্‌ তোমাদের মুক্ত করেছেন। সেইজন্য আজ আমি তোমাদের এই হুকুম দিচ্ছি।"},{"v":16,"ve":16,"vl":"16","bn":"“কিন্তু তোমাদের ও তোমাদের পরিবারের লোকদের প্রতি ভালবাসার দরুন এবং তোমাদের কাছে সুখে আছে বলে যদি সেই গোলাম জানায় যে, সে তোমাদের ছেড়ে যাবে না,"},{"v":17,"ve":17,"vl":"17","bn":"তবে তোমরা তার কানের লতি দরজার উপর রেখে তুরপুণ দিয়ে ছেঁদা করে দেবে; তাতে সে সারা জীবন তোমাদের গোলাম হয়ে থাকবে। তোমাদের বাঁদীর বেলায়ও তা-ই করবে।"},{"v":18,"ve":18,"vl":"18","bn":"“গোলাম কিংবা বাঁদীকে মুক্ত করে দেওয়াটা তোমার কোন কষ্টের ব্যাপার বলে মনে কোরো না, কারণ এই ছয় বছর সে তোমাদের জন্য যে কাজ করেছে তার দাম দু’জন মজুরের মজুরির সমান। তাদের মুক্ত করে দিলে তোমাদের মাবুদ আল্লাহ্‌ তোমাদের সব কিছুতে দোয়া করবেন।"},{"heading":"পশুর প্রথম পুরুষ-বাচ্চা সম্বন্ধে নিয়ম","v":19,"ve":19,"vl":"19","bn":"“তোমাদের গরু-ভেড়া ও ছাগলের প্রত্যেকটা প্রথম পুরুষ বাচ্চা তোমাদের মাবুদ আল্লাহ্‌র উদ্দেশ্যে আলাদা করে রাখবে। তোমাদের গরুর প্রথম বাচ্চাকে কাজে লাগাবে না এবং ছাগল ও ভেড়ার প্রথম বাচ্চার লোম কাটবে না।"},{"v":20,"ve":20,"vl":"20","bn":"তোমাদের মাবুদ আল্লাহ্‌র বেছে নেওয়া জায়গায় প্রত্যেক বছর তোমরা তোমাদের পরিবার নিয়ে তাঁর সামনে সেগুলোর গোশ্‌ত খাবে।"},{"v":21,"ve":21,"vl":"21","bn":"কিন্তু সেই সব পশুর কোনটার যদি কোন খুঁত থাকে, অর্থাৎ যদি সেটা খোঁড়া কিংবা অন্ধ হয় কিংবা তার গায়ে আর কোন বড় রকমের দোষ থাকে, তবে সেটা তোমাদের মাবুদ আল্লাহ্‌র উদ্দেশে কোরবানী দেবে না।"},{"v":22,"ve":22,"vl":"22","bn":"সেটা তোমরা নিজের জায়গাতেই খাবে। পাক-নাপাক যে কোন লোকই তা কৃষ্ণসার বা হরিণের গোশ্‌তের মতই খেতে পারবে।"},{"v":23,"ve":23,"vl":"23","bn":"কিন্তু তোমরা তার রক্ত খাবে না; পানির মত করে তা মাটিতে ঢেলে দেবে।"}],"16":[{"heading":"উদ্ধার-ঈদের পুনরালোচনা","v":1,"ve":1,"vl":"1","bn":"“আবীব মাসে তোমাদের মাবুদ আল্লাহ্‌র উদ্দেশে তোমরা উদ্ধার-ঈদ পালন করবে। এই আবীব মাসেই একদিন রাতের বেলায় তিনি মিসর দেশ থেকে তোমাদের বের করে এনেছিলেন।"},{"v":2,"ve":2,"vl":"2","bn":"নিজেকে প্রকাশ করবার জন্য মাবুদ তাঁর বাসস্থান হিসাবে যে জায়গাটা বেছে নেবেন, সেখানে তোমরা তোমাদের গরু বা ছাগল-ভেড়ার পাল থেকে পশু নিয়ে তোমাদের মাবুদ আল্লাহ্‌র উদ্দেশে উদ্ধার-ঈদের কোরবানী দেবে।"},{"v":3,"ve":3,"vl":"3","bn":"সেই পশুর গোশ্‌ত তোমরা খামি দেওয়া রুটির সংগে খাবে না। সাত দিন ধরে তোমাদের দুঃখ স্মরণ করানো খামিহীন রুটি খেতে হবে, কারণ ভয়ে তাড়াহুড়া করে তোমরা মিসর দেশ ছেড়ে চলে এসেছিলে। এতে মিসর দেশ থেকে বেরিয়ে আসবার কথা তোমাদের সারা জীবন মনে থাকবে।"},{"v":4,"ve":4,"vl":"4","bn":"এই সাত দিন সারা দেশে তোমাদের মধ্যে যেন খামি দেওয়া কোন কিছু পাওয়া না যায়। ঈদের প্রথম দিনের সন্ধ্যাবেলায় তোমরা যে গোশ্‌ত কোরবানী দেবে তা যেন সকাল পর্যন্ত পড়ে না থাকে।"},{"v":5,"ve":5,"vl":"5","bn":"“তোমাদের মাবুদ আল্লাহ্‌র দেওয়া আর কোন শহরে তোমরা উদ্ধার-ঈদের পশু-কোরবানী দেবে না;"},{"v":6,"ve":6,"vl":"6","bn":"যে জায়গাটা তিনি নিজেকে প্রকাশ করবার জন্য তাঁর বাসস্থান হিসাবে বেছে নেবেন কেবল সেখানেই তা কোরবানী দেবে। যেদিন তোমরা মিসর দেশ থেকে বের হয়ে এসেছ প্রত্যেক বছরের সেই দিনে সূর্য ডুববার সময় সন্ধ্যাবেলায় উদ্ধার-ঈদের পশু-কোরবানী দেবে।"},{"v":7,"ve":7,"vl":"7","bn":"তোমাদের মাবুদ আল্লাহ্‌ যে জায়গাটা বেছে নেবেন সেখানেই তোমরা সেই গোশ্‌ত রান্না করে খাবে। তার পরের দিন সকালে তোমরা তোমাদের ঘরে ফিরে যাবে।"},{"v":8,"ve":8,"vl":"8","bn":"ছয় দিন ধরে তোমরা খামিহীন রুটি খাবে আর সাত দিনের দিন তোমরা তোমাদের মাবুদ আল্লাহ্‌র উদ্দেশে শেষ দিনের মিলন-মাহ্‌ফিলের আয়োজন করবে এবং সেই দিন কোন কাজ করবে না।"},{"heading":"সাত সপ্তাহের ঈদের পুনরালোচনা","v":9,"ve":9,"vl":"9","bn":"“মাঠের ফসল কাটা শুরু করা থেকে তোমরা গুণে সাতটা সপ্তা বাদ দেবে।"},{"v":10,"ve":10,"vl":"10","bn":"তারপর তোমাদের নিজের ইচ্ছায় করা কোরবানী দিয়ে তোমরা তোমাদের মাবুদ আল্লাহ্‌র উদ্দেশে সাত সপ্তাহের ঈদ পালন করবে। তোমাদের মাবুদ আল্লাহ্‌ তোমাদের যে পরিমাণে দোয়া করেছেন তা বুঝে তোমরা এই কোরবানীর জিনিস দেবে।"},{"v":11,"ve":11,"vl":"11","bn":"তোমাদের মাবুদ আল্লাহ্‌ নিজেকে প্রকাশ করবার জন্য তাঁর বাসস্থান হিসাবে যে জায়গাটা বেছে নেবেন সেখানে তাঁর সামনে তোমরা, তোমাদের ছেলেমেয়েরা, তোমাদের গোলাম ও বাঁদীরা এবং তোমাদের মধ্যে বাস করা লেবীয়রা, বিদেশী বাসিন্দারা, এতিম ছেলেমেয়েরা আর বিধবারা- তোমরা সবাই আনন্দ করবে।"},{"v":12,"ve":12,"vl":"12","bn":"মিসর দেশে তোমরাও যে গোলাম ছিলে সেই কথাটা মনে রেখে তোমরা এই সব নিয়ম যত্নের সংগে পালন করবে।"},{"heading":"কুঁড়ে-ঘরের ঈদের পুনরালোচনা","v":13,"ve":13,"vl":"13","bn":"“তোমাদের খামার এবং আংগুর মাড়াই করবার জায়গা থেকে সব কিছু তুলে রাখবার পরে সাত দিন তোমরা কুঁড়ে-ঘরের ঈদ পালন করবে।"},{"v":14,"ve":14,"vl":"14","bn":"তোমরা, তোমাদের ছেলেমেয়েরা, তোমাদের গোলাম ও বাঁদীরা এবং তোমাদের মধ্যে বাস করা লেবীয়রা, বিদেশী বাসিন্দারা, এতিম ছেলেমেয়েরা আর বিধবারা- তোমরা সবাই এই পর্বে আনন্দ করবে।"},{"v":15,"ve":15,"vl":"15","bn":"তোমাদের মাবুদ আল্লাহ্‌ যে জায়গা বেছে নেবেন সেখানেই তোমরা তাঁর উদ্দেশে সাত দিন ধরে এই ঈদ পালন করবে, কারণ তোমাদের তোলা সব ফসল এবং সব কাজে তোমাদের মাবুদ আল্লাহ্‌ তোমাদের দোয়া করবেন আর তোমাদের আনন্দ পূর্ণ হবে।"},{"v":16,"ve":16,"vl":"16","bn":"“তোমাদের মাবুদ আল্লাহ্‌র বেছে নেওয়া জায়গায় বছরে তিনবার, অর্থাৎ খামিহীন রুটির ঈদের সময়, সাত সপ্তাহের ঈদের সময় এবং কুঁড়ে-ঘরের ঈদের সময় তোমাদের সব পুরুষ লোকদের মাবুদের সামনে উপস্থিত হতে হবে। কেউ যেন খালি হাতে মাবুদের সামনে উপস্থিত না হয়।"},{"v":17,"ve":17,"vl":"17","bn":"তোমাদের মাবুদ আল্লাহ্‌ তোমাদের যে পরিমাণে দোয়া করেছেন তা বুঝে তোমাদের প্রত্যেকেই যেন কিছু না কিছু নিয়ে আসে।"},{"heading":"বিচারক নিয়োগ","v":18,"ve":18,"vl":"18","bn":"“তোমাদের মাবুদ আল্লাহ্‌ তোমাদের যে সব গ্রাম ও শহর দিতে যাচ্ছেন তার প্রত্যেকটিতে প্রত্যেক গোষ্ঠীর জন্য তোমরা বিচারক ও কর্মচারী নিযুক্ত করবে। তারা ন্যায়ভাবে লোকদের বিচার করবে।"},{"v":19,"ve":19,"vl":"19","bn":"তোমরা অন্যায় বিচার করবে না কিংবা কারও পক্ষ নেবে না। তোমরা ঘুষ নেবে না, কারণ ঘুষ জ্ঞানীদের চোখ অন্ধ করে দেয় এবং নির্দোষ লোকদের কথায় প্যাঁচ লাগিয়ে দেয়।"},{"v":20,"ve":20,"vl":"20","bn":"যে দেশটা তোমাদের মাবুদ আল্লাহ্‌ তোমাদের দিচ্ছেন, তোমরা যাতে বেঁচে থেকে তা ভোগ-দখল করতে পার সেইজন্য তোমরা কেবল ন্যায়কেই মেনে চলবে।"},{"heading":"দেব-দেবী পূজার বিরুদ্ধে নিয়ম","v":21,"ve":22,"vl":"21-22","bn":"“তোমাদের মাবুদ আল্লাহ্‌র উদ্দেশে তোমরা যে কোরবানগাহ্‌ তৈরী করবে তার পাশে পূজা করবার জন্য কাঠের আশেরা-খুঁটি পুঁতবে না কিংবা কোন পাথরও খাড়া করবে না, কারণ তোমাদের মাবুদ আল্লাহ্‌ এই সব ঘৃণা করেন।"}],"17":[{"v":1,"ve":1,"vl":"1","bn":"“তোমাদের মাবুদ আল্লাহ্‌র উদ্দেশে তোমরা এমন কোন গরু বা ছাগল বা ভেড়া কোরবানী দেবে না যার কোন খুঁত বা দোষ আছে, কারণ তিনি তা ঘৃণা করেন।"},{"v":2,"ve":2,"vl":"2","bn":"“তোমাদের মাবুদ আল্লাহ্‌র দেওয়া গ্রাম বা শহরগুলোর কোনটাতে হয়তো দেখা যাবে যে, তোমাদের মধ্যেকার কোন পুরুষ অথবা স্ত্রীলোক তোমাদের মাবুদ আল্লাহ্‌র দেওয়া ব্যবস্থা অমান্য করে তাঁর চোখে যা খারাপ তা করছে।"},{"v":3,"ve":3,"vl":"3","bn":"সে হয়তো আমার হুকুমের বিরুদ্ধে গিয়ে দেব-দেবীর সেবা করছে এবং সেই সব দেব-দেবী কিংবা সূর্য, চাঁদ বা আসমানের তারাগুলোর পূজা করছে।"},{"v":4,"ve":4,"vl":"4","bn":"যদি এই সব তোমাদের জানানো হয়, তবে তোমরা তা ভাল করে তদন্ত করে দেখবে। যদি তা সত্যি হয় এবং এই রকম ঘৃণার কাজ বনি-ইসরাইলদের মধ্যে করা হয়েছে বলে প্রমাণিত হয়,"},{"v":5,"ve":5,"vl":"5","bn":"তবে যে পুরুষ বা স্ত্রীলোক এই রকম জঘন্য কাজ করেছে তোমরা তাকে গ্রাম বা শহরের সদর দরজার কাছে নিয়ে পাথর ছুঁড়ে হত্যা করবে।"},{"v":6,"ve":6,"vl":"6","bn":"কোন মানুষকে হত্যা করতে হলে দুই বা তিনজন সাক্ষীর কথার উপর ভরসা করে তা করতে হবে; মাত্র একজন সাক্ষীর কথার উপর ভরসা করে তা করা চলবে না।"},{"v":7,"ve":7,"vl":"7","bn":"সেই লোকটিকে হত্যা করবার জন্য সাক্ষীরাই প্রথমে পাথর ছুঁড়বে, তারপর ছুঁড়বে অন্যান্য সব লোকেরা। এইভাবে তোমরা তোমাদের মধ্য থেকে সেই খারাপী শেষ করে দেবে।"},{"heading":"জটিল বিচার সম্বন্ধে নির্দেশ","v":8,"ve":8,"vl":"8","bn":"“যদি এমন সব মামলা তোমাদের আদালতে আসে যেগুলোর বিচার করা তোমাদের পক্ষে কঠিন হয়ে দাঁড়ায়- সেটা রক্তপাতের জন্যই হোক কিংবা ঝগড়া-বিবাদের জন্যই হোক কিংবা আঘাতের জন্যই হোক- তবে সেই মামলা নিয়ে মাবুদের বেছে নেওয়া জায়গায় তোমাদের যেতে হবে।"},{"v":9,"ve":9,"vl":"9","bn":"তোমরা তখন সেই সময়কার বিচারক এবং লেবীয়দের মধ্যে যারা ইমাম তাদের কাছে যাবে। তোমরা বিষয়টা তাদের বুঝিয়ে বলবে আর তারাই তোমাদের সেই বিচারের রায় দেবে।"},{"v":10,"ve":10,"vl":"10","bn":"মাবুদের বেছে নেওয়া জায়গাতে তারা তোমাদের কাছে যে রায় জানাবে তোমরা তা কাজে লাগাবে। তবে সাবধান, তারা তোমাদের যা যা করতে বলবে তার কোনটাই তোমরা বাদ দেবে না।"},{"v":11,"ve":11,"vl":"11","bn":"তারা শরীয়ত সম্বন্ধে তোমাদের যা শিক্ষা দেবে এবং যে রায় দেবে সেই মতই তোমরা কাজ করবে। তারা তোমাদের যা করতে বলবে তোমরা ঠিক তা-ই করবে, এদিক ওদিক করবে না।"},{"v":12,"ve":12,"vl":"12","bn":"যদি কোন লোক অহংকারের বশে সেই বিচারকের কথা কিংবা তোমাদের মাবুদ আল্লাহ্‌র খেদমতকারী সেই ইমামের কথা শুনতে রাজী না হয়, তবে তাকে অবশ্যই হত্যা করতে হবে। তোমরা বনি-ইসরাইলদের মধ্য থেকে এই রকমের খারাপী শেষ করে দেবে।"},{"v":13,"ve":13,"vl":"13","bn":"তাহলে সমস্ত লোক সেই কথা শুনে ভয় পাবে এবং এই রকম অহংকারের ভাব আর দেখাবে না।"},{"heading":"বাদশাহ্‌র জন্য কয়েকটি বিশেষ নিয়ম","v":14,"ve":14,"vl":"14","bn":"“তোমাদের মাবুদ আল্লাহ্‌ যে দেশটা তোমাদের দিতে যাচ্ছেন সেখানে গিয়ে তা দখল করে যখন তোমরা সেখানে বাস করতে থাকবে এবং বলবে, ‘আমাদের আশেপাশের জাতিগুলোর মত এস, আমরা আমাদের জন্য একজনকে বাদশাহ্‌ হিসাবে বেছে নিই,’"},{"v":15,"ve":15,"vl":"15","bn":"তখন তোমাদের মাবুদ আল্লাহ্‌ যাকে ঠিক করে দেবেন তাকেই তোমরা তোমাদের বাদশাহ্‌ করবে। সে যেন তোমাদের ইসরাইলীয় ভাইদের মধ্যে একজন হয়। যে তোমাদের ইসরাইলীয় ভাই নয় এমন ভিন্ন জাতির কোন লোককে তোমরা তোমাদের বাদশাহ্‌ করবে না।"},{"v":16,"ve":16,"vl":"16","bn":"সেই বাদশাহ্‌ যেন নিজের জন্য অনেক ঘোড়া জোগাড় করবার দিকে মন না দেয় এবং তার পরে আরও ঘোড়া জোগাড় করবার জন্য বনি-ইসরাইলদের মিসর দেশে না পাঠায়, কারণ মাবুদ তোমাদের বলেছেন, ‘তোমরা ঐ পথে আর ফিরে যাবে না।’"},{"v":17,"ve":17,"vl":"17","bn":"সে যেন অনেক বিয়ে না করে; তাতে তার মন বিপথে যাবে। সে যেন নিজের জন্য অতিরিক্ত সোনা ও রূপা জড়ো না করে।"},{"v":18,"ve":18,"vl":"18","bn":"“লেবীয়দের মধ্যে যারা ইমাম তাদের কাছে শরীয়তের যে কিতাব আছে সিংহাসনে বসবার সময় তাকে সেই কিতাব থেকে তার নিজের জন্য সব শরীয়ত একটি বইয়ে লিখে নিতে হবে।"},{"v":19,"ve":19,"vl":"19","bn":"সেটা তার কাছেই থাকবে এবং সারা জীবন তাকে তা পড়তে হবে যাতে সে তার মাবুদ আল্লাহ্‌কে ভয় করতে শেখে এবং এই শরীয়ত ও নিয়মের কথাগুলো মেনে চলে।"},{"v":20,"ve":20,"vl":"20","bn":"এর ফলে অন্যান্য ইসরাইলীয় ভাইদের চেয়ে নিজেকে বড় করে দেখবার ভাব তার মনে আসবে না এবং শরীয়ত থেকে সে এদিক ওদিক সরে যাবে না। এতে সে ও তার বংশধরেরা বনি-ইসরাইলদের উপর অনেক দিন রাজত্ব করতে পারবে।"}],"18":[{"heading":"ইমাম ও লেবীয়দের জন্য দান","v":1,"ve":1,"vl":"1","bn":"“লেবীয় ইমামেরা এবং লেবি-গোষ্ঠীর অন্যান্য লোকেরা বাকী বনি-ইসরাইলদের মত কোন জায়গা-জমি কিংবা সম্পত্তি পাবে না। মাবুদের উদ্দেশে আগুনে দেওয়া কোরবানীর জন্য যে সব জিনিস আনা হবে এবং মাবুদকে আর যা কিছু দেওয়া হবে তা-ই তারা খাবে।"},{"v":2,"ve":2,"vl":"2","bn":"ইসরাইলীয় ভাইদের মধ্যে তাদের সম্পত্তি বলে কিছু থাকবে না। মাবুদের ওয়াদা অনুসারে মাবুদই হবেন তাদের সম্পত্তি।"},{"v":3,"ve":3,"vl":"3","bn":"“লোকেরা যে সব গরু-ছাগল-ভেড়া কোরবানী দেবে সেগুলোর কাঁধ, চোয়ালের গোশ্‌ত এবং পাকস্থলী তারা ইমামকে দেবে; এগুলো হবে ইমামের পাওনা।"},{"v":4,"ve":4,"vl":"4","bn":"তোমাদের প্রথমে তোলা ফসল, নতুন আংগুর-রস ও তেল আর ছাগল-ভেড়ার গা থেকে প্রথমবার কেটে নেওয়া লোম তোমরা ইমামদের দেবে,"},{"v":5,"ve":5,"vl":"5","bn":"কারণ তোমাদের মাবুদ আল্লাহ্‌ তোমাদের সমস্ত গোষ্ঠীর মধ্য থেকে লেবীয়দের এবং তাদের বংশধরদের বেছে নিয়েছেন, যেন তারা সব সময় মাবুদের নামে এবাদত-কাজ করতে পারে।"},{"v":6,"ve":6,"vl":"6","bn":"“ইসরাইলীয়দের দেশের কোন লেবীয় যদি তার বাসস্থান ছেড়ে সত্যিকারের ইচ্ছা নিয়ে মাবুদের বেছে নেওয়া জায়গায় যায়,"},{"v":7,"ve":7,"vl":"7","bn":"তবে অন্যান্য লেবীয় ভাইদের মত সে-ও সেখানে তার মাবুদ আল্লাহ্‌র নামে এবাদত-কাজ করতে পারবে।"},{"v":8,"ve":8,"vl":"8","bn":"তার পিতার রেখে যাওয়া জিনিসপত্র বিক্রি করে টাকা পেলেও সেখানকার লেবীয়দের সংগে সে সমান ভাগের অধিকারী হবে।"},{"heading":"মাবুদের চোখে যে সব কাজ জঘন্য","v":9,"ve":9,"vl":"9","bn":"“তোমাদের মাবুদ আল্লাহ্‌ তোমাদের যে দেশ দিতে যাচ্ছেন সেখানে গিয়ে সেখানকার জাতিগুলো যে সব জঘন্য কাজ করে তোমরা তা করতে শিখবে না।"},{"v":10,"ve":10,"vl":"10","bn":"তোমাদের মধ্যে যেন এমন কোন লোক না থাকে যে তার নিজের সন্তানকে আগুনে পুড়িয়ে কোরবানী করে, যে গোণাপড়া করে কিংবা মায়াবিদ্যা খাটায় কিংবা লক্ষণ দেখে ভবিষ্যতের কথা বলে, যে জাদু করে,"},{"v":11,"ve":11,"vl":"11","bn":"যে মন্ত্রতন্ত্র খাটায়, যে ভূতের মাধ্যম হয়, যে ভূতের সংগে সম্বন্ধ রাখে এবং যে মৃত লোকের সংগে যোগাযোগ রাখে।"},{"v":12,"ve":12,"vl":"12","bn":"এই সব কাজ যে করে মাবুদ তাকে জঘন্য মনে করেন। এই সব জঘন্য কাজের জন্যই তোমাদের মাবুদ আল্লাহ্‌ ঐ সব জাতি তোমাদের সামনে থেকে তাড়িয়ে দেবেন।"},{"v":13,"ve":13,"vl":"13","bn":"তোমাদের মাবুদ আল্লাহ্‌র সামনে তোমাদের নির্দোষ থাকতে হবে।"},{"heading":"সেই নবী","v":14,"ve":14,"vl":"14","bn":"“তোমরা যে সব জাতিদের বেদখল করবে তারা মায়াবিদ্যা ব্যবহারকারী ও গণকদের কথায় কান দেয়, কিন্তু তোমাদের বেলায় এই সব ব্যাপারে তোমাদের মাবুদ আল্লাহ্‌র নিষেধ রয়েছে।"},{"v":15,"ve":15,"vl":"15","bn":"তোমাদের মাবুদ আল্লাহ্‌ তোমাদের মধ্য থেকে, তোমাদের ভাইদের মধ্য থেকেই তোমাদের জন্য আমার মত একজন নবী দাঁড় করাবেন। তাঁর কথামত তোমাদের চলতে হবে।"},{"v":16,"ve":16,"vl":"16","bn":"তুর পাহাড়ের কাছে যেদিন তোমরা সবাই মাবুদের সামনে জমায়েত হয়েছিলে সেই দিন তোমরা তোমাদের মাবুদ আল্লাহ্‌র কাছে তা-ই চেয়েছিলে। তোমরা বলেছিলে, ‘আর আমরা আমাদের মাবুদ আল্লাহ্‌র কথা শুনতে কিংবা এই মহান আগুন দেখতে চাই না; তা হলে আমরা মারা যাব।’"},{"v":17,"ve":17,"vl":"17","bn":"“মাবুদ আমাকে বলেছিলেন, ‘তারা ভালই বলেছে।"},{"v":18,"ve":18,"vl":"18","bn":"আমি তাদের ভাইদের মধ্য থেকে তাদের জন্য তোমার মত একজন নবী দাঁড় করাব। তার মুখ দিয়েই আমি আমার কথা বলব, আর আমি যা বলতে তাকে হুকুম দেব সে তা-ই তাদের বলবে।"},{"v":19,"ve":19,"vl":"19","bn":"সেই নবী আমার নাম করে যে কথা বলবে কেউ যদি আমার সেই কথা না শোনে, তবে আমি নিজেই সেই লোককে দায়ী করব।"},{"v":20,"ve":20,"vl":"20","bn":"কিন্তু আমি হুকুম দিই নি এমন কোন কথা যদি কোন নবী আমার নাম করে বলতে সাহস করে কিংবা সে যদি দেব-দেবীর নামে কথা বলে, তবে তাকে হত্যা করতে হবে।’"},{"v":21,"ve":21,"vl":"21","bn":"“কোন একটা কথা সম্বন্ধে তোমরা মনে মনে বলতে পার, ‘মাবুদ এই কথা বলেছেন কিনা তা আমরা কি করে জানব?’"},{"v":22,"ve":22,"vl":"22","bn":"কোন নবী যদি মাবুদের নাম করে কোন কথা বলে আর তা যদি অসত্য হয় কিংবা না ঘটে, তবে বুঝতে হবে সেই কথা মাবুদ বলেন নি। সেই নবী দুঃসাহস করে ঐ কথা বলেছে। তাকে তোমরা ভয় কোরো না।"}],"19":[{"heading":"খুনীদের জন্য আশ্রয়-শহর","v":1,"ve":1,"vl":"1","bn":"“তোমাদের মাবুদ আল্লাহ্‌ যে দেশ তোমাদের দখল করবার জন্য দেবেন সেখানকার জাতিদের যখন তিনি ধ্বংস করে ফেলবেন এবং তোমরা তাদের বদলে তাদের গ্রামে বা শহরে ও বাড়ী-ঘরে বাস করতে থাকবে,"},{"v":2,"ve":3,"vl":"2-3","bn":"তখন সম্পত্তি হিসাবে তোমাদের মাবুদ আল্লাহ্‌র দেওয়া গোটা দেশটা তোমরা তিন ভাগে ভাগ করে নেবে। তার মধ্য থেকে আশ্রয়-শহর হিসাবে তিনটা শহর তোমরা আলাদা করে নেবে এবং সেখানে যাবার পথও তৈরী করে নেবে। তাহলে কেউ যদি কারও হাতে মারা পড়ে তবে যে মেরেছে সে তার কাছের আশ্রয়-শহরে পালিয়ে যেতে পারবে।"},{"v":4,"ve":4,"vl":"4","bn":"“মনে কোন হিংসা না রেখে যদি কেউ হঠাৎ কাউকে হত্যা করে এবং নিজের প্রাণ বাঁচাবার জন্য তার কাছের আশ্রয়-শহরটিতে পালিয়ে যায় তবে তার সম্বন্ধে এই হল নিয়ম।"},{"v":5,"ve":5,"vl":"5","bn":"ধরে নাও, একজন লোক অন্য আর একজনের সংগে বনে কাঠ কাটতে গেল। সেখানে গাছ কাটতে গিয়ে কুড়াল দিয়ে কোপ দেবার সময়ে কুড়ালের ফলাটা ফস্‌কিয়ে গিয়ে অন্য লোকটিকে আঘাত করল এবং তাতে সে মারা গেল। এই অবস্থায় ঐ লোকটি তার কাছের আশ্রয়-শহরটিতে গিয়ে নিজের প্রাণ বাঁচাতে পারবে।"},{"v":6,"ve":6,"vl":"6","bn":"তা না হলে রক্তের শোধ যার নেবার কথা সে রাগের বশে তাকে তাড়া করতে পারে আর আশ্রয়-শহর কাছে না হলে তাকে হত্যা করতে পারে, যদিও মনে হিংসা নিয়ে হত্যা করে নি বলে মৃত্যু তার পাওনা শাস্তি নয়।"},{"v":7,"ve":7,"vl":"7","bn":"সেইজন্য আমি তোমাদের নিজেদের জন্য তিনটা শহর আলাদা করে রাখবার হুকুম দিচ্ছি।"},{"v":8,"ve":9,"vl":"8-9","bn":"“তোমাদের মাবুদ আল্লাহ্‌কে মহব্বত করবার এবং সব সময় তাঁর পথে চলবার এই যে সব হুকুম আমি আজ তোমাদের দিচ্ছি তা যদি তোমরা যত্নের সংগে পালন কর তবে তোমাদের পূর্বপুরুষদের কাছে কসম খাওয়া ওয়াদা অনুসারে তোমাদের মাবুদ আল্লাহ্‌ তোমাদের দেশের সীমানা বাড়িয়ে দেবেন এবং গোটা দেশটা তোমাদের দেবেন। তখন তোমরা নিজেদের জন্য আশ্রয়-শহর হিসাবে আরও তিনটা শহর আলাদা করে রাখবে।"},{"v":10,"ve":10,"vl":"10","bn":"তোমরা এটা করবে যাতে সম্পত্তি হিসাবে যে দেশটা তোমাদের মাবুদ আল্লাহ্‌ তোমাদের দিতে যাচ্ছেন সেই দেশের উপর নির্দোষ লোকের রক্তপাত না হয় এবং রক্তপাতের দোষে তোমরা দোষী না হও।"},{"v":11,"ve":11,"vl":"11","bn":"“কিন্তু যদি কেউ হিংসা করে কাউকে হত্যা করবার জন্য ওৎ পেতে বসে থাকে এবং তাকে হামলা করে হত্যা করে আর তার পরে তার কাছের আশ্রয়-শহরটিতে পালিয়ে যায়,"},{"v":12,"ve":12,"vl":"12","bn":"তবে তার শহরের বৃদ্ধ নেতারা লোক পাঠিয়ে সেই শহর থেকে তাকে ধরে আনবে এবং রক্তের শোধ যার নেবার কথা তার হাতে তাকে হত্যা করবার জন্য তুলে দেবে।"},{"v":13,"ve":13,"vl":"13","bn":"তাকে তোমরা কোন দয়া দেখাবে না। তোমরা বনি-ইসরাইলদের মধ্য থেকে নির্দোষ লোকের রক্তপাতের দোষ মুছে ফেলবে। তাতে তোমাদের জন্য ভাল হবে।"},{"v":14,"ve":14,"vl":"14","bn":"“তোমাদের মাবুদ আল্লাহ্‌ যে দেশটা দখল করবার জন্য তোমাদের দিচ্ছেন সেখানে তোমাদের পূর্বপুরুষদের রাখা কোন সীমানা-চিহ্ন তোমরা সরাবে না।"},{"heading":"সাক্ষী সম্বন্ধে নিয়ম","v":15,"ve":15,"vl":"15","bn":"“যদি কারও বিরুদ্ধে দোষ বা অন্যায় করবার নালিশ আনা হয়, তবে মাত্র একজন সাক্ষী দাঁড়ালে চলবে না; দুই বা তিনজন সাক্ষীর কথা ছাড়া কোন বিষয় সত্যি বলে প্রমাণিত হতে পারবে না।"},{"v":16,"ve":16,"vl":"16","bn":"“যদি কেউ ক্ষতি করবার মনোভাব নিয়ে কারও বিরুদ্ধে কোন অন্যায় কাজের নালিশ আনে,"},{"v":17,"ve":17,"vl":"17","bn":"তবে সেই ব্যাপারে জড়িত সেই দু’জনকে তখনকার ইমাম ও বিচারকদের কাছে গিয়ে মাবুদের সামনে দাঁড়াতে হবে।"},{"v":18,"ve":18,"vl":"18","bn":"বিচারকেরা ব্যাপারটা ভাল করে তদন্ত করে দেখবে। যদি সে তার ইসরাইলীয় ভাইয়ের বিরুদ্ধে মিথ্যা সাক্ষ্য দেবার দরুন মিথ্যাবাদী বলে ধরা পড়ে,"},{"v":19,"ve":19,"vl":"19","bn":"তবে সে তার ভাইয়ের প্রতি যা করতে চেয়েছিল তা-ই তার প্রতি করতে হবে। তোমাদের মধ্য থেকে এই রকমের খারাপী শেষ করে দিতে হবে।"},{"v":20,"ve":20,"vl":"20","bn":"এই কথা শুনে অন্য সব বনি-ইসরাইলরা ভয় পাবে এবং এই রকম অন্যায় আর কখনও তারা করবে না।"},{"v":21,"ve":21,"vl":"21","bn":"তোমরা তার প্রতি কোন দয়া দেখাবে না- প্রাণের বদলে প্রাণ, চোখের বদলে চোখ, দাঁতের বদলে দাঁত, হাতের বদলে হাত এবং পায়ের বদলে পা নেবে।"}],"20":[{"heading":"যুদ্ধযাত্রা","v":1,"ve":1,"vl":"1","bn":"“যুদ্ধ করতে গিয়ে শত্রুর পক্ষে তোমাদের চেয়ে বেশী ঘোড়া, রথ ও সৈন্যদল দেখে তোমরা ভয় পেয়ো না, কারণ তোমাদের মাবুদ আল্লাহ্‌, যিনি মিসর দেশ থেকে তোমাদের বের করে এনেছেন তিনি তোমাদের সংগে থাকবেন।"},{"v":2,"ve":3,"vl":"2-3","bn":"তোমরা যুদ্ধে বেরিয়ে যাওয়ার আগে ইমাম এগিয়ে এসে সৈন্যদলকে বলবে, ‘বনি-ইসরাইলরা শোন, আজকে তোমরা তোমাদের শত্রুদের সংগে যুদ্ধ করতে যাচ্ছ। তোমরা সাহস হারায়ো না; তোমরা ভয় কোরো না কিংবা ভয়ে ভেংগে পোড়ো না; শত্রু দেখে যেন তোমাদের কাঁপুনি না ধরে।"},{"v":4,"ve":4,"vl":"4","bn":"শত্রুদের সংগে যুদ্ধ করে তোমাদের জয়ী করবার জন্য তোমাদের মাবুদ আল্লাহ্‌ই তোমাদের সংগে যাচ্ছেন।’"},{"v":5,"ve":5,"vl":"5","bn":"“তারপর তাদের নেতারা সৈন্যদের বলবে, ‘তোমাদের মধ্যে যদি কেউ নতুন ঘর তৈরী করে তা প্রতিষ্ঠা না করে থাকে তবে সে বাড়ী যাক; তা না হলে সে যুদ্ধে মারা গেলে অন্য কেউ সেই ঘর প্রতিষ্ঠা করবে।"},{"v":6,"ve":6,"vl":"6","bn":"কেউ যদি আংগুর ক্ষেত করে তার ফল না খেয়ে থাকে তবে সে-ও বাড়ী যাক; তা না হলে সে যুদ্ধে মারা গেলে অন্যে সেই ক্ষেত ভোগ করবে।"},{"v":7,"ve":7,"vl":"7","bn":"বিয়ের সম্বন্ধের পরে যদি কেউ বিয়ে না করে থাকে তবে সে-ও বাড়ী যাক; তা না হলে সে যুদ্ধে মারা গেলে অন্যে সেই স্ত্রীলোককে বিয়ে করবে।’"},{"v":8,"ve":8,"vl":"8","bn":"সেই নেতারা আরও বলবে, ‘তোমাদের মধ্যে যদি কেউ ভয় পেয়ে থাকে কিংবা সাহস হারিয়ে থাকে, তবে তা দেখে যাতে অন্য ইসরাইলীয় ভাইদের মনোবল নষ্ট হয়ে না যায় সেইজন্য সে বাড়ী ফিরে যাক।’"},{"v":9,"ve":9,"vl":"9","bn":"সৈন্যদের কাছে কথা বলা শেষ করে নেতারা সৈন্যদের বিভিন্ন দলের উপরে তাদের সেনাপতি নিযুক্ত করবে।"},{"v":10,"ve":10,"vl":"10","bn":"“তোমরা কোন গ্রাম বা শহর আক্রমণ করতে যাওয়ার আগে সেখানকার লোকদের কাছে বিনা যুদ্ধে অধীনতা মেনে নেবার প্রস্তাব করবে।"},{"v":11,"ve":11,"vl":"11","bn":"যদি তাতে তারা রাজী হয়ে তাদের দরজা খুলে দেয় তবে সেখানকার সমস্ত লোকেরা তোমাদের অধীন হবে এবং তোমাদের জন্য কাজ করতে বাধ্য থাকবে।"},{"v":12,"ve":12,"vl":"12","bn":"কিন্তু তারা যদি সেই প্রস্তাবে রাজী না হয়ে তোমাদের বিরুদ্ধে যুদ্ধে নামে তবে সেই জায়গা তোমরা আক্রমণ করবে।"},{"v":13,"ve":13,"vl":"13","bn":"তোমাদের মাবুদ আল্লাহ্‌ যখন সেই জায়গাটা তোমাদের হাতে তুলে দেবেন তখন সেখানকার সব পুরুষ লোকদের তোমরা হত্যা করবে।"},{"v":14,"ve":14,"vl":"14","bn":"তবে স্ত্রীলোক, ছেলেমেয়ে, পশুপাল এবং সেই জায়গার অন্য সব কিছু তোমরা লুটের জিনিস হিসাবে নিজেদের জন্য নিতে পারবে। শত্রুদের দেশ থেকে লুট করা যে সব জিনিস তোমাদের মাবুদ আল্লাহ্‌ তোমাদের দেবেন তা তোমরা ভোগ করতে পারবে।"},{"v":15,"ve":15,"vl":"15","bn":"যে সব শহর তোমাদের দেশ থেকে দূরে আছে, যেগুলো তোমাদের কাছের জাতিগুলোর শহর নয়, সেগুলোর প্রতি তোমরা এই রকম করবে।"},{"v":16,"ve":16,"vl":"16","bn":"কিন্তু তোমাদের মাবুদ আল্লাহ্‌ সম্পত্তি হিসাবে যে সব জাতিদের গ্রাম ও শহর তোমাদের দিতে যাচ্ছেন সেখানকার কাউকেই তোমরা বাঁচিয়ে রাখবে না।"},{"v":17,"ve":17,"vl":"17","bn":"তোমাদের মাবুদ আল্লাহ্‌র হুকুম অনুসারে তোমরা হিট্টীয়, আমোরীয়, কেনানীয়, পরিষীয়, হিব্বীয় এবং যিবূষীয়দের সম্পূর্ণভাবে ধ্বংস করে ফেলবে।"},{"v":18,"ve":18,"vl":"18","bn":"তা না করলে তারা তাদের দেব-দেবীর পূজা করবার সময়ে যে সব জঘন্য কাজ করে তা তোমরাও শিখবে আর তাতে তোমরা তোমাদের মাবুদ আল্লাহ্‌র বিরুদ্ধে গুনাহ্‌ করবে।"},{"v":19,"ve":19,"vl":"19","bn":"“তোমরা অনেক দিন ধরে যখন কোন গ্রাম বা শহর ঘেরাও করে রেখে তা দখল করবার জন্য যুদ্ধ করতে থাকবে তখন কুড়াল দিয়ে সেখানকার কোন গাছ নষ্ট করবে না, কারণ সেগুলোর ফল তোমরা খেতে পারবে। সেগুলো তোমরা কেটে ফেলবে না। মাঠের সেই গাছগুলো তো আর মানুষ নয় যে, সেগুলোর উপর তোমাদের হামলা করতে হবে।"},{"v":20,"ve":20,"vl":"20","bn":"তবে যেগুলো ফলের গাছ নয় বলে তোমাদের জানা থাকবে সেগুলো তোমরা কেটে ফেলতে পারবে এবং যে জায়গার লোকেরা তোমাদের সংগে যুদ্ধ করছে তারা হেরে না যাওয়া পর্যন্ত সেই গাছগুলো তোমরা হামলা করবার কাজে ব্যবহার করতে পারবে।"}],"21":[{"heading":"অজানা খুনের ব্যাপারে যা করতে হবে","v":1,"ve":1,"vl":"1","bn":"“তোমাদের মাবুদ আল্লাহ্‌ যে দেশ দখল করবার জন্য তোমাদের দিতে যাচ্ছেন সেখানকার কোন মাঠে হয়তো কাউকে খুন হয়ে পড়ে থাকতে দেখা যেতে পারে, কিন্তু কে তাকে খুন করেছে তা জানা নেই।"},{"v":2,"ve":2,"vl":"2","bn":"এই অবস্থায় তোমাদের বৃদ্ধ নেতারা ও বিচারকেরা বাইরে গিয়ে সেই লাশ থেকে কাছের গ্রাম বা শহরগুলো কত দূরে তা মেপে দেখবে।"},{"v":3,"ve":3,"vl":"3","bn":"লাশ থেকে যে জায়গাটা সবচেয়ে কাছে পড়বে সেখানকার বৃদ্ধ নেতাদের এমন একটা বক্‌না বাছুর নিতে হবে যাকে কখনও কাজে লাগানো হয় নি এবং যার কাঁধে কখনও জোয়াল দেওয়া হয় নি।"},{"v":4,"ve":4,"vl":"4","bn":"যেখানে কখনও চাষ করা কিংবা বীজ বোনা হয় নি এবং যেখানে একটা নদী বয়ে যাচ্ছে, বক্‌না বাছুরটাকে তেমন একটা উপত্যকায় তাদের নিয়ে যেতে হবে। সেই উপত্যকায় তারা বক্‌না বাছুরটার ঘাড় ভেংগে দেবে।"},{"v":5,"ve":5,"vl":"5","bn":"তারপর ইমামেরা, অর্থাৎ লেবি-গোষ্ঠীর লোকেরা সামনে এগিয়ে যাবে, কারণ এবাদত-কাজ করবার জন্য, মাবুদের নামে দোয়া উচ্চারণ করবার জন্য এবং ঝগড়া-বিবাদ ও মারধরের বিচার করবার জন্য তোমাদের মাবুদ আল্লাহ্‌ তাদেরই বেছে নিয়েছেন।"},{"v":6,"ve":6,"vl":"6","bn":"তারপর সবচেয়ে কাছের গ্রাম বা শহরের বৃদ্ধ নেতারা সেই ঘাড় ভাংগা বাছুরটার উপর তাদের হাত ধুয়ে ফেলবে।"},{"v":7,"ve":7,"vl":"7","bn":"এর পর তারা বলবে, ‘এই রক্তপাত আমরা নিজেরা করি নি এবং হতেও দেখি নি।"},{"v":8,"ve":8,"vl":"8","bn":"হে মাবুদ, তোমার মুক্ত করা বনি-ইসরাইলদের তুমি মাফ কর। এই লোকটির রক্তপাতের জন্য তুমি তোমার বান্দাদের দায়ী কোরো না।’ এতে সেই রক্তপাতের দোষ মাফ করা হবে।"},{"v":9,"ve":9,"vl":"9","bn":"এইভাবে তোমরা নিজেদের মধ্য থেকে নির্দোষ লোকের রক্তপাতের দোষ মুছে ফেলতে পারবে, কারণ তখন মাবুদের চোখে যা ভাল তা-ই করা হবে।"},{"heading":"বন্দী স্ত্রীলোককে বিয়ে করা","v":10,"ve":10,"vl":"10","bn":"“শত্রুদের সংগে যুদ্ধ করতে গিয়ে যখন তোমাদের মাবুদ আল্লাহ্‌ তোমাদের হাতে তাদের তুলে দেবেন আর তোমরা তাদের বন্দী করবে,"},{"v":11,"ve":11,"vl":"11","bn":"তখন যদি তাদের মধ্যেকার কোন সুন্দরী স্ত্রীলোককে দেখে তোমাদের কারও তাকে ভাল লাগে তবে সে তাকে স্ত্রী হিসাবে গ্রহণ করতে পারবে।"},{"v":12,"ve":12,"vl":"12","bn":"স্ত্রীলোকটিকে সে তার বাড়ীতে নিয়ে যাবে। তারপর স্ত্রীলোকটি তার চুল কামিয়ে ফেলবে ও নখ কেটে ফেলবে,"},{"v":13,"ve":13,"vl":"13","bn":"আর বন্দী হবার সময়ে তার গায়ে যে সব কাপড়-চোপড় ছিল তা খুলে ফেলবে। এর পর তার বাড়ীতে থেকে সেই স্ত্রীলোকটি পুরো এক মাস তার মা-বাবার জন্য শোক করবে। তারপর সেই লোকটি তাকে বিয়ে করে তার স্বামী হবে এবং স্ত্রীলোকটিও তার স্ত্রী হবে।"},{"v":14,"ve":14,"vl":"14","bn":"পরে যদি স্ত্রীলোকটির উপর সে অখুশী হয় তবে তাকে যেখানে ইচ্ছা চলে যেতে দিতে হবে। সে তাকে বিক্রি করতে পারবে না কিংবা বাঁদী হিসাবে রাখতে পারবে না, কারণ সে তার অসম্মান করেছে।"},{"heading":"প্রথম ছেলের পাওনা অধিকার","v":15,"ve":15,"vl":"15","bn":"“এমন হতে পারে যে, একজন লোকের দু’জন স্ত্রী আছে, আর তাদের একজনকেই সে ভালবাসে অন্যজনকে নয়। তাদের দু’জনেরই যদি ছেলে হয় আর প্রথম ছেলের জন্ম হয় সেই স্ত্রীর গর্ভে যাকে সে ভালবাসে না,"},{"v":16,"ve":16,"vl":"16","bn":"তবে সম্পত্তি উইল করে দেবার সময়ে যে স্ত্রীকে সে ভালবাসে না তার ছেলেকে বাদ দিয়ে অন্য স্ত্রীর ছেলেটিকে প্রথম ছেলের পাওনা অধিকার দেওয়া চলবে না, কারণ যে স্ত্রীকে সে ভালবাসে না তার ছেলেটিই আসলে তার প্রথম ছেলে।"},{"v":17,"ve":17,"vl":"17","bn":"যে স্ত্রীকে সে ভালবাসে না তার ছেলেকে তার সম্পত্তি থেকে অন্য যে কোন ছেলের চেয়ে দ্বিগুণ ভাগ দিয়ে সেই ছেলেই যে প্রথম ছেলে তা তাকে স্বীকার করতে হবে। সেই ছেলেই তার বাবার পুরুষ-শক্তির প্রথম ফল। প্রথম ছেলের অধিকার তারই পাওনা।"},{"heading":"বিদ্রোহী ছেলে","v":18,"ve":18,"vl":"18","bn":"“যদি কারও ছেলে একগুঁয়ে এবং বিদ্রোহী হয়, যদি সে কিছুতেই মা-বাবার কথা না শোনে এবং তাদের শাসন না মানে,"},{"v":19,"ve":19,"vl":"19","bn":"তবে তার মা-বাবা তাকে তাদের গ্রাম বা শহরের সদর দরজায় বৃদ্ধ নেতাদের কাছে নিয়ে যাবে।"},{"v":20,"ve":20,"vl":"20","bn":"তারা সেই বৃদ্ধ নেতাদের বলবে, ‘আমাদের এই ছেলে ভীষণ একগুঁয়ে এবং বিদ্রোহী; সে আমাদের অগ্রাহ্য করে চলে। সে মাতাল এবং টাকা-পয়সা উড়িয়ে দেয়।’"},{"v":21,"ve":21,"vl":"21","bn":"তখন সেই জায়গার সমস্ত পুরুষেরা তাকে পাথর ছুঁড়ে হত্যা করবে। এইভাবে তোমাদের মধ্য থেকে সেই খারাপী শেষ করে দিতে হবে। তাতে বনি-ইসরাইলরা সবাই এই কথা শুনে ভয় পাবে।"},{"heading":"অন্যান্য নিয়ম","v":22,"ve":22,"vl":"22","bn":"“যদি কোন লোক মৃত্যুর শাস্তি পাবার মত কোন দোষ করে এবং তাকে হত্যা করে গাছে টাংগিয়ে রাখা হয়,"},{"v":23,"ve":23,"vl":"23","bn":"তবে সকাল পর্যন্ত তার লাশ গাছে টাংগিয়ে রাখা চলবে না। সেই দিনই তাকে দাফন করে ফেলতে হবে, কারণ গাছে টাংগিয়ে রাখা লোক আল্লাহ্‌র বদদোয়াপ্রাপ্ত। সম্পত্তি হিসাবে যে দেশটা তোমাদের মাবুদ আল্লাহ্‌ তোমাদের দিতে যাচ্ছেন তা তোমরা নাপাক করবে না।"}],"22":[{"v":1,"ve":1,"vl":"1","bn":"“তোমাদের ইসরাইলীয় ভাইয়ের কোন গরু বা ভেড়াকে পথ হারিয়ে অন্য কোথাও চলে যেতে দেখলে তোমরা চুপ করে বসে থাকবে না। তোমরা অবশ্যই সেটা তার কাছে ফিরিয়ে নিয়ে যাবে।"},{"v":2,"ve":2,"vl":"2","bn":"যদি সেই ভাই তোমাদের বাড়ীর পাশের কেউ না হয় কিংবা ভাইটি কে তা যদি জানা না থাকে, তাহলে সেটা তোমরা নিয়ে যাবে এবং সেই ভাই সেটার খোঁজে না আসা পর্যন্ত নিজের বাড়ীতে রেখে দেবে। সে আসলে পর সেটা তাকে ফিরিয়ে দেবে।"},{"v":3,"ve":3,"vl":"3","bn":"তোমাদের ভাইয়ের গাধা কিংবা গায়ের কাপড় কিংবা তার হারিয়ে যাওয়া অন্য কিছু চোখে পড়লেও তোমরা ঐ রকম করবে, চুপ করে বসে থাকবে না।"},{"v":4,"ve":4,"vl":"4","bn":"“তোমাদের ভাইয়ের গাধা কিংবা গরু রাস্তায় পড়ে গেছে দেখতে পেলে চুপ করে বসে থাকবে না। সেটা যাতে উঠে দাঁড়ায় সেইজন্য অবশ্যই তুমি তাকে সাহায্য করবে।"},{"v":5,"ve":5,"vl":"5","bn":"“কোন স্ত্রীলোক যেন পুরুষের সাজে না সাজে কিংবা কোন পুরুষ যেন স্ত্রীলোকের পোশাক না পরে। যে তা করে তোমাদের মাবুদ আল্লাহ্‌ তাকে ঘৃণা করেন।"},{"v":6,"ve":6,"vl":"6","bn":"“তোমরা চলতে চলতে পথের পাশে কোন গাছে কিংবা মাটির উপরে যদি এমন কোন পাখীর বাসা দেখতে পাও যেখানে পাখীর মা বাচ্চাদের উপর বসে আছে কিংবা ডিমের উপর তা দিচ্ছে, তবে বাচ্চাসুদ্ধ মাকে তোমরা ধরে নিয়ে যাবে না।"},{"v":7,"ve":7,"vl":"7","bn":"তোমরা বাচ্চাগুলো নিতে পার কিন্তু মাকে অবশ্যই তোমাদের ছেড়ে দিতে হবে। এতে তোমাদের উন্নতি হবে আর তোমরা অনেক দিন বেঁচে থাকবে।"},{"v":8,"ve":8,"vl":"8","bn":"“বাড়ী তৈরী করবার সময় তোমরা সেটার ছাদের চারপাশটা দেয়ালের মত করে কিছুটা উঁচু করে দেবে, যাতে কেউ ছাদের উপর থেকে পড়ে মারা গেলে বাড়ীর লোকেরা তার মৃত্যুর জন্য দায়ী না হয়।"},{"v":9,"ve":9,"vl":"9","bn":"“আংগুর ক্ষেতে তোমরা দুই জাতের বীজ লাগাবে না; তা করলে সেই বীজের ফসল এবং ক্ষেতের আংগুর দুই-ই তোমাদের জন্য হারাম হয়ে যাবে।"},{"v":10,"ve":10,"vl":"10","bn":"“তোমরা বলদ আর গাধা একসংগে জুড়ে চাষ করবে না।"},{"v":11,"ve":11,"vl":"11","bn":"“তোমরা পশম আর মসীনা সুতা মিশিয়ে বোনা কাপড় পরবে না।"},{"v":12,"ve":12,"vl":"12","bn":"“তোমাদের গায়ের চাদরের চার কোণায় থোপ্‌না লাগাবে।"},{"heading":"সহবাস সম্বন্ধে নিয়ম","v":13,"ve":14,"vl":"13-14","bn":"“কোন লোক যদি বিয়ে করে স্ত্রীকে নিয়ে শোবার পরে তাকে অপছন্দ করে এবং তার নিন্দা ও বদনাম করে বলে, ‘আমি এই স্ত্রীলোককে বিয়ে করেছিলাম বটে, কিন্তু সে যে সতী মেয়ে তার মধ্যে সেই প্রমাণ আমি পেলাম না,’"},{"v":15,"ve":16,"vl":"15-16","bn":"তবে সেই মেয়ের মা-বাবা গ্রাম বা শহরের সদর দরজায় বৃদ্ধ নেতাদের কাছে তার সতীত্বের প্রমাণ নিয়ে যাবে এবং তার পিতা বলবে, ‘আমি এই লোকের সংগে আমার মেয়ের বিয়ে দিয়েছিলাম কিন্তু সে তাকে অপছন্দ করে,"},{"v":17,"ve":17,"vl":"17","bn":"আর এখন সে তার নিন্দা করে বলছে যে, সে তাকে সতী অবস্থায় পায় নি। কিন্তু এই দেখুন, আমার মেয়ের সতীত্বের প্রমাণ।’ এই বলে তারা বৃদ্ধ নেতাদের সামনে তার ব্যবহার করা কাপড় মেলে ধরবে।"},{"v":18,"ve":18,"vl":"18","bn":"তখন বৃদ্ধ নেতারা তার স্বামীকে শাস্তি দেবে।"},{"v":19,"ve":19,"vl":"19","bn":"তার কাছ থেকে তারা জরিমানা হিসাবে এক কেজি রূপা আদায় করে মেয়েটির বাবাকে দেবে, কারণ সে একজন ইসরাইলীয় সতী মেয়ের নামে বদনাম করেছে। এছাড়া মেয়েটি তার স্ত্রী-ই থাকবে এবং তার স্বামী জীবনে কখনও তাকে ছেড়ে দিতে পারবে না।"},{"v":20,"ve":20,"vl":"20","bn":"“কিন্তু কথাটা যদি সত্যি হয় এবং মেয়েটির সতীত্বের কোন প্রমাণ পাওয়া না যায়,"},{"v":21,"ve":21,"vl":"21","bn":"তবে মেয়েটিকে তার বাবার বাড়ীর দরজার কাছে নিয়ে যেতে হবে। সেই জায়গার পুরুষ লোকেরা সেখানে পাথর ছুঁড়ে তাকে হত্যা করবে। বাবার বাড়ীতে থাকবার সময়ে জেনা করে সে বনি-ইসরাইলদের মধ্যে ভীষণ ঘৃণার কাজ করেছে। তোমরা তোমাদের মধ্য থেকে এই রকম খারাপী শেষ করে দেবে।"},{"v":22,"ve":22,"vl":"22","bn":"“কোন লোককে যদি অন্য কারও স্ত্রীর সংগে সহবাস করতে দেখা যায় তবে যে তার সংগে সহবাস করেছে সেই পুরুষ ও সেই স্ত্রীলোক দু’জনকেই হত্যা করতে হবে। তোমরা বনি-ইসরাইলদের মধ্য থেকে এই রকম খারাপী শেষ করে দেবে।"},{"v":23,"ve":23,"vl":"23","bn":"“বিয়ে ঠিক হয়ে আছে এমন কোন মেয়েকে গ্রাম বা শহরের মধ্যে পেয়ে যদি কেউ তার সংগে সহবাস করে,"},{"v":24,"ve":24,"vl":"24","bn":"তবে তাদের দু’জনকেই সেখানকার সদর দরজার কাছে নিয়ে গিয়ে পাথর ছুঁড়ে হত্যা করতে হবে। মেয়েটিকে হত্যা করতে হবে কারণ গ্রাম বা শহরের মধ্যে থেকেও সে সাহায্যের জন্য চিৎকার করে নি, আর পুরুষটিকে হত্যা করতে হবে কারণ সে অন্যের স্ত্রীকে নষ্ট করেছে। তোমাদের মধ্য থেকে এই রকম খারাপী তোমরা শেষ করে দেবে।"},{"v":25,"ve":25,"vl":"25","bn":"“বিয়ে ঠিক হয়ে আছে এমন কোন মেয়েকে নির্জন খোলা মাঠে পেয়ে যদি কেউ জোর করে তার সংগে সহবাস করে তবে যে লোকটি তা করবে কেবল তাকেই হত্যা করতে হবে।"},{"v":26,"ve":26,"vl":"26","bn":"মেয়েটির প্রতি তোমরা কিছু করবে না; মৃত্যুর শাস্তি পাবার মত কোন গুনাহ্‌ সে করে নি। এটা একজন আর একজনকে ধরে হত্যা করবার মতই,"},{"v":27,"ve":27,"vl":"27","bn":"কারণ লোকটি মেয়েটিকে খোলা মাঠে পেয়েছিল আর বিয়ের কথা দেওয়া মেয়েটি যদিও চিৎকার করেছিল তবুও তাকে রক্ষা করবার মত কেউ সেখানে ছিল না।"},{"v":28,"ve":28,"vl":"28","bn":"“বিয়ে ঠিক হয় নি এমন কোন সতী মেয়েকে পেয়ে যদি কেউ জোর করে তার সংগে সহবাস করে আর যদি তারা ধরা পড়ে,"},{"v":29,"ve":29,"vl":"29","bn":"তবে লোকটিকে মেয়ের বাবাকে আধা কেজি রূপা দিতে হবে। মেয়েটিকে নষ্ট করেছে বলে তাকে তার বিয়ে করতে হবে। সে জীবনে কখনও তাকে ছেড়ে দিতে পারবে না।"},{"v":30,"ve":30,"vl":"30","bn":"“সৎমাকে কারও বিয়ে করা চলবে না; তাতে সে বাবার স্ত্রীর সংগে জেনা করে বাবাকে অসম্মান করবে।"}],"23":[{"heading":"ইসরাইল সমাজে যোগ দেবার নিয়ম","v":1,"ve":1,"vl":"1","bn":"“যার অণ্ডকোষ থেঁৎলে দেওয়া কিংবা পুরুষাংগ কেটে ফেলা হয়েছে সে মাবুদের বান্দাদের সমাজে যোগ দিতে পারবে না।"},{"v":2,"ve":2,"vl":"2","bn":"“কোন জারজ লোক মাবুদের বান্দাদের সমাজে যোগ দিতে পারবে না; তার চৌদ্দ পুরুষেও কেউ তা করতে পারবে না।"},{"v":3,"ve":3,"vl":"3","bn":"“কোন অম্মোনীয় কিংবা মোয়াবীয় মাবুদের বান্দাদের সমাজে যোগ দিতে পারবে না; তার চৌদ্দ পুরুষেও কেউ তা কখনও করতে পারবে না।"},{"v":4,"ve":4,"vl":"4","bn":"মিসর দেশ থেকে বের হয়ে আসবার পরে তোমাদের যাত্রার পথে তারা খাবার ও পানি নিয়ে তোমাদের কাছে এগিয়ে আসে নি, বরং তোমাদের বদদোয়া দেবার জন্য তারা ইরাম-নহরয়িম দেশের পথোর শহর থেকে বাউরের ছেলে বালামকে টাকা দিয়ে নিয়ে এসেছিল।"},{"v":5,"ve":5,"vl":"5","bn":"কিন্তু তোমাদের মাবুদ আল্লাহ্‌ বালামের কথায় সায় দেন নি; তোমাদের মহব্বত করেন বলে তিনি বরং এমন করলেন যাতে সেই বদদোয়া তোমাদের দোয়া হয়ে ওঠে।"},{"v":6,"ve":6,"vl":"6","bn":"তোমরা যতদিন বাঁচবে ততদিন এদের কোন উপকার বা উন্নতির চেষ্টা করবে না।"},{"v":7,"ve":7,"vl":"7","bn":"“কিন্তু ইদোমীয়দের তোমরা ঘৃণা করবে না, কারণ তারা তোমাদের ভাই। মিসরীয়দেরও ঘৃণা করবে না, কারণ তাদের দেশে তোমরা বিদেশী হিসাবে বাস করতে।"},{"v":8,"ve":8,"vl":"8","bn":"তোমাদের মধ্যে বাস করবার পরে তৃতীয় পুরুষ থেকে এরা মাবুদের বান্দাদের সমাজে যোগ দিতে পারবে।"},{"heading":"সৈন্য-ছাউনির পবিত্রতা রক্ষার নিয়ম","v":9,"ve":9,"vl":"9","bn":"“শত্রুদের বিরুদ্ধে যুদ্ধ করতে গিয়ে ছাউনি ফেলবার পরে সমস্ত রকম নাপাকী থেকে তোমরা দূরে থাকবে।"},{"v":10,"ve":10,"vl":"10","bn":"রাতে বীর্যপাতের দরুন যদি তোমাদের কেউ নাপাক হয়, তবে তাকে ছাউনির বাইরে গিয়ে থাকতে হবে।"},{"v":11,"ve":11,"vl":"11","bn":"বিকাল হয়ে আসলে তাকে গোসল করে ফেলতে হবে। সূর্য ডুবে গেলে পর সে ছাউনিতে ফিরে যেতে পারবে।"},{"v":12,"ve":12,"vl":"12","bn":"“পায়খানার জন্য ছাউনির বাইরে তোমাদের একটা জায়গা ঠিক করে নিতে হবে।"},{"v":13,"ve":13,"vl":"13","bn":"তোমাদের অস্ত্রশস্ত্রের মধ্যে মাটি খুঁড়বার জন্য একটা কিছু রাখতে হবে। পায়খানা করবার আগে তোমরা সেটা দিয়ে গর্ত করে পায়খানা মাটি চাপা দিয়ে দেবে।"},{"v":14,"ve":14,"vl":"14","bn":"তোমাদের রক্ষা করবার জন্য এবং তোমাদের শত্রুদের তোমাদের হাতে তুলে দেবার জন্য তোমাদের মাবুদ আল্লাহ্‌ তোমাদের ছাউনির মধ্যে ঘুরে বেড়ান। সেইজন্য তোমাদের ছাউনি পাক-পবিত্র অবস্থায় রাখতে হবে যাতে তোমাদের মধ্যে জঘন্য কিছু দেখে তিনি তোমাদের দিক থেকে মুখ ফিরিয়ে না নেন।"},{"heading":"নানা রকম নিয়ম","v":15,"ve":15,"vl":"15","bn":"“কারও গোলাম যদি তোমাদের কাছে এসে আশ্রয় নেয় তবে তার মালিকের হাতে তাকে ফিরিয়ে দিয়ো না।"},{"v":16,"ve":16,"vl":"16","bn":"সেই গোলাম তোমাদের মধ্যে যেখানে বাস করতে চায় তাকে সেখানেই বাস করতে দিয়ো; তাকে কষ্ট দিয়ো না।"},{"v":17,"ve":17,"vl":"17","bn":"“কোন ইসরাইলীয় স্ত্রীলোক যেন মন্দির-বেশ্যা না হয়; কোন ইসরাইলীয় পুরুষও যেন মন্দির-বেশ্যার জীবন না কাটায়।"},{"v":18,"ve":18,"vl":"18","bn":"পুরুষ হোক বা স্ত্রীলোক হোক যে বেশ্যার জীবন কাটায় তার রোজগারের টাকা মানত পূরণের জন্য তোমাদের মাবুদ আল্লাহ্‌র ঘরে আনা চলবে না, কারণ এই রকম পুরুষ ও স্ত্রীলোকদের মাবুদ ঘৃণা করেন।"},{"v":19,"ve":19,"vl":"19","bn":"“তোমরা কোন ইসরাইলীয় ভাইয়ের কাছ থেকে সুদ নেবে না- সেই সুদ টাকা-পয়সার উপরেই হোক কিংবা খাবার জিনিসের উপরেই হোক কিংবা অন্য যে কোন জিনিসের উপরেই হোক।"},{"v":20,"ve":20,"vl":"20","bn":"অন্য জাতির লোকদের কাছ থেকে তোমরা সুদ নিতে পার কিন্তু কোন ইসরাইলীয় ভাইয়ের কাছ থেকে নয়। এইভাবে চললে তোমরা যে দেশ দখল করতে যাচ্ছ সেখানে তোমরা যাতে হাত দেবে তাতেই তোমাদের মাবুদ আল্লাহ্‌ তোমাদের দোয়া করবেন।"},{"v":21,"ve":21,"vl":"21","bn":"“তোমাদের মাবুদ আল্লাহ্‌র কাছে যদি তোমরা কোন মানত কর তবে তা পূরণ করতে দেরি কোরো না, কারণ তোমাদের মাবুদ আল্লাহ্‌ কখনও তা ছেড়ে দেবেন না। তা পূরণ না করলে তোমাদের গুনাহ্‌ হবে;"},{"v":22,"ve":22,"vl":"22","bn":"কিন্তু মানত না করলে গুনাহ্‌ হবে না।"},{"v":23,"ve":23,"vl":"23","bn":"তোমরা মুখ দিয়ে যে মানতের কথা উচ্চারণ করবে তা তোমাদের পূরণ করতেই হবে, কারণ তোমরা নিজের ইচ্ছায় নিজের মুখেই তোমাদের মাবুদ আল্লাহ্‌র কাছে সেই মানত করেছ।"},{"v":24,"ve":24,"vl":"24","bn":"“অন্য কারো আংগুর ক্ষেতে গিয়ে তোমরা খুশীমত আংগুর খেতে পারবে, কিন্তু তা নিয়ে যাওয়ার জন্য কোন কিছুতে তুলে রাখা চলবে না।"},{"v":25,"ve":25,"vl":"25","bn":"কারও শস্য ক্ষেতে গিয়ে তোমরা হাত দিয়ে শীষ ছিঁড়তে পারবে, কিন্তু ফসলের গায়ে কাসে- লাগানো চলবে না।"}],"24":[{"v":1,"ve":1,"vl":"1","bn":"“বিয়ে করবার পরে যদি কেউ স্ত্রীর মধ্যে কোন দোষ দেখে তার উপর অসন্তুষ্ট হয় আর তালাক-নামা লিখে তার হাতে দিয়ে তাকে বাড়ী থেকে বিদায় করে দেয়,"},{"v":2,"ve":3,"vl":"2-3","bn":"আর স্ত্রীলোকটি তার বাড়ী থেকে চলে গিয়ে যদি আর কাউকে বিয়ে করে এবং তার দ্বিতীয় স্বামীও যদি পরে তাকে অপছন্দ করে তার প্রতি তা-ই করে, কিংবা সেই স্বামী যদি মারা যায়,"},{"v":4,"ve":4,"vl":"4","bn":"তবে তার প্রথম স্বামী, যে তাকে বিদায় করে দিয়েছিল সে তাকে আর বিয়ে করতে পারবে না, কারণ সে নাপাক হয়ে গেছে। এই রকমের বিয়ে মাবুদ ঘৃণা করেন। সম্পত্তি হিসাবে যে দেশটা তোমাদের মাবুদ আল্লাহ্‌ তোমাদের দিতে যাচ্ছেন তোমরা এইভাবে তার উপর গুনাহ্‌ ডেকে আনবে না।"},{"v":5,"ve":5,"vl":"5","bn":"“অল্পদিন হয় বিয়ে করেছে এমন কোন লোককে যুদ্ধে পাঠানো চলবে না কিংবা তার উপর অন্য কোন কাজের বোঝা চাপিয়ে দেওয়া চলবে না। সে যাকে বিয়ে করেছে তার সন্তুষ্টির জন্য এক বছর পর্যন্ত এই সব কাজ থেকে রেহাই দিয়ে তাকে বাড়ীতে থাকতে দিতে হবে।"},{"v":6,"ve":6,"vl":"6","bn":"“ঋণের বন্ধক হিসাবে কারও জাঁতা কিংবা তার উপরের পাথরটাও নেওয়া চলবে না, কারণ তাতে লোকটির বেঁচে থাকবার উপায়টাই বন্ধক নেওয়া হবে।"},{"v":7,"ve":7,"vl":"7","bn":"“যদি দেখা যায়, কোন লোক কোন ইসরাইলীয় ভাইকে চুরি করে নিয়ে গোলাম হিসাবে ব্যবহার করছে কিংবা বিক্রি করে দিয়েছে, তবে সেই চোরকে মরতে হবে। তোমাদের মধ্য থেকে তোমরা এই রকম খারাপী শেষ করে দেবে।"},{"v":8,"ve":8,"vl":"8","bn":"“চর্মরোগ দেখা দিলে তোমাদের সতর্ক হতে হবে এবং লেবীয় ইমামেরা যে নির্দেশ দেবে তা যত্নের সংগে পালন করতে হবে। আমি তাদের যে হুকুম দিয়েছি তোমাদের সাবধান হয়ে সেইমত চলতে হবে।"},{"v":9,"ve":9,"vl":"9","bn":"মিসর দেশ থেকে বেরিয়ে আসবার পরে পথে তোমাদের মাবুদ আল্লাহ্‌ মরিয়মের ব্যাপারে যে ব্যবস্থা দিয়েছিলেন তা ভুলে যেয়ো না।"},{"v":10,"ve":10,"vl":"10","bn":"“কাউকে কিছু ধার দিয়ে বন্ধক হিসাবে কোন জিনিস নেবার জন্য তার বাড়ীর মধ্যে যেয়ো না।"},{"v":11,"ve":11,"vl":"11","bn":"তোমরা বাইরে থেকো এবং যাকে তুমি ধার দিচ্ছ তাকেই বন্ধক দেবার জিনিসটা বাইরে তোমাদের কাছে নিয়ে আসতে দিয়ো।"},{"v":12,"ve":12,"vl":"12","bn":"লোকটি যদি গরীব হয় তবে তার বন্ধক রাখা কাপড়টা নিজের কাছে রেখে দিয়ে ঘুমাতে যেয়ো না।"},{"v":13,"ve":13,"vl":"13","bn":"সন্ধ্যার সময় তাকে তা ফিরিয়ে দিতেই হবে যাতে সে তা গায়ে দিয়ে ঘুমাতে পারে। এতে সে তোমাদের ভাল চাইবে, আর তোমাদের মাবুদ আল্লাহ্‌র চোখে সেই ফিরিয়ে দেবার কাজটা হবে তোমাদের পক্ষে তাঁর ইচ্ছামত চলা।"},{"v":14,"ve":14,"vl":"14","bn":"“পাওনার ব্যাপারে কোন গরীব এবং অভাবী মজুরের প্রতি অন্যায় করবে না- সে তোমাদের কোন ইসরাইলীয় ভাই হোক কিংবা তোমাদের দেশের ভিন্ন জাতির কোন বাসিন্দাই হোক।"},{"v":15,"ve":15,"vl":"15","bn":"সূর্য ডুববার আগেই তোমরা তার মজুরি দিয়ে দেবে, কারণ সে গরীব এবং সেই মজুরির উপরেই সে ভরসা করছে। তা না করলে তোমাদের গুনাহ্‌ হবে, আর সে তোমাদের বিরুদ্ধে মাবুদের কাছে কাতর হয়ে বিচার চাইতে পারে।"},{"v":16,"ve":16,"vl":"16","bn":"“ছেলেমেয়েদের গুনাহের জন্য বাবাকে কিংবা বাবার গুনাহের জন্য ছেলেমেয়েদের হত্যা করা চলবে না। প্রত্যেককেই তার নিজের গুনাহের জন্য মরতে হবে।"},{"v":17,"ve":17,"vl":"17","bn":"“বিদেশী বাসিন্দা কিংবা এতিমের প্রতি অন্যায় বিচার হতে দিয়ো না। কোন বিধবার কাছ থেকে বন্ধক হিসাবে তার গায়ের কাপড় নিয়ো না।"},{"v":18,"ve":18,"vl":"18","bn":"মনে রেখো, মিসর দেশে তোমরা গোলাম ছিলে আর তোমাদের মাবুদ আল্লাহ্‌ সেখান থেকে তোমাদের মুক্ত করে এনেছেন। সেইজন্যই আমি তোমাদের এই সব করবার হুকুম দিচ্ছি।"},{"v":19,"ve":19,"vl":"19","bn":"“তোমাদের জমির ফসল কাটবার পরে যদি শস্যের কোন আঁটি তোমরা সংগে নিতে ভুলে যাও তবে সেটা আর ফিরে আনতে যেয়ো না। বিদেশী বাসিন্দা, এতিম এবং বিধবাদের জন্য সেটা ফেলে রেখো। তাতে তোমাদের মাবুদ আল্লাহ্‌ সব কাজেই তোমাদের দোয়া করবেন।"},{"v":20,"ve":20,"vl":"20","bn":"জলপাই পাড়বার সময় তোমরা একই ডাল থেকে দু’বার ফল পাড়তে যেয়ো না। যা থেকে যাবে তা বিদেশী বাসিন্দা, এতিম ও বিধবাদের জন্য রেখে দিয়ো।"},{"v":21,"ve":21,"vl":"21","bn":"তোমাদের আংগুর ক্ষেতের আংগুর তুলবার সময় তোমরা একই ডাল থেকে দু’বার আংগুর তুলো না। যা থেকে যাবে তা বিদেশী বাসিন্দা, এতিম ও বিধবাদের জন্য রেখে দিয়ো।"},{"v":22,"ve":22,"vl":"22","bn":"ভুলে যেয়ো না তোমরা মিসর দেশে গোলাম ছিলে। সেইজন্য আমি তোমাদের এই সব করতে হুকুম দিচ্ছি।"}],"25":[{"v":1,"ve":1,"vl":"1","bn":"“যদি লোকদের মধ্যে ঝগড়া-বিবাদ দেখা দেয় আর তা আদালতে নিয়ে যাওয়া হয় তবে বিচারকেরা তার বিচার করে নির্দোষকে নির্দোষ এবং দোষীকে দোষী বলে রায় দেবে।"},{"v":2,"ve":2,"vl":"2","bn":"সেই রায়ে দোষীকে যদি মার দেবার নির্দেশ দেওয়া হয় তবে বিচারক তাকে মাটিতে শুইয়ে দোষ অনুসারে যে কয়টা আঘাত তার পাওনা তা তাঁর নিজের সামনেই দেওয়াবে,"},{"v":3,"ve":3,"vl":"3","bn":"কিন্তু চল্লিশটার বেশী আঘাত তাকে দেওয়া চলবে না। এর বেশী দিলে একজন ইসরাইলীয় ভাইকে সকলের সামনে অসম্মান করা হবে।"},{"v":4,"ve":4,"vl":"4","bn":"“শস্য মাড়াই করবার সময়ে বলদের মুখে জাল্‌তি বেঁধো না।"},{"v":5,"ve":5,"vl":"5","bn":"“ভাইয়েরা এক পরিবার হয়ে বাস করবার সময়ে যদি এক ভাই ছেলে না রেখে মারা যায়, তবে তার বিধবা স্ত্রী পরিবারের বাইরে আর কাউকে বিয়ে করতে পারবে না। তার স্বামীর ভাই তাকে বিয়ে করবে এবং তার প্রতি স্বামীর ভাইয়ের যে কর্তব্য তা পালন করবে।"},{"v":6,"ve":6,"vl":"6","bn":"তাহলে তার যে প্রথম ছেলে হবে সে সেই মৃত ভাইয়ের নাম রক্ষা করবে আর সেই ভাইয়ের নাম বনি-ইসরাইলদের মধ্য থেকে মুছে যাবে না।"},{"v":7,"ve":7,"vl":"7","bn":"কিন্তু সে যদি ভাইয়ের স্ত্রীকে বিয়ে করতে না চায় তবে সেই স্ত্রী গ্রাম বা শহরের সদর দরজায় বৃদ্ধ নেতাদের কাছে গিয়ে বলবে, ‘আমার স্বামীর ভাই বনি-ইসরাইলদের মধ্যে তার ভাইয়ের নাম রক্ষা করতে রাজী নয়। আমার প্রতি তার যে কর্তব্য তা সে পালন করতে চায় না।’"},{"v":8,"ve":8,"vl":"8","bn":"তখন সেখানকার বৃদ্ধ নেতারা সেই লোকটিকে ডেকে বুঝাবেন। এর পরেও যদি সে বলতে থাকে যে, সে তাকে বিয়ে করতে রাজী নয়,"},{"v":9,"ve":9,"vl":"9","bn":"তবে তার ভাইয়ের স্ত্রী বৃদ্ধ নেতাদের সামনেই লোকটির কাছে গিয়ে তার পা থেকে এক পাটি জুতা খুলে নেবে এবং তার মুখে থুথু দিয়ে বলবে, ‘ভাইয়ের বংশ যে রক্ষা করতে চায় না তার প্রতি এ-ই করা হয়।’"},{"v":10,"ve":10,"vl":"10","bn":"বনি-ইসরাইলদের মধ্যে সেই লোকের বংশকে বলা হবে ‘জুতাহারার বংশ।’"},{"v":11,"ve":11,"vl":"11","bn":"“দু’জন লোক মারামারি করবার সময়ে যদি তাদের একজনের স্ত্রী তার স্বামীকে অন্যজনের হাত থেকে রক্ষা করবার উদ্দেশ্যে কাছে গিয়ে অন্য লোকটির পুরুষাংগ চেপে ধরে,"},{"v":12,"ve":12,"vl":"12","bn":"তবে তোমরা সেই স্ত্রীলোকের হাত কেটে ফেলবে। তাকে তোমরা কোন দয়া দেখাবে না।"},{"v":13,"ve":13,"vl":"13","bn":"“তোমাদের থলিতে যেন একই ওজন দেখাবার জন্য দু’টা করে বাট্‌খারা না থাকে, একটা বেশী ওজনের আর একটা কম ওজনের।"},{"v":14,"ve":14,"vl":"14","bn":"তোমাদের বাড়ীতে যেন একই মাপ দেখাবার জন্য দু’টা করে পাত্র না থাকে, একটা বেশী মাপের আর একটা কম মাপের।"},{"v":15,"ve":15,"vl":"15","bn":"তোমাদের মাবুদ আল্লাহ্‌ তোমাদের যে দেশ দিতে যাচ্ছেন সেখানে যেন তোমরা অনেক দিন বেঁচে থাকতে পার সেইজন্য তোমাদের ঠিক এবং উচিত মাপের বাট্‌খারা ও পাত্র রাখতে হবে।"},{"v":16,"ve":16,"vl":"16","bn":"এর কারণ হল, যে এই সব করে, অর্থাৎ যে ঠকিয়ে বেড়ায় তোমাদের মাবুদ আল্লাহ্‌ তাকে ঘৃণা করেন।"},{"v":17,"ve":17,"vl":"17","bn":"“তোমরা মিসর দেশ থেকে বের হয়ে আসবার পরে আমালেকীয়রা পথে তোমাদের সংগে যা করেছিল তা ভুলে যেয়ো না।"},{"v":18,"ve":18,"vl":"18","bn":"তোমাদের শ্রান্ত-ক্লান্ত অবস্থায় যারা পিছনে পড়েছিল তারা তাদের উপর হামলা চালিয়েছিল। তারা আল্লাহ্‌কে ভয় করে নি।"},{"v":19,"ve":19,"vl":"19","bn":"তোমাদের মাবুদ আল্লাহ্‌ যে দেশটা সম্পত্তি হিসাবে দখল করবার জন্য তোমাদের দিতে যাচ্ছেন সেখানে তোমাদের চারপাশের শত্রুদের সংগে লড়াই থেকে তিনি যখন তোমাদের বিশ্রাম দেবেন তখন দুনিয়ার উপর থেকে আমালেকীয়দের চিহ্ন তোমাদের একেবারে মুছে ফেলতে হবে। এই কথা তোমরা ভুলে যেয়ো না।"}],"26":[{"heading":"প্রথমে তোলা ফসল ও দশমাংশ","v":1,"ve":1,"vl":"1","bn":"“তোমাদের মাবুদ আল্লাহ্‌ যে দেশটা সম্পত্তি হিসাবে তোমাদের দিতে যাচ্ছেন তোমরা সেটা দখল করে যখন সেখানে বাস করতে থাকবে,"},{"v":2,"ve":2,"vl":"2","bn":"তখন তোমাদের মাবুদ আল্লাহ্‌র দেওয়া সেই দেশের জমিতে তোমরা যে সব ফসল ফলাবে তার প্রথমে তোলা কিছু ফসল টুকরিতে রাখবে। তোমাদের মাবুদ আল্লাহ্‌ নিজেকে প্রকাশ করবার জন্য যে জায়গাটা তাঁর বাসস্থান হিসাবে বেছে নেবেন সেই ফসল তোমরা সেখানে নিয়ে যাবে।"},{"v":3,"ve":3,"vl":"3","bn":"তখন যে ইমাম থাকবে তোমরা প্রত্যেকে তাকে বলবে, ‘আপনার মাবুদ আল্লাহ্‌র কাছে আজ আমি স্বীকার করছি যে, তিনি যে দেশটা আমাদের দেবেন বলে আমাদের পূর্বপুরুষদের কাছে কসম খেয়েছিলেন সেই দেশে আমি এসে গেছি।’"},{"v":4,"ve":4,"vl":"4","bn":"তখন ইমাম তোমাদের হাত থেকে সেই সব টুকরি নিয়ে তোমাদের মাবুদ আল্লাহ্‌র কোরবানগাহের সামনে রাখবে।"},{"v":5,"ve":5,"vl":"5","bn":"তারপর তোমরা প্রত্যেকে তোমাদের মাবুদ আল্লাহ্‌র সামনে বলবে, ‘আমার পূর্বপুরুষ ছিলেন একজন ইরামীয় যাযাবর। তিনি মাত্র কয়েকজন লোক নিয়ে মিসর দেশে চলে গিয়েছিলেন এবং সেখানে বাস করবার সময় তাঁর মধ্য দিয়ে একটি মহান ও শক্তিশালী জাতির সৃষ্টি হয়েছিল যার লোকসংখ্যা ছিল অনেক।"},{"v":6,"ve":6,"vl":"6","bn":"কিন্তু মিসরীয়রা আমাদের সংগে ভাল ব্যবহার করে নি। তারা আমাদের কষ্ট দিয়েছিল এবং আমাদের উপর একটা কঠিন পরিশ্রমের বোঝা চাপিয়ে দিয়েছিল।"},{"v":7,"ve":7,"vl":"7","bn":"তখন আমরা আমাদের পূর্বপুরুষদের মাবুদ আল্লাহ্‌র কাছে কান্নাকাটি করলাম। তিনি আমাদের কান্না শুনলেন, আমাদের কষ্ট ও পরিশ্রম দেখলেন; আরও দেখলেন আমাদের উপর কি রকম জুলুম করা হচ্ছে।"},{"v":8,"ve":8,"vl":"8","bn":"সেইজন্য তিনি তাঁর কঠোর এবং শক্তিশালী হাত বাড়িয়ে ভয় জাগানো কাজ এবং অলৌকিক চিহ্ন ও কুদরতি দেখিয়ে মিসর দেশ থেকে আমাদের বের করে আনলেন।"},{"v":9,"ve":9,"vl":"9","bn":"তিনি আমাদের এখানে এনেছেন এবং দুধ আর মধুতে ভরা এই দেশ আমাদের দিয়েছেন।"},{"v":10,"ve":10,"vl":"10","bn":"সেইজন্য হে মাবুদ, তোমার দেওয়া জমির প্রথমে তোলা ফসল আমি তোমার কাছেই এনেছি।’ এই বলে তোমাদের মাবুদ আল্লাহ্‌র সামনে তোমরা তোমাদের টুকরি রাখবে এবং তাঁকে সেজদা করবে।"},{"v":11,"ve":11,"vl":"11","bn":"তোমাদের এবং তোমাদের পরিবারকে তোমাদের মাবুদ আল্লাহ্‌ যে সব ভাল ভাল জিনিস দিয়ে দোয়া করেছেন তা নিয়ে তোমরা, লেবীয়রা এবং তোমাদের মধ্যেকার বিদেশী বাসিন্দারা আনন্দ করবে।"},{"v":12,"ve":12,"vl":"12","bn":"“প্রত্যেক তৃতীয় বছরে তোমাদের সব ফসলের দশ ভাগের এক ভাগ আদায় করা শেষ হলে পর সেগুলো তোমরা লেবীয়, বিদেশী বাসিন্দা, এতিম এবং বিধবাদের দেবে। তাতে ঐ সব লোকেরা তোমাদের দেশের মধ্যে খাওয়া-দাওয়া করে তৃপ্ত হবে।"},{"v":13,"ve":13,"vl":"13","bn":"তারপর তোমরা প্রত্যেকে তোমাদের মাবুদ আল্লাহ্‌কে বলবে, ‘আমি তোমার হুকুম অনুসারে আমার আয় থেকে পবিত্র অংশটা বাড়ী থেকে বের করে এনে লেবীয়, বিদেশী বাসিন্দা, এতিম এবং বিধবাদের দিয়েছি। তোমার হুকুম আমি অমান্য করি নি কিংবা সেগুলোর একটাও আমি ভুলে যাই নি।"},{"v":14,"ve":14,"vl":"14","bn":"মৃতদের জন্য শোক প্রকাশের অবস্থায় আমি পবিত্র অংশ থেকে কোন কিছু খাই নি, কিংবা নাপাক অবস্থায় তা বাড়ী থেকে বের করি নি, কিংবা তা থেকে কোন অংশ মৃত লোকদের উদ্দেশে দান করি নি। আমি আমার মাবুদ আল্লাহ্‌র কথামত কাজ করেছি। তোমার হুকুম করা সব কিছুই আমি করেছি।"},{"v":15,"ve":15,"vl":"15","bn":"হে মাবুদ, তোমার পবিত্র বাসস্থান বেহেশত থেকে তুমি নীচে তাকিয়ে দেখ আর তোমার বান্দাদের, অর্থাৎ বনি-ইসরাইলদের তুমি দোয়া কর। আমাদের পূর্বপুরুষদের কাছে তোমার কসম খাওয়া ওয়াদা অনুসারে দুধ আর মধুতে ভরা যে দেশ তুমি আমাদের দিয়েছ সেই দেশকেও দোয়া কর।’"},{"heading":"মাবুদের হুকুম পালন করবার নির্দেশ","v":16,"ve":16,"vl":"16","bn":"“তোমাদের মাবুদ আল্লাহ্‌ আজ তোমাদের এই সমস্ত নিয়ম ও নির্দেশ মেনে চলবার হুকুম দিচ্ছেন। তোমরা সতর্ক হয়ে সমস্ত মনপ্রাণ দিয়ে তা পালন করবে।"},{"v":17,"ve":17,"vl":"17","bn":"আজকেই তোমরা স্বীকার করেছ যে, আল্লাহ্‌ই তোমাদের মাবুদ আর তাঁর পথেই তোমরা চলবে। তোমরা স্বীকার করেছ যে, তাঁর নিয়ম, হুকুম ও নির্দেশ তোমরা পালন করবে এবং তাঁর কথামতই চলবে।"},{"v":18,"ve":18,"vl":"18","bn":"আর মাবুদও আজকে ঘোষণা করেছেন যে, তাঁর ওয়াদা অনুসারে তোমরা তাঁরই বান্দা এবং তাঁর নিজের বিশেষ সম্পত্তি হয়েছ। তাঁর সব হুকুম তোমাদের মেনে চলতে হবে।"},{"v":19,"ve":19,"vl":"19","bn":"তিনি ঘোষণা করেছেন যে, প্রশংসা, সুনাম ও গৌরবের দিক থেকে তাঁর সৃষ্ট অন্যান্য জাতিদের উপরে তিনি তোমাদের স্থান দেবেন এবং তোমাদের মাবুদ আল্লাহ্‌র ওয়াদা অনুসারে তোমরা হবে তাঁর উদ্দেশ্যে একটা পবিত্র জাতি।”"}],"27":[{"heading":"এবল পাহাড়ের কোরবানগাহ্‌","v":1,"ve":1,"vl":"1","bn":"মূসা ইসরাইলীয় বৃদ্ধ নেতাদের সংগে নিয়ে লোকদের বললেন, “যে সব হুকুম আজ আমি তোমাদের দিচ্ছি তা তোমরা পালন করবে।"},{"v":2,"ve":2,"vl":"2","bn":"তোমরা জর্ডান নদী পার হয়ে তোমাদের মাবুদ আল্লাহ্‌র দেওয়া দেশে গিয়ে কতগুলো বড় বড় পাথর খাড়া করে নেবে এবং সেগুলো চুন দিয়ে লেপে দেবে,"},{"v":3,"ve":3,"vl":"3","bn":"আর সেগুলোর উপর এই শরীয়তের সব কথাগুলো লিখবে। তোমাদের পূর্বপুরুষদের মাবুদ আল্লাহ্‌ তোমাদের কাছে করা তাঁর ওয়াদা অনুসারে দুধ আর মধুতে ভরা যে দেশটি তোমাদের দিতে যাচ্ছেন তোমরা সেখানে যাওয়ার পর,"},{"v":4,"ve":4,"vl":"4","bn":"অর্থাৎ জর্ডান নদী পার হয়ে যাওয়ার পর আমার আজকের হুকুম অনুসারে তোমরা এবল পাহাড়ের উপর সেই পাথরগুলো খাড়া করে নিয়ে চুন দিয়ে লেপে দেবে।"},{"v":5,"ve":5,"vl":"5","bn":"তোমাদের মাবুদ আল্লাহ্‌র উদ্দেশে তোমরা সেখানে একটা পাথরের কোরবানগাহ্‌ তৈরী করবে। পাথরগুলোর উপর তোমরা কোন লোহার যন্ত্রপাতি ব্যবহার করবে না।"},{"v":6,"ve":6,"vl":"6","bn":"তোমাদের মাবুদ আল্লাহ্‌র এই কোরবানগাহ্‌টি তোমরা গোটা গোটা পাথর দিয়ে তৈরী করবে আর তার উপর তোমরা তোমাদের মাবুদ আল্লাহ্‌র উদ্দেশে পোড়ানো-কোরবানী দেবে।"},{"v":7,"ve":7,"vl":"7","bn":"সেখানে তোমরা যোগাযোগ-কোরবানী দেবে ও সেই কোরবানীর জিনিস খেয়ে তোমাদের মাবুদ আল্লাহ্‌র সামনে আনন্দ করবে।"},{"v":8,"ve":8,"vl":"8","bn":"যে পাথরগুলো তোমরা খাড়া করে নেবে তার উপর এই শরীয়তের সব কথাগুলো খুব স্পষ্ট করে লিখবে।”"},{"heading":"এবল পাহাড় থেকে বদদোয়া উচ্চারণ","v":9,"ve":9,"vl":"9","bn":"এর পর মূসা লেবীয় ইমামদের নিয়ে সমস্ত বনি-ইসরাইলদের বললেন, “হে বনি-ইসরাইলরা, তোমরা চুপ করে শোন। আজ তোমরা তোমাদের মাবুদ আল্লাহ্‌র নিজের বান্দা হয়েছ।"},{"v":10,"ve":10,"vl":"10","bn":"তোমরা তাঁর বাধ্য হয়ে চলবে। আজ আমি যে সব হুকুম ও নিয়ম তোমাদের দিচ্ছি তা তোমরা পালন করে চলবে।”"},{"v":11,"ve":11,"vl":"11","bn":"ঐ দিনই মূসা লোকদের এই হুকুম দিলেন,"},{"v":12,"ve":12,"vl":"12","bn":"“তোমরা জর্ডান নদী পার হয়ে যাবার পর যখন মাবুদের দোয়া উচ্চারণ করা হবে তখন শিমিয়োন, লেবি, এহুদা, ইষাখর, ইউসুফ ও বিন্যামীন-গোষ্ঠীর লোকেরা গরিষীম পাহাড়ের উপরে থাকবে।"},{"v":13,"ve":13,"vl":"13","bn":"আর যখন তাঁর বদদোয়া উচ্চারণ করা হবে তখন রূবেণ, গাদ, আশের, সবূলূন, দান ও নপ্তালি-গোষ্ঠীর লোকেরা এবল পাহাড়ের উপরে থাকবে।"},{"v":14,"ve":14,"vl":"14","bn":"“লেবীয়রা তখন সমস্ত বনি-ইসরাইলদের সামনে চিৎকার করে এই কথা বলবে:"},{"v":15,"ve":15,"vl":"15","bn":"‘সেই লোক বদদোয়াপ্রাপ্ত, যে ছাঁচে ফেলে কিংবা কাঠ বা পাথর খোদাই করে কোন মূর্তি তৈরী করে এবং পূজার জন্য তা গোপন জায়গায় স্থাপন করে। এই সব মূর্তি মাবুদের ঘৃণার জিনিস, কারিগরের হাতের কাজ মাত্র।’ তখন সবাই বলবে, ‘আমিন।’"},{"v":16,"ve":16,"vl":"16","bn":"‘সেই লোক বদদোয়াপ্রাপ্ত, যে মা কিংবা বাবাকে অসম্মান করে।’ তখন সকলে বলবে, ‘আমিন।’"},{"v":17,"ve":17,"vl":"17","bn":"‘সেই লোক বদদোয়াপ্রাপ্ত, যে অন্য লোকের জমির সীমানা-চিহ্ন সরিয়ে দেয়।’ তখন সকলে বলবে, ‘আমিন।’"},{"v":18,"ve":18,"vl":"18","bn":"‘সেই লোক বদদোয়াপ্রাপ্ত, যে অন্ধকে ভুল পথে নিয়ে যায়।’ তখন সকলে বলবে, ‘আমিন।’"},{"v":19,"ve":19,"vl":"19","bn":"‘সেই লোক বদদোয়াপ্রাপ্ত, যে বিদেশী বাসিন্দা, এতিম এবং বিধবাদের প্রতি অন্যায় বিচার হতে দেয়।’ তখন সকলে বলবে, ‘আমিন।’"},{"v":20,"ve":20,"vl":"20","bn":"‘সেই লোক বদদোয়াপ্রাপ্ত, যে তার সৎমায়ের সংগে জেনা করে, কারণ তাতে তার বাবাকে সে অসম্মান করে।’ তখন সকলে বলবে, ‘আমিন।’"},{"v":21,"ve":21,"vl":"21","bn":"‘সেই লোক বদদোয়াপ্রাপ্ত, যে পশুর সংগে সহবাস করে।’ তখন সকলে বলবে, ‘আমিন।’"},{"v":22,"ve":22,"vl":"22","bn":"‘সেই লোক বদদোয়াপ্রাপ্ত, যে তার সৎবোনের সংগে জেনা করে- সে বাবার মেয়ে হোক কিংবা মায়ের মেয়ে হোক।’ তখন সকলে বলবে, ‘আমিন।’"},{"v":23,"ve":23,"vl":"23","bn":"‘সেই লোক বদদোয়াপ্রাপ্ত, যে তার শাশুড়ীর সংগে জেনা করে।’ তখন সকলে বলবে, ‘আমিন।’"},{"v":24,"ve":24,"vl":"24","bn":"‘সেই লোক বদদোয়াপ্রাপ্ত, যে কাউকে গোপনে খুন করে।’ তখন সকলে বলবে, ‘আমিন।’"},{"v":25,"ve":25,"vl":"25","bn":"‘সেই লোক বদদোয়াপ্রাপ্ত, যে নির্দোষ লোককে খুন করবার জন্য ঘুষ নেয়।’ তখন সকলে বলবে, ‘আমিন।’"},{"v":26,"ve":26,"vl":"26","bn":"‘সেই লোক বদদোয়াপ্রাপ্ত, যে এই শরীয়তের কথাগুলো পালন করে না এবং তার ক্ষমতাকে অস্বীকার করে।’ তখন সকলে বলবে, ‘আমিন।’"}],"28":[{"heading":"বাধ্যতার ফল","v":1,"ve":1,"vl":"1","bn":"“তোমাদের মাবুদ আল্লাহ্‌র প্রতি যদি তোমাদের পূর্ণ বাধ্যতা থাকে এবং আজ আমি তাঁর যে সব হুকুম তোমাদের দিচ্ছি তা যদি তোমরা যত্নের সংগে পালন কর, তবে তিনি দুনিয়ার অন্য সব জাতির উপরে তোমাদের স্থান দেবেন।"},{"v":2,"ve":2,"vl":"2","bn":"তোমরা যদি তোমাদের মাবুদ আল্লাহ্‌র বাধ্য হও তবে এই সব দোয়া তোমরা পাবে আর তা তোমাদের সংগে থাকবে:"},{"v":3,"ve":3,"vl":"3","bn":"তোমাদের বাসস্থান ও ক্ষেত-খামারের সব কিছুতে তোমরা দোয়া পাবে।"},{"v":4,"ve":4,"vl":"4","bn":"তোমরা দোয়া পাবে যার ফলে তোমাদের পরিবারের অনেক সন্তান, ক্ষেতে প্রচুর ফসল এবং পালের গরু-ছাগল-ভেড়ার অনেক বাচ্চা হবে।"},{"v":5,"ve":5,"vl":"5","bn":"তোমাদের ফসলের ঝুড়ি ও ময়দা ঠাঁসবার পাত্র দোয়া পাবে।"},{"v":6,"ve":6,"vl":"6","bn":"প্রতিদিনকার জীবনে তোমরা দোয়া পাবে।"},{"v":7,"ve":7,"vl":"7","bn":"“যারা শত্রু হয়ে তোমাদের বিরুদ্ধে দাঁড়াবে মাবুদ এমন করবেন যাতে তারা তোমাদের কাছে হেরে যায়। তারা এক দিক দিয়ে তোমাদের আক্রমণ করতে এসে সাত দিক দিয়ে পালিয়ে যাবে।"},{"v":8,"ve":8,"vl":"8","bn":"“তোমাদের গোলাঘরের উপর মাবুদের দোয়া থাকবে এবং যে কাজে তোমরা হাত দেবে তাতেই তিনি দোয়া করবেন। তোমাদের মাবুদ আল্লাহ্‌ তাঁর দেওয়া দেশে তোমাদের দোয়া করবেন।"},{"v":9,"ve":9,"vl":"9","bn":"“যদি তোমরা তোমাদের মাবুদ আল্লাহ্‌র হুকুমগুলো পালন কর এবং তাঁর পথে চল তবে তিনি তাঁর কসম খেয়ে ওয়াদা অনুসারে, তাঁর পবিত্র জাতি হিসাবে তোমাদের দাঁড় করাবেন।"},{"v":10,"ve":10,"vl":"10","bn":"তখন দুনিয়ার সমস্ত জাতি দেখতে পাবে যে, মাবুদের নামেই তোমাদের পরিচয়, আর তাতে তারা তোমাদের ভয় করে চলবে।"},{"v":11,"ve":11,"vl":"11","bn":"যে দেশটা তোমাদের দেবেন বলে মাবুদ তোমাদের পূর্বপুরুষদের কাছে কসম খেয়েছিলেন সেই দেশে তিনি তোমাদের প্রচুর দান করবেন, অর্থাৎ তিনি তোমাদের পরিবারে অনেক ছেলেমেয়ে, পশুপালে অনেক বাচ্চা ও ক্ষেতে অনেক ফসল দেবেন।"},{"v":12,"ve":12,"vl":"12","bn":"“তোমাদের দেশে সময়মত বৃষ্টি দিয়ে তোমাদের হাতের সব কাজে দোয়া করবার জন্য মাবুদ তাঁর দানের ভাণ্ডার, অর্থাৎ আসমান খুলে দেবেন। তোমরা অনেক জাতিকে ঋণ দিতে পারবে, কিন্তু কারও কাছ থেকে তোমাদের ঋণ নিতে হবে না।"},{"v":13,"ve":13,"vl":"13","bn":"মাবুদ এমন করবেন যাতে তোমরা সকলের মাথার উপরে থাক, পায়ের তলায় নয়। তোমাদের মাবুদ আল্লাহ্‌র যে সব হুকুম আজ আমি তোমাদের দিচ্ছি তাতে যদি তোমরা কান দাও এবং যত্নের সংগে তা পালন কর, তবে সব সময় তোমাদের স্থান থাকবে উপরে, নীচে নয়।"},{"v":14,"ve":14,"vl":"14","bn":"আজ আমি তোমাদের যে সব হুকুম দিচ্ছি, দেব-দেবীর পিছনে গিয়ে এবং তাদের পূজা করে তোমরা তা থেকে এদিক ওদিক সরে যাবে না।"},{"heading":"অবাধ্যতার জন্য বদদোয়া","v":15,"ve":15,"vl":"15","bn":"“কিন্তু তোমরা যদি তোমাদের মাবুদ আল্লাহ্‌র কথায় কান না দাও এবং আজকের দেওয়া আমার এই সব হুকুম ও নিয়ম যত্নের সংগে পালন না কর, তবে এই সব বদদোয়া তোমাদের উপর নেমে আসবে এবং তোমাদের সংগে থাকবে:"},{"v":16,"ve":16,"vl":"16","bn":"তোমাদের বাসস্থান ও ক্ষেত-খামারের সব কিছুতে তোমরা বদদোয়াপ্রাপ্ত হবে।"},{"v":17,"ve":17,"vl":"17","bn":"তোমাদের ফসলের ঝুড়ি ও ময়দা ঠাঁসবার পাত্র বদদোয়াপ্রাপ্ত হবে।"},{"v":18,"ve":18,"vl":"18","bn":"তোমরা বদদোয়াপ্রাপ্ত হবে যার ফলে তোমাদের পরিবারে কম ছেলেমেয়ে, ক্ষেতে কম ফসল এবং পালের গরু, ছাগল ও ভেড়ার কম বাচ্চা হবে।"},{"v":19,"ve":19,"vl":"19","bn":"প্রতিদিনকার জীবনে তোমরা বদদোয়াপ্রাপ্ত হবে।"},{"v":20,"ve":20,"vl":"20","bn":"“খারাপ কাজ করে মাবুদকে ত্যাগ করবার অপরাধে তোমাদের সমস্ত কাজে তিনি তোমাদের বদদোয়া দেবেন, বিশৃঙ্খলায় ফেলবেন আর তিরস্কার করবেন, যার ফলে তোমরা ক্ষয় হতে হতে অল্প সময়ের মধ্যেই ধ্বংস হয়ে যাবে।"},{"v":21,"ve":21,"vl":"21","bn":"তোমরা যে দেশ দখল করতে যাচ্ছ মাবুদ সেখানে এমন করবেন যাতে তোমাদের মধ্যে মহামারী লেগেই থাকে আর শেষ পর্যন্ত তোমরা দেশ থেকে একেবারে শেষ হয়ে যাও।"},{"v":22,"ve":22,"vl":"22","bn":"ক্ষয় রোগ, তিন রকমের মারাত্মক জ্বর, যুদ্ধ, গরম শুকনা বাতাস এবং ছাৎলা- এই সব মাবুদ তোমাদের উপর নিয়ে আসবেন এবং তোমাদের কষ্ট দেবেন যতক্ষণ না তোমরা ধ্বংস হয়ে যাও।"},{"v":23,"ve":23,"vl":"23","bn":"তোমাদের মাথার উপরের আসমান হবে ব্রোঞ্জের মত শক্ত, আর পায়ের তলার মাটি হবে লোহার মত শক্ত।"},{"v":24,"ve":24,"vl":"24","bn":"মাবুদ এমন করবেন যাতে তোমাদের দেশে বৃষ্টির বদলে আসমান থেকে ধুলা আর বালি পড়ে। সেগুলো তোমাদের উপর পড়বে যতক্ষণ না তোমরা শেষ হয়ে যাও।"},{"v":25,"ve":25,"vl":"25","bn":"“মাবুদ এমন করবেন যাতে তোমরা তোমাদের শত্রুদের সামনে হেরে যাও। তোমরা এক দিক দিয়ে তাদের আক্রমণ করবে কিন্তু তাদের সামনে থেকে পালিয়ে যাবে সাত দিক দিয়ে। দুনিয়ার অন্য সব রাজ্যের লোকেরা তোমাদের অবস্থা দেখে ভয়ে আঁতকে উঠবে।"},{"v":26,"ve":26,"vl":"26","bn":"তোমাদের লাশ হবে আকাশের পাখী এবং দুনিয়ার পশুদের খাবার, আর তাদের তাড়িয়ে দেবার জন্য কেউ এগিয়ে আসবে না।"},{"v":27,"ve":27,"vl":"27","bn":"মাবুদ মিসরীয়দের সেই ফোড়া, আব, চুলকানি আর পাঁচড়া দিয়ে তোমাদের কষ্ট দেবেন যা থেকে কেউ তোমাদের ভাল করতে পারবে না।"},{"v":28,"ve":28,"vl":"28","bn":"তিনি পাগলামি ও অন্ধতা দিয়ে এবং চিন্তাশক্তি নষ্ট করে দিয়ে তোমাদের আরও কষ্ট দেবেন।"},{"v":29,"ve":29,"vl":"29","bn":"অন্ধ লোক যেমন অন্ধকারে হাতড়ে বেড়ায় তেমনি করে তোমরা দিনের বেলাতেই হাতড়ে বেড়াবে; তোমাদের কোন কাজই সফল হবে না। তোমাদের উপর সব সময় জুলুম আর লুট চলবে; তা থেকে তোমাদের উদ্ধার করবার জন্য কেউ এগিয়ে আসবে না।"},{"v":30,"ve":30,"vl":"30","bn":"“যে স্ত্রীলোকের সংগে তোমার বিয়ে ঠিক হবে অন্য লোকে তার ইজ্জত নষ্ট করবে। তোমরা বাড়ী তৈরী করবে কিন্তু তাতে থাকতে পারবে না। তোমরা আংগুর ক্ষেত করবে কিন্তু তার ফল মুখে দিতে পারবে না।"},{"v":31,"ve":31,"vl":"31","bn":"তোমাদের চোখের সামনেই তোমাদের গরু জবাই করা হবে, কিন্তু তার এক টুকরা গোশ্‌তও তোমাদের পেটে যাবে না। তোমাদের গাধাকে জোর করে তোমাদের কাছ থেকে নিয়ে যাওয়া হবে, কিন্তু তা আর ফিরিয়ে দেওয়া হবে না। তোমাদের ভেড়া তোমাদের শত্রুদের হাতে গিয়ে পড়বে; আর এই বিপদে তোমাদের উদ্ধার করতে কেউ এগিয়ে আসবে না।"},{"v":32,"ve":32,"vl":"32","bn":"তোমাদের ছেলেমেয়েরা অন্য জাতির হাতে পড়বে। দিনের পর দিন তাদের আসবার পথ চেয়ে তোমাদের চোখ অন্ধ হয়ে যাবে, কিন্তু কিছু করবার শক্তি তোমাদের হাতে থাকবে না।"},{"v":33,"ve":33,"vl":"33","bn":"তোমাদের অচেনা জাতির লোকেরা তোমাদের জমির ফসল ও পরিশ্রমের ফল ভোগ করবে আর তোমাদের সারাটা জীবন ধরে তোমরা কেবল জুলুম ও খারাপ ব্যবহার ভোগ করবে।"},{"v":34,"ve":34,"vl":"34","bn":"তোমরা যা দেখবে তা তোমাদের পাগল করে দেবে।"},{"v":35,"ve":35,"vl":"35","bn":"মাবুদ তোমাদের হাঁটুতে ও পায়ে এমন সব বিষফোড়া দিয়ে কষ্ট দেবেন যা কখনও ভাল হবে না। সেই ফোড়া তোমাদের পায়ের তলা থেকে মাথার তালু পর্যন্ত সব জায়গায় হবে।"},{"v":36,"ve":36,"vl":"36","bn":"“যাকে তোমরা বাদশাহ্‌ করে তোমাদের উপরে বসাবে মাবুদ তাকে এবং তোমাদের বন্দী করে নিয়ে যাওয়ার জন্য এমন এক জাতির হাতে ফেলবেন যাকে তোমরাও জান না এবং তোমাদের পূর্বপুরুষেরাও জানত না। সেখানে তোমরা কাঠ আর পাথরের দেব-মূর্তির পূজা করবে।"},{"v":37,"ve":37,"vl":"37","bn":"মাবুদ তোমাদের যে সব জাতির মধ্যে তাড়িয়ে দেবেন তারা তোমাদের অবস্থা দেখে ভয়ে আঁতকে উঠবে, আর তারা তোমাদের ঠাট্টা-তামাশা করবে ও কটুকথায় বিঁধবে।"},{"v":38,"ve":38,"vl":"38","bn":"“তোমরা বুনবে অনেক কিন্তু কাটবে কম, কারণ পংগপালে ফসল খেয়ে ফেলবে।"},{"v":39,"ve":39,"vl":"39","bn":"তোমরা আংগুর ক্ষেত করবে এবং তার যত্নও নেবে কিন্তু পোকায় তার ফল খেয়ে ফেলবে বলে তোমরা তা তুলতেও পারবে না কিংবা তার রসও খেতে পারবে না।"},{"v":40,"ve":40,"vl":"40","bn":"তোমাদের সারা দেশে জলপাই গাছ থাকবে কিন্তু তার ফল ঝরে পড়ে যাবে বলে জলপাই তেল মাখা তোমাদের হবে না।"},{"v":41,"ve":41,"vl":"41","bn":"যে সব ছেলেমেয়ে তোমাদের হবে তারা তোমাদের কাছে থাকবে না, কারণ তাদের বন্দী করে নিয়ে যাওয়া হবে।"},{"v":42,"ve":42,"vl":"42","bn":"ঝাঁকে ঝাঁকে পংগপাল এসে তোমাদের দেশের গাছ-গাছড়া ও ফসল খেয়ে ফেলবে।"},{"v":43,"ve":43,"vl":"43","bn":"“তোমাদের মধ্যে বাস করা অন্যান্য জাতির লোকেরা তোমাদের উপরে উঠতে থাকবে আর তোমরা নামতে থাকবে তাদের নীচে।"},{"v":44,"ve":44,"vl":"44","bn":"তারাই তোমাদের ঋণ দেবে কিন্তু তোমরা তাদের ঋণ দিতে পারবে না। তারা থাকবে তোমাদের মাথার উপরে আর তোমরা থাকবে তাদের পায়ের তলায়।"},{"v":45,"ve":45,"vl":"45","bn":"“এই সব বদদোয়া তোমাদের উপরে নেমে আসবে। তোমরা তোমাদের মাবুদ আল্লাহ্‌র বাধ্য না হওয়ার দরুন এবং তিনি যে সব হুকুম ও নিয়ম দিয়েছেন তা পালন না করবার দরুন এই সব বদদোয়া তোমাদের পিছনে তাড়া করে আসবে ও তোমাদের ধরে ফেলবে এবং শেষ পর্যন্ত তোমরা ধ্বংস হয়ে যাবে।"},{"v":46,"ve":46,"vl":"46","bn":"এই বদদোয়াগুলো অলৌকিক চিহ্ন ও অলৌকিক কাজ হিসাবে তোমাদের ও তোমাদের বংশধরদের উপর চিরকাল থাকবে।"},{"v":47,"ve":48,"vl":"47-48","bn":"সুদিনে খুশী মনে এবং আনন্দের সংগে তোমাদের মাবুদ আল্লাহ্‌র এবাদত না করবার দরুন খাওয়া-পরার অভাব, পিপাসা আর ভীষণ অভাবের মধ্যে তোমরা সেই সব শত্রুর সেবা করবে যাদের মাবুদ তোমাদের বিরুদ্ধে পাঠিয়ে দেবেন। তিনি তোমাদের ঘাড়ে লোহার জোয়াল চাপিয়ে রাখবেন যতক্ষণ না তোমরা ধ্বংস হয়ে যাও।"},{"v":49,"ve":49,"vl":"49","bn":"“মাবুদ দূর থেকে, দুনিয়ার শেষ সীমানা থেকে এমন এক জাতিকে তোমাদের বিরুদ্ধে নিয়ে আসবেন যাদের ভাষা তোমরা বুঝবে না। ঈগল পাখীর মত করে সেই জাতি ছোঁ মেরে তোমাদের উপর নেমে আসবে।"},{"v":50,"ve":50,"vl":"50","bn":"তারা হবে ভীষণ চেহারার লোক। তারা বুড়োদের সম্মান করবে না আর ছেলেমেয়েদের দয়ামায়া করবে না।"},{"v":51,"ve":51,"vl":"51","bn":"তারা তোমাদের পশুর বাচ্চা ও ক্ষেতের ফসল খেয়ে ফেলবে এবং শেষ পর্যন্ত তোমরা ধ্বংস হয়ে যাবে। তারা তোমাদের জন্য কোন ফসল, নতুন আংগুর-রস কিংবা তেল কিংবা গরুর বাছুর বা ভেড়ার বাচ্চা বাকী রাখবে না, আর শেষ পর্যন্ত তোমরা ধ্বংস হয়ে যাবে।"},{"v":52,"ve":52,"vl":"52","bn":"তারা তোমাদের গ্রাম ও শহরগুলো ঘেরাও করে রাখবে, আর শেষ পর্যন্ত তোমাদের উঁচু ও শক্ত দেয়ালগুলো ভেংগে পড়বে যার উপর তোমরা এত ভরসা করছ। তোমাদের মাবুদ আল্লাহ্‌ যে দেশ তোমাদের দিতে যাচ্ছেন সেই দেশের সমস্ত গ্রাম ও শহর তারা ঘেরাও করবে।"},{"v":53,"ve":53,"vl":"53","bn":"“সেগুলো ঘেরাও করে রাখবার সময় শত্রুরা তোমাদের এমন কষ্টে ফেলবে যে, তোমরা তোমাদের নিজেদের সন্তানদেরই খাবে, অর্থাৎ তোমরা তোমাদের মাবুদ আল্লাহ্‌র দেওয়া ছেলেমেয়েদের গোশ্‌ত খাবে।"},{"v":54,"ve":54,"vl":"54","bn":"তখন তোমাদের মধ্যে যে লোক কোমল স্বভাবের আর ভাল অবস্থায় মানুষ হয়েছে, তার অন্তরও এমন হবে যে, নিজের ভাইয়ের প্রতি, কিংবা প্রিয় স্ত্রীর প্রতি, কিংবা জীবিত ছেলেমেয়েদের প্রতি তার কোন দয়ামায়া থাকবে না।"},{"v":55,"ve":55,"vl":"55","bn":"যে সন্তানের গোশ্‌ত সে খাবে তার একটুও সে তাদের দেবে না, কারণ শত্রুরা যখন তোমাদের গ্রাম বা শহর ঘেরাও করে রেখে তোমাদের কষ্টে ফেলবে তখন এছাড়া আর কোন খাবারই তার কাছে থাকবে না।"},{"v":56,"ve":56,"vl":"56","bn":"তোমাদের মধ্যে যে স্ত্রীলোক কোমল স্বভাবের এবং এমন ভাল অবস্থায় মানুষ হয়েছে যে তাকে কোন দিন মাটিতে পা ফেলতে হয় নি, তারও তার প্রিয় স্বামী ও ছেলেমেয়েদের প্রতি কোন দয়ামায়া থাকবে না।"},{"v":57,"ve":57,"vl":"57","bn":"সন্তান জন্মের পর সেই সন্তান এবং তার পরে শরীর থেকে বের হয়ে আসা ফুল, এর কোনটাই সে তাদের খেতে দেবে না। তোমাদের ঘেরাও করে রাখবার সময় তোমাদের শত্রুরা যখন তোমাদের কষ্টে ফেলবে তখন সে নিজেই সেই ফুল ও সন্তান চুপিচুপি খাবে।"},{"v":58,"ve":58,"vl":"58","bn":"“এই কিতাবে যে সব শরীয়ত লেখা রয়েছে তা যদি তোমরা যত্নের সংগে মেনে না চল, অর্থাৎ ‘তোমাদের মাবুদ আল্লাহ্‌’ বলে তাঁর এই যে গৌরবপূর্ণ ও ভয় জাগানো নামটি রয়েছে যদি তোমরা সেই নামের সম্মান না কর,"},{"v":59,"ve":59,"vl":"59","bn":"তবে মাবুদ তোমাদের ও তোমাদের বংশধরদের উপর এমন সব ভীষণ ও অদ্ভুত রকমের আঘাত ও কষ্ট দেওয়া রোগ নিয়ে আসবেন যা অনেক দিন ধরে চলবে।"},{"v":60,"ve":60,"vl":"60","bn":"মিসর দেশে যে সব রোগ দেখে তোমরা ভয় পেতে, তিনি সেই সবই তোমাদের উপর আনবেন আর সেগুলো তোমাদের ছাড়বে না।"},{"v":61,"ve":61,"vl":"61","bn":"এছাড়া মাবুদ এমন সব রোগ ও আঘাত তোমাদের উপর আনবেন যার কথা এই তৌরাত কিতাবের মধ্যে লেখা নেই, আর শেষ পর্যন্ত তোমরা ধ্বংস হয়ে যাবে।"},{"v":62,"ve":62,"vl":"62","bn":"তোমাদের লোকসংখ্যা আসমানের তারার মত হলেও তোমাদের মাবুদ আল্লাহ্‌র প্রতি অবাধ্যতার দরুন তোমরা তখন মাত্র অল্প কয়েকজনই বেঁচে থাকবে।"},{"v":63,"ve":63,"vl":"63","bn":"যে আনন্দে মাবুদ তোমাদের উন্নতি করেছেন ও তোমাদের লোকসংখ্যা বাড়িয়ে তুলেছেন সেই আনন্দে তখন তিনি তোমাদের ধ্বংস করে শেষ করে দেবেন। যে দেশ তোমরা দখল করতে যাচ্ছ সেই দেশ থেকে শিকড়সুদ্ধ তোমাদের তুলে ফেলা হবে।"},{"v":64,"ve":64,"vl":"64","bn":"“তারপর মাবুদ দুনিয়ার এক সীমা থেকে অন্য সীমা পর্যন্ত সমস্ত জাতির মধ্যে তোমাদের ছড়িয়ে দেবেন। তোমরা সেখানে তোমাদের এবং তোমাদের পূর্বপুরুষদের অজানা কাঠের ও পাথরের দেব-মূর্তির পূজা করবে।"},{"v":65,"ve":65,"vl":"65","bn":"সেই সব জাতির মধ্যে তোমরা শান্তি পাবে না, আর তোমাদের বিশ্রাম করবার নিজের কোন জায়গা থাকবে না। সেখানে মাবুদ তোমাদের মন দুশ্চিন্তায় ভরে তুলবেন এবং আশা করে চেয়ে থাকা চোখ তোমাদের ক্লান্ত করে তুলবেন, আর তোমাদের অন্তর নিরাশায় ভরে দেবেন।"},{"v":66,"ve":66,"vl":"66","bn":"কি হবে না হবে এই ভাবটা তোমাদের পেয়ে বসবে; আর দিনরাত ভয়-ভরা অন্তরে তোমরা বেঁচে থাকা সম্বন্ধে কখনও নিশ্চিত হতে পারবে না।"},{"v":67,"ve":67,"vl":"67","bn":"তোমরা সকালবেলা বলবে, ‘সন্ধ্যা হোক,’ আর সন্ধ্যাবেলা বলবে, ‘সকাল হোক,’ কারণ তোমাদের অন্তর ভয়ে ভরা থাকবে আর চোখ অনেক কিছু দেখবে।"},{"v":68,"ve":68,"vl":"68","bn":"মিসরে যাওয়া সম্বন্ধে আমি তোমাদের বলেছিলাম যে, সেই পথে আর কখনও তোমাদের পা দিতে হবে না; কিন্তু মাবুদ তখন জাহাজ ভরে ভরে তোমাদের মিসরে ফেরৎ পাঠাবেন। সেখানে তোমরা গোলাম ও বাঁদী হিসাবে শত্রুদের কাছে নিজেদের বিক্রি করতে চাইবে কিন্তু কেউ তোমাদের কিনবে না।”"}],"29":[{"v":1,"ve":1,"vl":"1","bn":"মাবুদ তুর পাহাড়ে মূসার মধ্য দিয়ে বনি-ইসরাইলদের জন্য একটা ব্যবস্থা স্থাপন করেছিলেন, আর এগুলো হল তাঁর দ্বিতীয় ব্যবস্থার শর্ত যা তিনি মূসাকে মোয়াব দেশে বনি-ইসরাইলদের জন্য স্থাপন করতে বলেছিলেন।"},{"heading":"মোয়াব দেশে হযরত মূসা (আঃ)-এর ঘোষণা","v":2,"ve":2,"vl":"2","bn":"মূসা সব বনি-ইসরাইলদের ডেকে বললেন, “মাবুদ মিসর দেশের ফেরাউন ও তাঁর সমস্ত কর্মচারীর প্রতি এবং তাঁর গোটা দেশটার প্রতি যা করেছিলেন তা তোমরা নিজেরাই দেখেছ।"},{"v":3,"ve":3,"vl":"3","bn":"তাঁদের সেই মহাপরীক্ষা এবং মাবুদের দেখানো অলৌকিক চিহ্ন এবং তাঁর বড় বড় কুদরতি তোমরা নিজেদের চোখেই দেখেছ।"},{"v":4,"ve":4,"vl":"4","bn":"কিন্তু তোমরা মাবুদের কাছ থেকে আজ পর্যন্ত সেগুলো বুঝবার মন, দেখবার চোখ ও শুনবার কান পাও নি।"},{"v":5,"ve":5,"vl":"5","bn":"চল্লিশ বছর মরুভূমির মধ্য দিয়ে মাবুদই তোমাদের চালিয়ে নিয়ে এসেছেন। এর মধ্যে তোমাদের গায়ের কাপড় এবং জুতা নষ্ট হয়ে যায় নি।"},{"v":6,"ve":6,"vl":"6","bn":"রুটি, আংগুর-রস কিংবা অন্য কোন মদানো রস তোমরা খেতে পাও নি। মাবুদই তা করেছেন যাতে তোমরা বুঝতে পার যে, তিনিই তোমাদের মাবুদ আল্লাহ্‌।"},{"v":7,"ve":7,"vl":"7","bn":"“তোমরা এই জায়গায় পৌঁছালে পর হিষ্‌বোনের বাদশাহ্‌ সীহোন ও বাশনের বাদশাহ্‌ উজ আমাদের সংগে যুদ্ধ করবার জন্য বের হয়ে এসেছিলেন, কিন্তু আমরা তাঁদের হারিয়ে দিয়েছি।"},{"v":8,"ve":8,"vl":"8","bn":"আমরা তাঁদের দেশ নিয়ে সম্পত্তি হিসাবে তা রূবেণীয়, গাদীয় ও মানশা-গোষ্ঠীর অর্ধেক লোককে দিয়েছি।"},{"v":9,"ve":9,"vl":"9","bn":"সেইজন্য তোমরা এই ব্যবস্থার সব হুকুমগুলো যত্নের সংগে মেনে চলবে যাতে সব কাজেই তোমাদের উন্নতি হয়।"},{"v":10,"ve":10,"vl":"10","bn":"“তোমাদের মাবুদ আল্লাহ্‌র সামনে আজ তোমরা সবাই এসে দাঁড়িয়েছ- দাঁড়িয়েছে তোমাদের সর্দারেরা ও প্রধানেরা, তোমাদের বৃদ্ধ নেতারা ও কর্মচারীরা এবং অন্যান্য সব বনি-ইসরাইলরা।"},{"v":11,"ve":11,"vl":"11","bn":"তোমাদের সংগে রয়েছে তোমাদের ছেলেমেয়ে ও স্ত্রীলোকেরা; আর রয়েছে তোমাদের ছাউনিতে বাস-করা অন্য জাতির লোকেরা যারা তোমাদের কাঠ কাটে ও পানি তোলে।"},{"v":12,"ve":12,"vl":"12","bn":"তোমাদের মাবুদ আল্লাহ্‌ তোমাদের জন্য আজ নিশ্চয়তার কসম খেয়ে যে ব্যবস্থা স্থাপন করেছেন সেই কসম ও ব্যবস্থা মেনে নেবার জন্য তোমরা এখানে এসে দাঁড়িয়েছ।"},{"v":13,"ve":13,"vl":"13","bn":"মাবুদ আজ তা স্থাপন করছেন যাতে তোমাদের পূর্বপুরুষ ইব্রাহিম, ইসহাক ও ইয়াকুবের কাছে খাওয়া কসম এবং তোমাদের কাছে করা ওয়াদা অনুসারে তিনি তোমাদের আল্লাহ্‌ হতে পারেন এবং আজকের দিনে পাকাপাকি ভাবে তোমাদের তাঁর নিজের লোক করে নিতে পারেন।"},{"v":14,"ve":15,"vl":"14-15","bn":"আমাদের মাবুদ আল্লাহ্‌র সামনে এসে আজ যারা দাঁড়িয়েছে কেবল তাদের জন্যই যে আমি নিশ্চয়তার কসম খাওয়া এই ব্যবস্থার কথা ঘোষণা করছি তা নয়, কিন্তু যাদের এখনও জন্ম হয় নি তাদের জন্যও করছি।"},{"v":16,"ve":16,"vl":"16","bn":"“তোমরা নিজেরাই জান, মিসর দেশে আমরা কি রকম জীবন কাটিয়েছি এবং কিভাবে বিভিন্ন দেশের মধ্য দিয়ে এখানে এসে পৌঁছেছি।"},{"v":17,"ve":17,"vl":"17","bn":"কাঠ, পাথর, সোনা ও রূপার তৈরী জঘন্য মূর্তি ও প্রতিমা তোমরা ঐ সব লোকদের মধ্যে দেখেছ।"},{"v":18,"ve":18,"vl":"18","bn":"তোমরা দেখে নাও যেন তোমাদের মধ্যে আজ এমন কোন পুরুষ বা স্ত্রীলোক কিংবা কোন বংশ বা গোষ্ঠী না থাকে যার অন্তর তোমাদের মাবুদ আল্লাহ্‌কে ফেলে ঐ সব জাতির দেব-দেবীর পূজা করতে আগ্রহী। যদি সেই রকম কেউ থাকে তবে তোমাদের মধ্যে সে হবে এমন একটা শিকড়ের মত যা পরে বিষাক্ত তেতো গাছ হয়ে উঠবে।"},{"v":19,"ve":19,"vl":"19","bn":"এই রকম লোক এই কসম খাওয়া কথাগুলো শুনবার সময় যদি নিজেকে ভাগ্যবান বলে মনে করে এবং মনে মনে ভাবে, নিজের ইচ্ছামত চলতে থাকলেও সে নিরাপদে থাকবে, তাহলে তোমাদের সকলের উপরেই সে সর্বনাশ ডেকে আনবে।"},{"v":20,"ve":20,"vl":"20","bn":"মাবুদ কখনও তাকে মাফ করতে রাজী হবেন না। সেই লোকের বিরুদ্ধে তাঁর রাগ জ্বলে উঠবে আর তাঁর অন্তরে তাঁর পাওনা এবাদতের আগ্রহ জেগে উঠবে। এই কিতাবে যে সব বদদোয়ার কথা লেখা আছে তা সবই তার উপর পড়বে। মাবুদ দুনিয়া থেকে তার নাম মুছে ফেলবেন।"},{"v":21,"ve":21,"vl":"21","bn":"তিনি বনি-ইসরাইলদের সমস্ত গোষ্ঠীর মধ্য থেকে দুঃখকষ্টের জন্য তাকেই বেছে নেবেন, আর তিনি এই তৌরাত কিতাবে লেখা ব্যবস্থার মধ্যে যে সব বদদোয়ার কথা বলা হয়েছে সেই কথা অনুসারে তা করবেন।"},{"v":22,"ve":22,"vl":"22","bn":"“এইভাবে এই দেশের উপর যে সব গজব নেমে আসবে এবং মাবুদ যে সব রোগ দেশের উপর পাঠিয়ে দেবেন সেই বিষয়ে তোমাদের বংশধরেরা আর দূর দেশ থেকে আসা বিদেশীরা তোমাদের জিজ্ঞাসা করবে।"},{"v":23,"ve":23,"vl":"23","bn":"গোটা দেশটা লবণ আর গন্ধকে পুড়ে পড়ে থাকবে। তাতে কিছুই বোনা হবে না, কিছুই গজাবে না আর কোন ঘাস বা ঝোপ-ঝাড় তার উপর থাকবে না। এই দেশের অবস্থা হবে সাদুম, আমুরা, অদ্‌মা ও সবোয়িমের মত, যা মাবুদ তাঁর ভয়ংকর রাগে জ্বলে উঠে ধ্বংস করে দিয়েছিলেন।"},{"v":24,"ve":24,"vl":"24","bn":"তা দেখে অন্য সব জাতি জিজ্ঞাসা করবে, ‘মাবুদ কেন এই দেশটার এই দশা করেছেন? কেন তাঁর এই ভয়ংকর জ্বলন্ত রাগ?’"},{"v":25,"ve":25,"vl":"25","bn":"“এর জবাব হবে, ‘কারণ এই জাতি তাদের পূর্বপুরুষদের মাবুদ আল্লাহ্‌র ব্যবস্থা ত্যাগ করেছে, যে ব্যবস্থা মিসর দেশ থেকে তাদের বের করে আনবার পর তিনি তাদের জন্য স্থাপন করেছিলেন।"},{"v":26,"ve":26,"vl":"26","bn":"তারা তাঁকে ফেলে তাদের কাছে নতুন দেব-দেবীর পূজা করেছে ও তাদের সামনে মাথা নীচু করেছে, যাদের পূজা করবার নির্দেশ মাবুদ দেন নি।"},{"v":27,"ve":27,"vl":"27","bn":"সেইজন্যই মাবুদের রাগ এই দেশের উপর জ্বলে উঠেছে আর তিনি এই কিতাবে লেখা সব বদদোয়া এই দেশের উপর ঢেলে দিয়েছেন।"},{"v":28,"ve":28,"vl":"28","bn":"ভীষণ গজবে, ভয়ংকর জ্বলন্ত রাগে, তিনি দেশ থেকে তাদের উপ্‌ড়ে নিয়ে অন্য দেশে ছুঁড়ে ফেলে দিয়েছেন, আর আজও তারা সেখানেই আছে।’"},{"v":29,"ve":29,"vl":"29","bn":"“গোপন সব কিছু আমাদের মাবুদ আল্লাহ্‌র ব্যাপার, কিন্তু প্রকাশিত সব কিছু চিরকালের জন্য আমাদের ও আমাদের সন্তানদের, যেন এই শরীয়তের সমস্ত কথা আমরা পালন করে চলতে পারি।"}],"30":[{"heading":"মাবুদের কাছে ফিরে আসবার ফল","v":1,"ve":1,"vl":"1","bn":"“আমি তোমাদের সামনে যে দোয়া ও বদদোয়া তুলে ধরলাম তা সবই তোমাদের উপর আসবে। তারপর তোমাদের মাবুদ আল্লাহ্‌ যে সব জাতির মধ্যে তোমাদের ছড়িয়ে দেবেন তাদের মধ্যে বাস করবার সময় এই সব কথায় তোমরা মন দেবে।"},{"v":2,"ve":2,"vl":"2","bn":"সেই সময় যখন তোমরা ও তোমাদের সন্তানেরা তোমাদের মাবুদ আল্লাহ্‌র কাছে ফিরে আসবে এবং আজ আমি তোমাদের যে সব হুকুম দিচ্ছি তা পালন করে মনেপ্রাণে তাঁর ইচ্ছামত চলবে,"},{"v":3,"ve":3,"vl":"3","bn":"তখন মাবুদ বন্দীদশা থেকে মুক্ত করে তোমাদের ফিরিয়ে আনবেন। তিনি তোমাদের প্রতি মমতা করবেন এবং যে সব জাতিদের মধ্যে তোমাদের ছড়িয়ে দেবেন তাদের মধ্য থেকে তিনি আবার তোমাদের কুড়িয়ে আনবেন।"},{"v":4,"ve":4,"vl":"4","bn":"আসমানের শেষ সীমানায়ও যদি তোমাদের ফেলে দেওয়া হয় সেখান থেকেও তোমাদের মাবুদ আল্লাহ্‌ তোমাদের কুড়িয়ে আনবেন।"},{"v":5,"ve":5,"vl":"5","bn":"তোমাদের পূর্বপুরুষদের দেশেই তিনি তোমাদের ফিরিয়ে আনবেন আর তোমরা তা আবার দখল করবে। তিনি তোমাদের অনেক উন্নতি করবেন এবং তোমাদের পূর্বপুরুষদের চেয়েও তোমাদের লোকসংখ্যা বাড়িয়ে দেবেন।"},{"v":6,"ve":6,"vl":"6","bn":"তোমরা যাতে তোমাদের সমস্ত মনপ্রাণ দিয়ে তাঁকে মহব্বত করে বেঁচে থাক সেইজন্য তিনি তোমাদের ও তোমাদের বংশধরদের অন্তরের খৎনা করাবেন।"},{"v":7,"ve":7,"vl":"7","bn":"এই সব বদদোয়া তোমাদের মাবুদ আল্লাহ্‌ তোমাদের শত্রুদের উপর আনবেন যারা তোমাদের ঘৃণা ও জুলুম করবে।"},{"v":8,"ve":8,"vl":"8","bn":"তখন তোমরা আবার মাবুদের বাধ্য হয়ে চলবে আর তাঁর যে সব হুকুম আজ আমি তোমাদের দিচ্ছি তা মেনে চলবে।"},{"v":9,"ve":9,"vl":"9","bn":"“তখন তোমাদের মাবুদ আল্লাহ্‌ সব দিক থেকে তোমাদের উন্নতি করবেন। তিনি তোমাদের কাজকর্মে দোয়া করবেন এবং তোমাদের সন্তানের সংখ্যা, পশুর বাচ্চা এবং জমির ফসল বাড়িয়ে দেবেন। তোমাদের পূর্বপুরুষদের উপর তাঁর যে আনন্দ ছিল তোমাদের উপর আবার সেই আনন্দ নিয়ে তিনি তোমাদের উন্নতি করবেন-"},{"v":10,"ve":10,"vl":"10","bn":"অবশ্য যদি তোমরা তোমাদের মাবুদ আল্লাহ্‌র বাধ্য হয়ে এই তৌরাত কিতাবে লেখা তাঁর সব হুকুম ও নিয়ম পালন কর আর মনেপ্রাণে তোমাদের মাবুদ আল্লাহ্‌র দিকে ফেরো।"},{"heading":"জীবন অথবা মৃত্যু","v":11,"ve":11,"vl":"11","bn":"“আজ আমি তোমাদের যে হুকুম দিচ্ছি তা পালন করা তোমাদের পক্ষে তেমন শক্ত নয় কিংবা এই হুকুম তোমাদের নাগালের বাইরেও নয়।"},{"v":12,"ve":12,"vl":"12","bn":"এই হুকুম বেহেশতে তুলে রাখা কোন জিনিস নয় যে, তোমরা বলবে, ‘কে বেহেশতে গিয়ে তা এনে আমাদের শোনাবে যাতে আমরা তা পালন করতে পারি?’"},{"v":13,"ve":13,"vl":"13","bn":"এটা সমুদ্রের ওপারের কোন জিনিসও নয় যে, তোমরা বলবে, ‘কে সমুদ্র পার হয়ে গিয়ে তা এনে আমাদের শোনাবে যাতে আমরা তা পালন করতে পারি?’"},{"v":14,"ve":14,"vl":"14","bn":"মাবুদের কথা তোমাদের সংগেই রয়েছে; রয়েছে তোমাদের মুখে ও দিলে যাতে তোমরা তা পালন করতে পার।"},{"v":15,"ve":15,"vl":"15","bn":"“দেখ, আজ আমি তোমাদের সামনে যা তুলে ধরছি তা হল জীবন ও উন্নতি কিংবা মৃত্যু ও দুঃখকষ্ট।"},{"v":16,"ve":16,"vl":"16","bn":"আজ তোমাদের কাছে আমার হুকুম এই যে, তোমরা তোমাদের মাবুদ আল্লাহ্‌কে মহব্বত করবে, তাঁর পথে চলবে এবং তাঁর হুকুম, নিয়ম ও নির্দেশ মেনে চলবে। তাহলে তোমরা বাঁচবে এবং সংখ্যায় বেড়ে উঠবে, আর যে দেশ তোমরা দখল করবার জন্য যাচ্ছ সেখানে তোমাদের মাবুদ আল্লাহ্‌ তোমাদের দোয়া করবেন।"},{"v":17,"ve":17,"vl":"17","bn":"“কিন্তু যদি তোমাদের অন্তর তাঁর কাছ থেকে সরে যায় এবং তোমরা তাঁর অবাধ্য হও আর যদি তোমরা দেব-দেবীর পূজার টানে তাদের সেজদা কর,"},{"v":18,"ve":18,"vl":"18","bn":"তবে আজ আমি তোমাদের বলে দিচ্ছি যে, তোমরা নিশ্চয়ই ধ্বংস হয়ে যাবে। জর্ডান নদী পার হয়ে যে দেশ তোমরা দখল করতে যাচ্ছ সেখানে তোমরা বেশী দিন বেঁচে থাকবে না।"},{"v":19,"ve":20,"vl":"19-20","bn":"“তোমাদের বিরুদ্ধে আসমান ও জমীনকে সাক্ষী রেখে আমি বলছি যে, আজ আমি তোমাদের সামনে জীবন কিংবা মৃত্যু এবং দোয়া কিংবা বদদোয়া তুলে ধরলাম। তোমরা জীবনকে বেছে নাও, যেন তোমরা ও তোমাদের ছেলেমেয়েরা বেঁচে থাক ও তোমাদের মাবুদ আল্লাহ্‌কে মহব্বত কর, তাঁর কথা শোন এবং তাঁকে আঁক্‌ড়ে ধরে রাখ, কারণ এগুলোর মধ্যেই রয়েছে তোমাদের জীবন। যে দেশ দেবার কসম তিনি তোমাদের পূর্বপুরুষ ইব্রাহিম, ইসহাক ও ইয়াকুবের কাছে খেয়েছিলেন সেখানে এগুলোর মধ্যেই রয়েছে তোমাদের আয়ু।”"}],"31":[{"heading":"হযরত মূসা (আঃ)-এর দায়িত্ব হস্তান্তর","v":1,"ve":1,"vl":"1","bn":"পরে মূসা সমস্ত বনি-ইসরাইলদের বললেন,"},{"v":2,"ve":2,"vl":"2","bn":"“আমার বয়স একশো বিশ বছর হয়ে গেছে। আমার কাজ আর আমি করতে পারছি না। মাবুদও আমাকে বলেছেন যে, জর্ডান নদী পার হয়ে যাওয়া আমার হবে না।"},{"v":3,"ve":3,"vl":"3","bn":"তোমাদের মাবুদ আল্লাহ্‌ নিজেই নদী পার হয়ে তোমাদের আগে আগে যাবেন। তোমাদের সামনে থেকে ঐ সব জাতিদের তিনিই ধ্বংস করে দেবেন আর তোমরা তাদের দেশ দখল করে নেবে। মাবুদের কথা অনুসারে ইউসাই নদী পার হয়ে তোমাদের আগে আগে যাবে।"},{"v":4,"ve":4,"vl":"4","bn":"আমোরীয়দের বাদশাহ্‌ সীহোন এবং উজ আর তাঁদের দেশ যেমন মাবুদ ধ্বংস করে দিয়েছিলেন তেমনি করে তিনি সেই সব জাতিও ধ্বংস করে ফেলবেন।"},{"v":5,"ve":5,"vl":"5","bn":"তাদের তিনি তোমাদের হাতে তুলে দেবেন আর আমি তাদের প্রতি যা করবার হুকুম দিয়েছি তোমরা তাদের প্রতি তা-ই করবে।"},{"v":6,"ve":6,"vl":"6","bn":"তোমরা শক্ত হও ও মনে সাহস আন। তাদের দেখে তোমরা ভয় পেয়ো না কিংবা কেঁপে উঠো না, কারণ তোমাদের মাবুদ আল্লাহ্‌ই তোমাদের সংগে যাবেন। তিনি কখনও তোমাদের ছেড়ে যাবেন না বা ত্যাগ করবেন না।”"},{"v":7,"ve":7,"vl":"7","bn":"এর পর মূসা ইউসাকে ডাকলেন এবং সমস্ত বনি-ইসরাইলদের সামনে তাঁকে বললেন, “তুমি শক্তিশালী হও ও মনে সাহস আন, কারণ তোমাকেই এই লোকদের সংগে সেই দেশে যেতে হবে যে দেশটা এদের দেবার কসম মাবুদ এদের পূর্বপুরুষদের কাছে খেয়েছিলেন। তোমাকেই সেই দেশটা সম্পত্তি হিসাবে এদের মধ্যে ভাগ করে দিতে হবে।"},{"v":8,"ve":8,"vl":"8","bn":"মাবুদ নিজেই তোমার আগে আগে যাবেন এবং তোমার সংগে থাকবেন। তিনি কখনও তোমাকে ছেড়ে যাবেন না বা ত্যাগ করবেন না। তুমি ভয় কোরো না, উৎসাহ হারায়ো না।”"},{"heading":"তৌরাত শরীফ তেলাওয়াতের বিশেষ নিয়ম","v":9,"ve":9,"vl":"9","bn":"লেবি-গোষ্ঠীর ইমামেরা, যাঁরা মাবুদের সাক্ষ্য-সিন্দুকটি বয়ে নিয়ে যেতেন, মূসা সমস্ত শরীয়ত লিখে তাঁদের হাতে ও বনি-ইসরাইলদের বৃদ্ধ নেতাদের হাতে দিলেন।"},{"v":10,"ve":11,"vl":"10-11","bn":"তিনি তাঁদের হুকুম দিলেন, “প্রত্যেক সপ্তম বছরে, অর্থাৎ ঋণ মাফের বছরে যখন কুঁড়ে-ঘরের ঈদের সময় আসবে এবং সমস্ত বনি-ইসরাইল তোমাদের মাবুদ আল্লাহ্‌র সামনে উপস্থিত হবার জন্য তাঁর বেছে নেওয়া জায়গায় যাবে তখন তোমরা এই শরীয়ত তাদের তেলাওয়াত করে শোনাবে।"},{"v":12,"ve":12,"vl":"12","bn":"পুরুষ, স্ত্রীলোক, ছেলেমেয়ে এবং তোমাদের বিভিন্ন গ্রাম ও শহরের ভিন্ন জাতির লোকদের ডেকে তোমরা একসংগে জমায়েত করবে, যাতে তারা তা শুনতে পারে এবং তোমাদের মাবুদ আল্লাহ্‌কে ভয় করতে শেখে আর এই শরীয়তের সমস্ত কথা যত্নের সংগে পালন করে।"},{"v":13,"ve":13,"vl":"13","bn":"এইভাবে তাদের ছেলেমেয়েরা, যাদের এই শরীয়তের কথা জানা থাকবে না, তারাও তা শুনতে পাবে এবং এই শিক্ষা পাবে যে, জর্ডান পার হয়ে যে দেশটা তোমরা দখল করতে যাচ্ছ সেখানে সারা জীবন তোমাদের মাবুদ আল্লাহ্‌কে তাদের ভয় করতে হবে।”"},{"heading":"বিদ্রোহের ভবিষ্যদ্বাণী","v":14,"ve":14,"vl":"14","bn":"এর পর মাবুদ মূসাকে বললেন, “তোমার মৃত্যুর দিন কাছে এসে গেছে। ইউসাকে ডেকে নিয়ে তুমি মিলন-তাম্বুতে যাও। সেখানে আমি তাকে তার কাজের ভার দেব।” কাজেই মূসা ও ইউসা মিলন-তাম্বুতে মাবুদের সামনে উপস্থিত হলেন।"},{"v":15,"ve":15,"vl":"15","bn":"তখন মাবুদ মেঘের থামের মধ্যে সেই তাম্বুতে উপস্থিত হলেন এবং সেই থামটি তাম্বুর দরজার কাছে গিয়ে দাঁড়াল।"},{"v":16,"ve":16,"vl":"16","bn":"মাবুদ মূসাকে বললেন, “তুমি তোমার পূর্বপুরুষদের কাছে বিশ্রাম করতে যাচ্ছ, কিন্তু এই লোকেরা যে দেশে ঢুকতে যাচ্ছে সেখানে খুব শীঘ্রই তারা আমার প্রতি বেঈমানী করে সেখানকার দেবপূজায় নিজেদের বিকিয়ে দেবে। তারা আমাকে ত্যাগ করবে এবং আমি তাদের জন্য যে ব্যবস্থা স্থাপন করেছি তারা তার অগ্রাহ্য করবে।"},{"v":17,"ve":17,"vl":"17","bn":"যেদিন তারা তা করবে সেই দিন রাগে আমি তাদের ত্যাগ করব। আমি তাদের কাছ থেকে আমার মুখ ফিরিয়ে নেব আর তারা ধ্বংস হয়ে যাবে। তখন তাদের উপর অনেক বিপদ ও দুঃখ-কষ্ট নেমে আসবে। সেই দিন তারা বলবে, ‘আমাদের আল্লাহ্‌ আমাদের সংগে নেই বলেই আমাদের উপর এই সব বিপদ এসেছে।’"},{"v":18,"ve":18,"vl":"18","bn":"তারা দেব-দেবীদের দিকে ফিরে যে সব খারাপ কাজ করবে সেইজন্য আমি নিশ্চয়ই সেই দিন আমার মুখ ফিরিয়ে নেব।"},{"v":19,"ve":19,"vl":"19","bn":"“তোমরা এখন এই গজলটি লিখে নাও। এটা বনি-ইসরাইলদের শিখাবে এবং তাদের দিয়ে গাওয়াবে, যাতে তাদের বিরুদ্ধে এটা আমার পক্ষে একটা সাক্ষী হয়ে থাকে।"},{"v":20,"ve":20,"vl":"20","bn":"তাদের পূর্বপুরুষদের কাছে আমার কসম খাওয়া সেই দুধ আর মধুতে ভরা দেশে যখন আমি তাদের নিয়ে যাব আর যখন তারা পেট ভরে খেয়ে সুখে থাকবে তখন তারা আমাকে তুচ্ছ করে আমার ব্যবস্থার অগ্রাহ্য করে দেব-দেবীর পিছনে গিয়ে তাদের পূজা করবে।"},{"v":21,"ve":21,"vl":"21","bn":"ফলে তাদের উপর যখন অনেক বিপদ ও দুঃখ-কষ্ট নেমে আসবে তখন এই গজলটাই তাদের বিরুদ্ধে সাক্ষী হয়ে দাঁড়াবে, কারণ তাদের বংশধরেরা গজলটি ভুলে যাবে না। আমার কসম খেয়ে ওয়াদা করা দেশে তাদের নিয়ে যাওয়ার আগেই আমি জানি যে, তাদের অন্তরে এখন কি রয়েছে।”"},{"v":22,"ve":22,"vl":"22","bn":"মূসা ঐ দিন গজলটি লিখে বনি-ইসরাইলদের শিখিয়েছিলেন।"},{"v":23,"ve":23,"vl":"23","bn":"নূনের ছেলে ইউসাকে মাবুদ এই হুকুম দিলেন, “তুমি শক্তিশালী হও ও মনে সাহস আন। যে দেশ দেবার ওয়াদা আমি কসম খেয়ে বনি-ইসরাইলদের কাছে করেছিলাম সেখানে তুমিই তাদের নিয়ে যাবে। আমি নিজেই তোমার সংগে থাকব।”"},{"v":24,"ve":24,"vl":"24","bn":"মূসা এই শরীয়ত আগাগোড়া একটি কিতাবে লিখে নিলেন।"},{"v":25,"ve":25,"vl":"25","bn":"তারপর মাবুদের সাক্ষ্য-সিন্দুক বহনকারী লেবীয়দের তিনি বললেন,"},{"v":26,"ve":26,"vl":"26","bn":"“এই তৌরাত কিতাব নিয়ে তোমরা তোমাদের মাবুদ আল্লাহ্‌র সাক্ষ্য-সিন্দুকের পাশে রাখ। এটা বনি-ইসরাইলদের বিরুদ্ধে সাক্ষী হয়ে সেখানে থাকবে।"},{"v":27,"ve":27,"vl":"27","bn":"তোমরা যে কেমন একগুঁয়ে ও বিদ্রোহী তা আমার জানা আছে। আমি তোমাদের মধ্যে বেঁচে থাকতেই যখন তোমরা মাবুদের বিরুদ্ধে বিদ্রোহ করেছ তখন আমি মারা যাওয়ার পরে আরও কত বেশী করেই না তা করবে।"},{"v":28,"ve":28,"vl":"28","bn":"তোমরা তোমাদের গোষ্ঠীর বৃদ্ধ নেতাদের ও কর্মচারীদের সবাইকে আমার সামনে জমায়েত কর। আমি তাদের এই সব কথা বলতে চাই আর আসমান ও জমীনকে তাদের বিরুদ্ধে সাক্ষী রেখে যেতে চাই।"},{"v":29,"ve":29,"vl":"29","bn":"আমি জানি যে, আমার মৃত্যুর পরে তোমরা একেবারেই খারাপ হয়ে যাবে এবং যে পথে আমি তোমাদের চলবার নির্দেশ দিয়েছি তোমরা তা থেকে সরে যাবে। ভবিষ্যতে তোমাদের উপর বিপদ নেমে আসবে, কারণ মাবুদের চোখে যা খারাপ তোমরা তা করবে এবং তোমাদের নিজের হাতে গড়া মূর্তি দিয়ে তোমরা তাঁকে রাগিয়ে তুলবে।”"},{"heading":"হযরত মূসা (আঃ)-এর গজল","v":30,"ve":30,"vl":"30","bn":"তারপর মূসা এই গজলের কথাগুলো প্রথম থেকে শেষ পর্যন্ত সমস্ত বনি-ইসরাইলদের শোনালেন:"}],"32":[{"v":1,"ve":1,"vl":"1","bn":"হে আসমান, আমার কথায় কান দাও; হে দুনিয়া, আমার মুখের কথা শোন।"},{"v":2,"ve":2,"vl":"2","bn":"আমার শিক্ষা বৃষ্টির মত করে ঝরে পড়ুক, আমার কথা শিশিরের মত করে নেমে আসুক। হালকা এক পস্‌লা বৃষ্টির মত করে তা নতুন ঘাসের উপর ঝরে পড়ুক, আর গাছ-গাছড়ার উপর ভারী বৃষ্টি হয়ে তা পড়ুক।"},{"v":3,"ve":3,"vl":"3","bn":"আমি মাবুদের নাম ঘোষণা করব। তোমরা আমাদের আল্লাহ্‌র মহিমা-কাওয়ালী গাও।"},{"v":4,"ve":4,"vl":"4","bn":"তিনিই আশ্রয়-পাহাড়, তাঁর কাজ নিখুঁত; তাঁর সমস্ত পথ ন্যায়ের পথ। তিনি নির্ভরযোগ্য আল্লাহ্‌, তিনি কোন অন্যায় করেন না; তিনি ন্যায়বান ও সৎ।"},{"v":5,"ve":5,"vl":"5","bn":"তাঁর প্রতি তাঁর বান্দারা জঘন্য ব্যবহার করেছে। তাদের অন্তরের কলংকের জন্য তারা আর তাঁর সন্তান নয়। তারা বেঈমান, তাদের মন সরল নয়।"},{"v":6,"ve":6,"vl":"6","bn":"হে অবুঝ, বুদ্ধিহীন জাতি! এমনি করেই কি তোমরা মাবুদকে শোধ দেবে? তিনি কি তোমাদের পিতা ও সৃষ্টিকর্তা নন? তিনিই তো তোমাদের সৃষ্টি করেছেন; তিনিই জাতি হিসাবে তোমাদের স্থাপন করেছেন।"},{"v":7,"ve":7,"vl":"7","bn":"সেই পুরানো দিনগুলোর কথা মনে কর; তোমাদের অনেক দিন আগেকার পূর্বপুরুষদের কথা ভেবে দেখ। সেই সব দিনের কথা তোমাদের পিতাদের জিজ্ঞাসা কর, তাঁরা তোমাদের বলবেন; বুড়ো লোকদের জিজ্ঞাসা কর, তাঁরা তোমাদের বুঝিয়ে বলবেন।"},{"v":8,"ve":8,"vl":"8","bn":"আল্লাহ্‌তা’লা যখন বিভিন্ন জাতিকে সম্পত্তি ভাগ করে দিলেন, আর মানুষকে ভিন্ন ভিন্ন জাতিতে ভাগ করলেন, তখন ইসরাইল জাতির লোকসংখ্যা মনে রেখে তিনি অন্য জাতিদের সীমানা ঠিক করে দিলেন।"},{"v":9,"ve":9,"vl":"9","bn":"মাবুদের পাওনা ভাগই হল তাঁর বান্দারা; ইয়াকুব, হ্যাঁ, ইসরাইল জাতি হল তাঁর পাওনা সম্পত্তি।"},{"v":10,"ve":10,"vl":"10","bn":"তিনি তাকে এক মরুভূমিতে পেলেন, পেলেন গর্জন্তভরা এক নির্জন জায়গায়। তিনি তাকে ঘিরে রাখলেন, যত্ন করলেন; তাকে চোখের মণির মত করে পাহারা দিয়ে রাখলেন,"},{"v":11,"ve":11,"vl":"11","bn":"যেমন করে ঈগল পাখী তার বাসায় বাচ্চাদের চঞ্চল করে তোলে, যেমন করে তাদের উপর সে আস্তে আস্তে উড়তে থাকে, যেমন করে তাদের তুলে নেবার জন্য তার ডানা মেলে দেয়, আর যেমন করে তার পাখার উপর তাদের বয়ে নিয়ে যায়।"},{"v":12,"ve":12,"vl":"12","bn":"মাবুদ একাই তাকে চালিয়ে নিয়ে আসলেন, তাঁর সংগে ছিল না কোন দেব-দেবী।"},{"v":13,"ve":13,"vl":"13","bn":"বিজয়ী হিসাবে তাকে তিনি চালিয়ে নিয়ে গেলেন দেশের এক পাহাড় থেকে অন্য পাহাড়ে; তাকে ক্ষেতের ফসল খেতে দিলেন। তিনি তাকে খাওয়ালেন সেই মধু যা পাহাড়ের ফাটলে পাওয়া যায়, আর তাকে শক্ত পাথুরে জমির জলপাইয়ের তেল খাওয়ালেন।"},{"v":14,"ve":14,"vl":"14","bn":"তিনি তাকে খাওয়ালেন গরুর দুধের দই আর ছাগল ও ভেড়ার দুধ, আর খাওয়ালেন মোটাসোটা ভেড়ার বাচ্চার গোশ্‌ত, ছাগলের গোশ্‌ত আর বাশন দেশের পুরুষ ভেড়ার গোশ্‌ত। তিনি তাকে খাওয়ালেন পরিপুষ্ট গম। হে ইসরাইল, তুমি গেঁজে ওঠা আংগুর-রস খেয়েছ।"},{"v":15,"ve":15,"vl":"15","bn":"কিন্তু মোটা হয়ে যিশুরূণ লাথি মারল। হে যিশুরূণ, তুমি অতিরিক্ত খেয়ে ভারী ও মোটা হয়েছ। তারপর সে তার সৃষ্টিকর্তা আল্লাহ্‌কে ত্যাগ করল, আর ছোট করে দেখল তার আশ্রয়-পাহাড়কে।"},{"v":16,"ve":16,"vl":"16","bn":"দেবতা পূজায় তাঁর বান্দারা তাঁর পাওনা এবাদতের আগ্রহে আগুন লাগাল, জঘন্য মূর্তি পূজায় তাঁর রাগ জাগাল।"},{"v":17,"ve":17,"vl":"17","bn":"তারা কোরবানী দিল ভূতদের উদ্দেশে যারা মাবুদ নয়, তারা কোরবানী দিল নতুন দেব-দেবীর উদ্দেশে, যারা মাত্র কিছুদিন আগে দেখা দিয়েছে, যাদের তোমাদের পূর্বপুরুষেরা ভয় করত না।"},{"v":18,"ve":18,"vl":"18","bn":"সেই আশ্রয়-পাহাড় তোমরা অবহেলা করেছ যিনি তোমাদের পিতা; সেই আল্লাহ্‌কে তোমরা ভুলে গেছ যিনি মায়ের মত প্রসব-বেদনার মধ্য দিয়ে তোমাদের দুনিয়াতে এনেছেন।"},{"v":19,"ve":19,"vl":"19","bn":"তা দেখে মাবুদ তাঁর ছেলেমেয়েদের দিক থেকে মুখ ফিরিয়ে নিলেন, কারণ তারা তাঁর রাগ জাগিয়ে তুলেছিল।"},{"v":20,"ve":20,"vl":"20","bn":"তিনি বললেন, “আমি তাদের কাছ থেকে মুখ ফিরিয়ে নেব, শেষে তাদের দশা কি হয় দেখব; কারণ এরা উল্টা পথে চলা জাতি, বেঈমান সন্তান।"},{"v":21,"ve":21,"vl":"21","bn":"আল্লাহ্‌ নয় এমন দেবতার পূজা করে তারা আমার পাওনা এবাদতের আগ্রহে আগুন লাগিয়েছে; অসার মূর্তির পূজা করে তারা আমার রাগ জাগিয়ে তুলেছে। জাতিই নয় এমন জাতির হাতে ফেলে আমিও তাদের অন্তরে আগুন জ্বালাব; একটা অবুঝ জাতির হাতে ফেলে তাদের রাগ জাগাব।"},{"v":22,"ve":22,"vl":"22","bn":"আমার রাগের আগুন জ্বলে উঠেছে; সেই আগুন জ্বলছে কবরের সবচেয়ে নীচু জায়গা পর্যন্ত। সেই আগুন দুনিয়া ও তার সব ফসল খেয়ে ফেলবে আর আগুন লাগাবে সব পাহাড়ের তলায়।"},{"v":23,"ve":23,"vl":"23","bn":"“আমি সমস্ত বিপদ এনে তাদের উপর জড়ো করব; আমার সব তীর আমি তাদেরই উপর শেষ করব।"},{"v":24,"ve":24,"vl":"24","bn":"আমি তাদের উপর দেহ ক্ষয় করা দুর্ভিক্ষ, ধ্বংসকারী মহামারী আর কষ্ট ভরা রোগ পাঠিয়ে দেব। তাদের বিরুদ্ধে আমি বুনো দাঁতাল পশু আর বুকে ভর করে চলা বিষাক্ত সাপ পাঠিয়ে দেব।"},{"v":25,"ve":25,"vl":"25","bn":"শহরের বাইরে তলোয়ারের আঘাতে তাদের সন্তানেরা মারা পড়বে, আর বাড়ীর ভিতরে ভয়ের রাজত্ব চলবে। তাদের সব যুবক-যুবতী, ছোট ছেলেমেয়ে আর বুড়োরা ধ্বংস হয়ে যাবে।"},{"v":26,"ve":26,"vl":"26","bn":"আমি বলেছিলাম, আমি তাদের টুকরা টুকরা করে ফেলব, তাদের কথা মানুষের মন থেকে মুছে ফেলব।"},{"v":27,"ve":27,"vl":"27","bn":"কিন্তু আমি জানতাম এতে শত্রু বড়াই করবে আর না বুঝে বলবে যে, তাদেরই জয় হয়েছে; মাবুদ এই সব কিছুই করেন নি।”"},{"v":28,"ve":28,"vl":"28","bn":"ইসরাইল জাতির মধ্যে ভাল বুদ্ধি দেবার লোক নেই, তাদের বিচারবুদ্ধি বলে কিছু নেই।"},{"v":29,"ve":29,"vl":"29","bn":"বুদ্ধি থাকলে এই কথাটা তারা বুঝত, বুঝত তাদের শেষ দশা কি হবে।"},{"v":30,"ve":30,"vl":"30","bn":"কি করে একজন হাজার জনকে তাড়ায়, কি করে দু’জনকে দেখে দশ হাজার পালায়, যদি না তাদের আশ্রয়-পাহাড় শত্রুদের হাতে তাদের বিকিয়ে দিয়ে থাকেন, যদি না মাবুদ শত্রুদের হাতে তাদের তুলে দিয়ে থাকেন?"},{"v":31,"ve":31,"vl":"31","bn":"শত্রুদের আশ্রয়-পাহাড় আমাদের আশ্রয়-পাহাড়ের মত নয়, এটা আমাদের শত্রুদেরও রায়।"},{"v":32,"ve":32,"vl":"32","bn":"মাবুদ বললেন, “তাদের আংগুর গাছ সাদুমের আংগুর গাছ থেকে আর আমুরার ক্ষেত থেকে এসেছে। তাদের আংগুরে রয়েছে বিষ, তাদের আংগুরের থোকা তেতো।"},{"v":33,"ve":33,"vl":"33","bn":"তাদের আংগুর-রস হল সাপের বিষ, গোখ্‌রা সাপের ভয়ংকর বিষ।"},{"v":34,"ve":34,"vl":"34","bn":"আমার কাছেই তা তোলা আছে, আমার ভাণ্ডার ঘরে সীলমোহর করা আছে।"},{"v":35,"ve":35,"vl":"35","bn":"অন্যায়ের শাস্তি দেবার অধিকার আমারই; যার যা পাওনা আমি তাকে তা-ই দেব। সময় হলেই শত্রুদের পা পিছ্‌লে যাবে; তাদের ধ্বংসের দিন তাদের কাছে এসে গেছে। তাদের জন্য যা ঠিক করে রাখা হয়েছে, তা শীঘ্রই তাদের উপর এসে পড়বে।”"},{"v":36,"ve":36,"vl":"36","bn":"মাবুদ যখন দেখবেন, তাঁর বান্দাদের শক্তি ফুরিয়ে গেছে, গোলাম বা স্বাধীন কারও আর শক্তি নেই, তখন তিনি তাঁর বান্দাদের পক্ষ নেবেন, তাঁর গোলামদের উপর মমতা করবেন।"},{"v":37,"ve":37,"vl":"37","bn":"তিনি তখন বলবেন, “কোথায় এখন তাদের দেব-দেবী? কোথায় তাদের সেই পাহাড় যাঁর কাছে তারা আশ্রয় নিয়েছিল?"},{"v":38,"ve":38,"vl":"38","bn":"কোথায় সেই দেব-দেবী যারা তাদের কোরবানীর পশুর চর্বি খেয়েছিল, খেয়েছিল তাদের ঢালন-কোরবানীর আংগুর-রস? এখন তারা এসে তোমাদের সাহায্য করুক, আর তোমাদের আশ্রয় দিক।"},{"v":39,"ve":39,"vl":"39","bn":"এবার তোমরা ভেবে দেখ যে, আমিই তিনি; আমি ছাড়া আর কোন মাবুদ নেই। মরণ-বাঁচন আমারই হাতে, আমি ক্ষত করেছি, আমিই সুস্থ করব; আমার হাত থেকে বাঁচাতে পারে এমন কেউ নেই।"},{"v":40,"ve":40,"vl":"40","bn":"আমি হাত তুলে কসম খেয়ে বলছি, আমার জীবনের কসম যে,"},{"v":41,"ve":41,"vl":"41","bn":"যখন আমার ঝক্‌ঝকে তলোয়ারে আমি শান দেব, আমার বিচারের রায়কে কাজে লাগাবার জন্য তা হাতে নেব, তখন আমার শত্রুদের আমি শাস্তি দেব, আর যারা আমাকে ঘৃণা করে তাদের যা পাওনা তা তাদের দেব।"},{"v":42,"ve":42,"vl":"42","bn":"মেরে ফেলা আর বন্দী লোকদের রক্ত খাইয়ে আমার তীরগুলোকে আমি মাতাল করে তুলব; আমার তলোয়ার গোশ্‌ত খাবে, লম্বা-চুলওয়ালা শত্রুর মাথার গোশ্‌ত খাবে।”"},{"v":43,"ve":43,"vl":"43","bn":"হে সমস্ত জাতির লোকেরা, তোমরা মাবুদের বান্দাদের সংগে তাঁর প্রশংসা কর, কারণ তিনি তাঁর গোলামদের রক্তের শোধ নেবেন, তাঁর শত্রুদের শাস্তি দেবেন আর তাঁর দেশ ও তাঁর বান্দাদের গুনাহ্‌ ঢাকবার ব্যবস্থা করবেন।"},{"v":44,"ve":44,"vl":"44","bn":"মূসা আর নূনের ছেলে ইউসা গিয়ে এই গজলের সব কথা লোকদের শোনালেন।"},{"v":45,"ve":46,"vl":"45-46","bn":"সমস্ত বনি-ইসরাইলদের কাছে মূসা তা বলা শেষ করে তাদের বললেন, “যে কথাগুলো তোমাদের বিরুদ্ধে সাক্ষী হয়ে থাকবার জন্য আজ আমি তোমাদের বললাম তা তোমরা মনে গেঁথে রাখ যাতে এই শরীয়তের সব কথা যত্নের সংগে পালন করবার জন্য তোমাদের ছেলেমেয়েদের হুকুম দিতে পার।"},{"v":47,"ve":47,"vl":"47","bn":"তোমাদের জন্য এগুলো বাজে কথা নয়, এগুলো তোমাদের জীবন। জর্ডান নদী পার হয়ে তোমরা যে দেশ দখল করতে যাচ্ছ সেখানে এই কথাগুলো পালন করে তোমরা অনেক দিন বেঁচে থাকতে পারবে।”"},{"heading":"হযরত মূসা (আঃ)-এর ইন্তেকালের কথা","v":48,"ve":48,"vl":"48","bn":"সেই দিনই মাবুদ মূসাকে বললেন,"},{"v":49,"ve":49,"vl":"49","bn":"“তুমি জেরিকোর উল্টা দিকে মোয়াব দেশের অবারীম পাহাড়শ্রেণীর মধ্যে নবো পাহাড়ে গিয়ে ওঠো এবং সম্পত্তি হিসাবে যে কেনান দেশটা আমি বনি-ইসরাইলদের দিচ্ছি তা একবার দেখে নাও।"},{"v":50,"ve":50,"vl":"50","bn":"তোমার ভাই হারুন যেমন হোর পাহাড়ে মারা গিয়ে তার পূর্বপুরুষদের কাছে চলে গেছে তেমনি করে তুমিও নবো পাহাড়ে উঠে মারা যাবে এবং তোমার পূর্বপুরুষদের কাছে চলে যাবে।"},{"v":51,"ve":51,"vl":"51","bn":"এর কারণ হল, সীন মরুভূমিতে কাদেশের মরীবার পানির কাছে বনি-ইসরাইলদের সামনে তোমরা আমার প্রতি অবিশ্বস্ততার কাজ করেছিলে এবং বনি-ইসরাইলদের সামনে আমাকে পবিত্র বলে মান্য কর নি।"},{"v":52,"ve":52,"vl":"52","bn":"সেইজন্য যে দেশটা আমি বনি-ইসরাইলদের দিতে যাচ্ছি তা তুমি কেবল দূর থেকে দেখতে পাবে কিন্তু সেখানে তোমার ঢোকা হবে না।”"}],"33":[{"heading":"বনি-ইসরাইলদের প্রতি হযরত মূসা (আঃ)-এর শেষ দোয়া","v":1,"ve":1,"vl":"1","bn":"আল্লাহ্‌র বান্দা মূসা ইন্তেকাল করবার আগে বনি-ইসরাইলদের এই বলে দোয়া করেছিলেন,"},{"v":2,"ve":2,"vl":"2","bn":"“মাবুদ তুর পাহাড় থেকে আসলেন, তিনি সেয়ীর থেকে তাদের উপর আলো দিলেন; তাঁর আলো পারণ পাহাড় থেকে ছড়িয়ে পড়ল। তিনি লক্ষ লক্ষ পবিত্র ফেরেশতাদের মাঝখান থেকে আসলেন; তাঁর ডান হাতে রয়েছে তাদের জন্য আগুন ভরা আইন।"},{"v":3,"ve":3,"vl":"3","bn":"“সত্যিই তিনি তাঁর নিজের বান্দাদের মহব্বত করেন। পবিত্র ফেরেশতারা তাঁর অধীনে রয়েছেন, তাঁরা সবাই তাঁর পায়ে নত হয়ে আছেন; তাঁরই কাছে তাঁরা হুকুম পান।"},{"v":4,"ve":4,"vl":"4","bn":"আমাদের কাছে মূসা যে শরীয়ত দিয়েছিলেন, সেটাই হল ইয়াকুব-গোষ্ঠীর ধন।"},{"v":5,"ve":5,"vl":"5","bn":"যখন ইসরাইলীয় সর্দারেরা জমায়েত হলেন, তাদের সংগে ইসরাইলীয় সব গোষ্ঠী জমায়েত হল, তখন মাবুদই ছিলেন ইসরাইলের বাদশাহ্‌।”"},{"heading":"বারো গোষ্ঠির প্রতি দোয়া","v":6,"ve":6,"vl":"6","bn":"রূবেণ সম্বন্ধে মূসা বলেছিলেন, “রূবেণকে বাঁচিয়ে রাখ, মৃত্যু তার দূরে রাখ; তার লোকসংখ্যা যেন কম থাকে।”"},{"v":7,"ve":7,"vl":"7","bn":"এহুদা সমন্ধে তিনি বলেছিলেন, “হে মাবুদ, তুমি এহুদার কথা শোন; তার লোকদের মধ্যে তাকে ফিরিয়ে আন। তার নিজের দু’হাত সে যুদ্ধে লাগায়; শত্রুর বিরুদ্ধে তুমি তার সহায় হও।”"},{"v":8,"ve":8,"vl":"8","bn":"লেবি সম্বন্ধে তিনি বলেছিলেন, “তোমার ভক্তের কাছে তোমার তূম্মীম ও ঊরীম আছে; মঃসাতে তুমি তার পরীক্ষা করেছিলে, মরীবার পানির কাছে তার সংগে ঝগড়া করেছিলে।"},{"v":9,"ve":9,"vl":"9","bn":"নিজের পিতা-মাতাকে বড় করে না দেখে, নিজের ভাইদের স্বীকার না করে, নিজের ছেলেমেয়েদের অস্বীকার করে, সে তোমার কালাম পাহারা দিয়েছে আর তোমার ব্যবস্থা রক্ষা করেছে।"},{"v":10,"ve":10,"vl":"10","bn":"তোমার হুকুম সে ইয়াকুবকে শিখায়, আর শরীয়ত শিখায় ইসরাইলকে। সে তোমার সামনে ধূপ জ্বালায়, তোমার কোরবানগাহের উপরে পোড়ানো-কোরবানী দেয়।"},{"v":11,"ve":11,"vl":"11","bn":"হে মাবুদ, তুমি তার সম্পত্তিতে দোয়া কর, তার সব কাজে তুমি খুশী হও। তুমি তার শত্রুর কোমর ভেংগে দাও; যারা তাকে ঘৃণা করে তাদের কোমর ভেংগে দাও, যেন তারা আর দাঁড়াতে না পারে।”"},{"v":12,"ve":12,"vl":"12","bn":"বিন্‌ইয়ামীন সম্বন্ধে তিনি বলেছিলেন, “মাবুদ যাকে মহব্বত করেন সে নিরাপদে তাঁর কাছে থাকবে; তিনি সব সময় তাকে আড়ালে রাখেন; তাঁরই পিঠের উপর তার স্থান।”"},{"v":13,"ve":13,"vl":"13","bn":"ইউসুফ সম্বন্ধে তিনি বলেছিলেন, “মাবুদ তার দেশকে যেন দোয়া করেন আসমানের মহামূল্য শিশির দিয়ে, মাটির নীচের পানি দিয়ে,"},{"v":14,"ve":14,"vl":"14","bn":"সূর্যের সেরা দান দিয়ে, মৌসুমের সেরা ফসল দিয়ে,"},{"v":15,"ve":15,"vl":"15","bn":"পুরানো পাহাড়ের সম্পদ দিয়ে, চিরকালের পাহাড়ের ধন দিয়ে,"},{"v":16,"ve":16,"vl":"16","bn":"ভরা দুনিয়ার ভাল ভাল জিনিস দিয়ে, আর জ্বলন্ত ঝোপে যিনি ছিলেন তাঁর রহমত দিয়ে। ইউসুফের মাথায় এই সব দোয়া ঝরে পড়ুক; ভাইদের মধ্যে যে মহৎ তাঁরই মাথায় ঝরে পড়ুক এই সব দোয়া।"},{"v":17,"ve":17,"vl":"17","bn":"তার মহিমা প্রথমে জন্মানো ষাঁড়ের মত, তার মাথায় রয়েছে বুনো ষাঁড়ের শিং। তা দিয়ে সে গুঁতাবে দুনিয়ার সব জাতিকে, এমন কি, এর শেষ সীমানার জাতিকেও। এই রকমই হবে আফরাহীমের লক্ষ লক্ষ আর মানশার হাজার হাজার লোক।”"},{"v":18,"ve":18,"vl":"18","bn":"সবূলূন সম্বন্ধে তিনি বলেছিলেন, “সবূলূন বাইরের কাজে খুশী হোক, আর ইষাখর খুশী হোক ঘরের কাজে।"},{"v":19,"ve":19,"vl":"19","bn":"লোকদের তারা পাহাড়ের ধারে ডাকবে; সেখানে যোগ্য মনোভাব নিয়ে তারা পশু-কোরবানী দেবে। সাগর থেকে তারা তুলবে সাগরের ধন, আর বালি থেকে তুলে আনবে বালির তলার ধন।”"},{"v":20,"ve":20,"vl":"20","bn":"গাদ সম্বন্ধে তিনি বলেছিলেন, “ধন্য তিনি, যিনি গাদের রাজ্যের সীমা বাড়াবেন। সে সিংহের মত বসবে আর শত্রুর মাথা ও হাত ছিঁড়বে।"},{"v":21,"ve":21,"vl":"21","bn":"সব জায়গার সেরা জায়গা সে বেছে নিয়েছে; নেতার যোগ্য পাওনা তার জন্য রাখা আছে। যুদ্ধে জমায়েত হওয়া সর্দারদের মধ্যে সে-ই মাবুদের ন্যায়-ভরা হুকুম পালন করেছে, পালন করেছে ইসরাইলকে দেওয়া মাবুদের নিয়ম।”"},{"v":22,"ve":22,"vl":"22","bn":"দান সম্বন্ধে তিনি বলেছিলেন, “সে যেন বাশন থেকে লাফিয়ে আসা সিংহের বাচ্চা।”"},{"v":23,"ve":23,"vl":"23","bn":"নপ্তালি সম্বন্ধে তিনি বলেছিলেন, “নপ্তালি মাবুদের মমতায় পূর্ণ; তাঁরই দোয়ায় সে পূর্ণ হয়ে উঠেছে। তুমি তোমার সীমানার মধ্যে নিয়ে এস গালীল সাগর ও তার দক্ষিণের দেশ।”"},{"v":24,"ve":24,"vl":"24","bn":"আশের সম্বন্ধে তিনি বলেছিলেন, “আশের অন্যের চেয়ে বেশী দোয়া পাবে; সে যেন ভাইদের প্রিয় হয়, তার পা দু’খানা যেন জলপাই তেলের মধ্যে ডুবে থাকে।"},{"v":25,"ve":25,"vl":"25","bn":"লোহা আর ব্রোঞ্জের আগল দিয়ে তার সদর দরজা বাঁধা থাকবে। যতদিন সে বেঁচে থাকবে ততদিন তার গায়ে শক্তি থাকবে।”"},{"v":26,"ve":26,"vl":"26","bn":"মূসা বলেছিলেন, “ইসরাইলের আল্লাহ্‌র মত আর কেউ নেই। তোমার সাহায্যকারী হবার জন্য মেঘের উপর চড়ে নিজের মহিমায় তিনি আসমান-পথে চলেন।"},{"v":27,"ve":27,"vl":"27","bn":"যিনি আদিকালের আল্লাহ্‌ তিনিই তোমার আশ্রয়; তাঁর চিরকালের হাতে তিনিই তোমাকে ধরে আছেন। তোমার সামনে যত শত্রু আছে তিনি তাদের তাড়িয়ে দেবেন; তিনি বলবেন, ‘এদের ধ্বংস কর।’"},{"v":28,"ve":28,"vl":"28","bn":"ইসরাইল জাতি তাই নিরাপদে থাকবে। ইয়াকুবের ঝর্ণা থাকবে বিপদ-সীমার বাইরে; সেখানে থাকবে প্রচুর শস্য ও নতুন আংগুর-রস, তার উপরে আকাশের শিশির ঝরে পড়বে।"},{"v":29,"ve":29,"vl":"29","bn":"হে ইসরাইল জাতি, ধন্য তুমি! তুমিই মাবুদের উদ্ধার-করা জাতি, তোমার মত আর কোন জাতি নেই। তিনিই তোমার সাহায্যের ঢাল, তোমার গৌরবের তলোয়ার। শত্রুরা তোমার সামনে থর থর করে কাঁপবে, আর তুমি তাদের পিঠ মাড়িয়ে চলে যাবে।”"}],"34":[{"heading":"হযরত মূসা (আঃ)-এর ইন্তেকাল","v":1,"ve":1,"vl":"1","bn":"এর পর মূসা মোয়াবের সমভূমি থেকে জেরিকোর উল্টাদিকে পিস্‌গা পাহাড়শ্রেণীর মধ্যে সবচেয়ে উঁচু নবো পাহাড়ে উঠে গেলেন। সেখান থেকে মাবুদ তাঁকে গোটা দেশটা দেখালেন। তিনি তাঁকে গিলিয়দ থেকে দান পর্যন্ত সমস্ত জায়গা,"},{"v":2,"ve":2,"vl":"2","bn":"নপ্তালির সমস্ত জায়গা, আফরাহীম ও মানশার জায়গা এবং পশ্চিম দিকে সমুদ্র পর্যন্ত এহুদার সমস্ত জায়গাটা দেখালেন।"},{"v":3,"ve":3,"vl":"3","bn":"এছাড়া তিনি তাঁকে নেগেভ এবং খেজুর-শহর জেরিকো এবং তার কাছের জর্ডান নদীর দক্ষিণ দিকের সমভূমি থেকে সোয়র পর্যন্ত সমস্ত এলাকাটা দেখালেন।"},{"v":4,"ve":4,"vl":"4","bn":"তারপর মাবুদ তাঁকে বললেন, “এই সেই দেশ যা আমি ইব্রাহিম, ইসহাক ও ইয়াকুবের কাছে কসম খেয়ে বলেছিলাম, ‘দেশটা আমি তোমার বংশধরদের দেব।’ দেশটা আমি তোমাকে নিজের চোখে দেখে নেবার সুযোগ দিলাম, কিন্তু নদী পার হয়ে তোমার সেখানে যাওয়া হবে না।”"},{"v":5,"ve":5,"vl":"5","bn":"মাবুদ যা বলেছিলেন সেই অনুসারে মাবুদের গোলাম মূসা ঐ মোয়াব দেশেই ইন্তেকাল করলেন।"},{"v":6,"ve":6,"vl":"6","bn":"মোয়াব দেশের বৈৎ-পিয়োরের কাছে যে উপত্যকা ছিল সেখানে মাবুদই তাঁকে দাফন করলেন, কিন্তু তাঁর কবরটা যে কোথায় তা আজ পর্যন্ত কেউ জানে না।"},{"v":7,"ve":7,"vl":"7","bn":"ইন্তেকাল করবার সময়ে মূসার বয়স ছিল একশো বিশ বছর। তখনও তাঁর দেখবার শক্তি দুর্বল হয় নি কিংবা তাঁর গায়ের জোরও কমে যায় নি।"},{"v":8,"ve":8,"vl":"8","bn":"বনি-ইসরাইলরা মোয়াবের সমভূমিতে ত্রিশ দিন পর্যন্ত মূসার জন্য কান্নাকাটি করেছিল। তারপর তাদের কান্নাকাটি ও শোক-প্রকাশের সময় শেষ হল।"},{"v":9,"ve":9,"vl":"9","bn":"নূনের ছেলে ইউসার উপর মূসা হাত রেখেছিলেন বলে তিনি জ্ঞানদানকারী পাক-রূহে পূর্ণ হয়েছিলেন। সেইজন্য বনি-ইসরাইলরা তাঁর কথামত চলতে লাগল এবং মূসার মধ্য দিয়ে মাবুদ তাদের যে হুকুম দিয়েছিলেন তা পালন করতে লাগল।"},{"v":10,"ve":10,"vl":"10","bn":"আজ পর্যন্ত বনি-ইসরাইলদের মধ্যে মূসার মত আর কোন নবীর জন্ম হয় নি যাঁর কাছে মাবুদ বন্ধুর মত সামনাসামনি কথা বলতেন।"},{"v":11,"ve":11,"vl":"11","bn":"মাবুদ মূসাকে মিসর দেশে ফেরাউন ও তাঁর কর্মচারী এবং তাঁর গোটা দেশের উপর যে সব অলৌকিক চিহ্ন ও কুদরতি দেখাবার জন্য পাঠিয়েছিলেন সেই রকম কাজ আর কেউ করে নি।"},{"v":12,"ve":12,"vl":"12","bn":"সমস্ত বনি-ইসরাইলদের চোখের সামনে মূসা যে মহাশক্তি দেখিয়েছিলেন কিংবা যে সব ভয় জাগানো কাজ করেছিলেন তা আর কেউ কখনও করে নি।"}]}};
